@Override
	protected void read(CompoundTag compound, HolderLookup.Provider registries, boolean clientPacket) {
		super.read(compound, registries, clientPacket);

		if (compound.getBoolean("IsController"))
			controller = worldPosition;

		color = compound.contains("Dye") ? Optional.of(NBTHelper.readEnum(compound, "Dye", DyeColor.class))
			: Optional.empty();

		if (!wasMoved) {
			if (!isController())
				controller = NBTHelper.readBlockPos(compound, "Controller");
			trackerUpdateTag = compound;
			index = compound.getInt("Index");
			beltLength = compound.getInt("Length");
		}

		if (isController())
			getInventory().read(compound.getCompound("Inventory"), registries);

		CasingType casingBefore = casing;
		boolean coverBefore = covered;
		casing = NBTHelper.readEnum(compound, "Casing", CasingType.class);
		covered = compound.getBoolean("Covered");

		if (!clientPacket)
			return;

		if (casingBefore == casing && coverBefore == covered)
			return;
		if (!isVirtual())
			requestModelDataUpdate();
		if (hasLevel())
			level.sendBlockUpdated(getBlockPos(), getBlockState(), getBlockState(), 16);
	}

@Override
	protected void read(CompoundTag compound, HolderLookup.Provider registries, boolean clientPacket) {
		super.read(compound, registries, clientPacket);
		int horizontalDistance = compound.getInt("HorizontalDistance");
		int verticalDistance = compound.getInt("VerticalDistance");

		if (launcher.getHorizontalDistance() != horizontalDistance
			|| launcher.getVerticalDistance() != verticalDistance) {
			launcher.set(horizontalDistance, verticalDistance);
			launcher.clamp(AllConfigs.server().kinetics.maxEjectorDistance.get());
		}

		powered = compound.getBoolean("Powered");
		state = NBTHelper.readEnum(compound, "State", State.class);
		lidProgress.readNBT(compound.getCompound("Lid"), false);
		launchedItems = NBTHelper.readCompoundList(compound.getList("LaunchedItems", Tag.TAG_COMPOUND),
			nbt -> IntAttached.read(nbt, t -> ItemStack.parseOptional(registries, t)));

		earlyTarget = null;
		earlyTargetTime = 0;
		if (compound.contains("EarlyTarget")) {
			earlyTarget = Pair.of(VecHelper.readNBT(compound.getList("EarlyTarget", Tag.TAG_DOUBLE)),
					NBTHelper.readBlockPos(compound, "EarlyTargetPos"));
			earlyTargetTime = compound.getFloat("EarlyTargetTime");
		}

		if (compound.contains("ForceAngle"))
			lidProgress.startWithValue(compound.getFloat("ForceAngle"));
	}

@Override
	public void read(CompoundTag nbt, HolderLookup.Provider registries, boolean clientPacket) {
		CompoundTag panelTag = nbt.getCompound(CreateLang.asId(slot.name()));
		if (panelTag.isEmpty()) {
			active = false;
			return;
		}

		active = true;
		filter = FilterItemStack.of(registries, panelTag.getCompound("Filter"));
		count = panelTag.getInt("FilterAmount");
		upTo = panelTag.getBoolean("UpTo");
		timer = panelTag.getInt("Timer");
		lastReportedLevelInStorage = panelTag.getInt("LastLevel");
		lastReportedPromises = panelTag.getInt("LastPromised");
		lastReportedUnloadedLinks = panelTag.getInt("LastUnloadedLinks");
		satisfied = panelTag.getBoolean("Satisfied");
		promisedSatisfied = panelTag.getBoolean("PromisedSatisfied");
		waitingForNetwork = panelTag.getBoolean("Waiting");
		redstonePowered = panelTag.getBoolean("RedstonePowered");
		promiseClearingInterval = panelTag.getInt("PromiseClearingInterval");
		if (panelTag.hasUUID("Freq"))
			network = panelTag.getUUID("Freq");

		targeting.clear();
		targeting.addAll(CatnipCodecUtils.decode(CatnipCodecs.set(FactoryPanelPosition.CODEC), registries, panelTag.get("Targeting")).orElse(Set.of()));

		targetedBy.clear();
		CatnipCodecUtils.decode(Codec.list(FactoryPanelConnection.CODEC), registries, panelTag.get("TargetedBy")).orElse(List.of())
			.forEach(c -> targetedBy.put(c.from, c));

		targetedByLinks.clear();
		CatnipCodecUtils.decode(Codec.list(FactoryPanelConnection.CODEC), registries, panelTag.get("TargetedByLinks")).orElse(List.of())
			.forEach(c -> targetedByLinks.put(c.from.pos(), c));

		activeCraftingArrangement = NBTHelper.readItemList(panelTag.getList("Craft", Tag.TAG_COMPOUND), registries);
		recipeAddress = panelTag.getString("RecipeAddress");
		recipeOutput = panelTag.getInt("RecipeOutput");

		if (nbt.getBoolean("Restocker") && !clientPacket) {
			restockerPromises = RequestPromiseQueue.read(panelTag.getCompound("Promises"), registries, () -> {
			});
			promisePrimedForMarkDirty = false;
		}
	}

public static RequestPromiseQueue read(CompoundTag tag, HolderLookup.Provider registries, Runnable onChanged) {
		RequestPromiseQueue queue = new RequestPromiseQueue(onChanged);
		List<RequestPromise> promises = CatnipCodecUtils.decode(Codec.list(RequestPromise.CODEC), registries, tag.get("List")).orElse(List.of());
		for (RequestPromise promise : promises) {
			queue.add(promise);
		}
		return queue;
	}

