public void loadInventoryConfiguration() {
    Map<ISlotType, ICurioStacksHandler> defaultInventory = this.createDefaultInventory();
    SortedMap<ISlotType, ICurioStacksHandler> sortedCurios = new TreeMap<>(defaultInventory);

    for (Map.Entry<String, ICurioStacksHandler> entry : this.curios.entrySet()) {
      String id = entry.getKey();
      ISlotType slotType = CuriosSlotTypes.getSlotType(id, this.owner.level().isClientSide());
      ICurioStacksHandler prevStacksHandler = entry.getValue();

      if (slotType != null && defaultInventory.containsKey(slotType)) {
        ICurioStacksHandler curioStacksHandler = defaultInventory.get(slotType);
        int defaultSize = curioStacksHandler.getSlots();
        int oldSize = prevStacksHandler.getSlots();
        curioStacksHandler.copyModifiers(prevStacksHandler);

        if (oldSize != defaultSize) {
          curioStacksHandler.addTransientModifier(
              new AttributeModifier(SIZE_SHIFT, oldSize - defaultSize,
                  AttributeModifier.Operation.ADD_VALUE));
        }
        int index = 0;

        while (index < curioStacksHandler.getSlots() && index < prevStacksHandler.getSlots()) {
          ItemStack prevStack = prevStacksHandler.getStacks().getStackInSlot(index);

          if (!prevStack.isEmpty()) {

            if (curioStacksHandler.getStacks().isItemValid(index, prevStack)) {
              curioStacksHandler.getStacks().setStackInSlot(index, prevStack);
            } else {
              this.invalidStacks.add(prevStack);
            }
          }
          ItemStack prevCosmetic =
              prevStacksHandler.getCosmeticStacks().getStackInSlot(index);

          if (!prevCosmetic.isEmpty()) {

            if (curioStacksHandler.getStacks().isItemValid(index, prevCosmetic)) {
              curioStacksHandler
                  .getCosmeticStacks()
                  .setStackInSlot(
                      index, prevStacksHandler.getCosmeticStacks().getStackInSlot(index));
            } else {
              this.invalidStacks.add(prevCosmetic);
            }
          }
          index++;
        }

        while (index < prevStacksHandler.getSlots()) {
          this.invalidStacks.add(prevStacksHandler.getStacks().getStackInSlot(index));
          this.invalidStacks.add(prevStacksHandler.getCosmeticStacks().getStackInSlot(index));
          index++;
        }
        sortedCurios.put(slotType, curioStacksHandler);

        for (int j = 0;
             j < curioStacksHandler.getRenders().size()
                 && j < prevStacksHandler.getRenders().size();
             j++) {
          curioStacksHandler.getRenders().set(j, prevStacksHandler.getRenders().get(j));
        }

        for (int j = 0;
             j < curioStacksHandler.getActiveStates().size()
                 && j < prevStacksHandler.getActiveStates().size();
             j++) {
          curioStacksHandler.getActiveStates()
              .set(j, prevStacksHandler.getActiveStates().get(j));
        }
      } else {
        IDynamicStackHandler stackHandler = prevStacksHandler.getStacks();
        IDynamicStackHandler cosmeticStackHandler = prevStacksHandler.getCosmeticStacks();

        for (int j = 0; j < stackHandler.getSlots(); j++) {
          ItemStack stack = stackHandler.getStackInSlot(j);

          if (!stack.isEmpty()) {
            this.invalidStacks.add(stack);
          }

          ItemStack cosmeticStack = cosmeticStackHandler.getStackInSlot(j);

          if (!cosmeticStack.isEmpty()) {
            this.invalidStacks.add(cosmeticStack);
          }
        }
      }
    }
    this.curios.clear();

    for (Map.Entry<ISlotType, ICurioStacksHandler> entry : sortedCurios.entrySet()) {
      ICurioStacksHandler stacksHandler = entry.getValue();

      if (stacksHandler instanceof CurioStacksHandler curioStacksHandler) {
        curioStacksHandler.setDataLoaded();
      }
      this.curios.put(entry.getKey().getId(), stacksHandler);
    }
  }

@Override
  public void deserialize(@Nonnull ValueInput valueInput) {
    this.curios.clear();
    ValueInput.ValueInputList list = valueInput.childrenListOrEmpty(CURIOS_KEY);

    if (list.isEmpty()) {
      this.resetInventory();
      return;
    }
    list.forEach(input -> {

      for (String id : input.keySet()) {

        if (!id.isEmpty()) {
          ICurioStacksHandler stacks = new CurioStacksHandler(this, id);
          stacks.deserialize(input.childOrEmpty(id));
          this.curios.put(id, stacks);
        }
      }
    });
  }

public void deserialize(NBTTagCompound nbt) {	
		if (nbt == null) return;	
		inspiration = nbt.getInteger("inspiration");
		inspirationStart = nbt.getInteger("inspirationStart");
		placedCards = nbt.getInteger("placedCards");
		bonusDraws = nbt.getInteger("bonusDraws");
		aidsChosen = nbt.getInteger("aidsChosen");
		penaltyStart = nbt.getInteger("penaltyStart");
		player=nbt.getString("player");

		//
		NBTTagList savedTag = nbt.getTagList("savedCards", (byte)10);
		savedCards = new ArrayList<Long>();
		for (int x=0;x<savedTag.tagCount();x++) {
			NBTTagCompound nbtdata = (NBTTagCompound) savedTag.getCompoundTagAt(x);
			savedCards.add(nbtdata.getLong("card"));
		}

		//
		NBTTagList categoriesBlockedTag = nbt.getTagList("categoriesBlocked", (byte)10);
		categoriesBlocked = new ArrayList<String>();
		for (int x=0;x<categoriesBlockedTag.tagCount();x++) {
			NBTTagCompound nbtdata = (NBTTagCompound) categoriesBlockedTag.getCompoundTagAt(x);
			categoriesBlocked.add(nbtdata.getString("category"));
		}

		//
		NBTTagList categoryTotalsTag = nbt.getTagList("categoryTotals", (byte)10);
		categoryTotals = new TreeMap<String,Integer>();
		for (int x=0;x<categoryTotalsTag.tagCount();x++) {
			NBTTagCompound nbtdata = (NBTTagCompound) categoryTotalsTag.getCompoundTagAt(x);
			categoryTotals.put(nbtdata.getString("category"), nbtdata.getInteger("total"));
		}

		//
		NBTTagList aidCardsTag = nbt.getTagList("aidCards", (byte)10);
		aidCards = new ArrayList<String>();
		for (int x=0;x<aidCardsTag.tagCount();x++) {
			NBTTagCompound nbtdata = (NBTTagCompound) aidCardsTag.getCompoundTagAt(x);
			aidCards.add(nbtdata.getString("aidCard"));
		}

		//

		EntityPlayer pe = null;		
		if (this.table!=null && table.getWorld()!=null && !table.getWorld().isRemote) 
			pe = this.table.getWorld().getPlayerEntityByName(player);

		NBTTagList cardChoicesTag = nbt.getTagList("cardChoices", (byte)10);
		cardChoices = new ArrayList<CardChoice>();
		for (int x=0;x<cardChoicesTag.tagCount();x++) {			
			NBTTagCompound nbtdata = (NBTTagCompound) cardChoicesTag.getCompoundTagAt(x);			
			CardChoice cc = deserializeCardChoice(nbtdata);
			if (cc!=null) cardChoices.add(cc);
		}

		lastDraw = deserializeCardChoice(nbt.getCompoundTag("lastDraw"));

	}

public CardChoice deserializeCardChoice(NBTTagCompound nbt) {	
		if (nbt == null) return null;	
		String key = nbt.getString("cardChoice");			
		TheorycraftCard tc=generateCardWithNBT(nbt.getString("cardChoice"), nbt.getCompoundTag("cardNBT"));				
		if (tc==null) return null;
		return new CardChoice(key,tc,nbt.getBoolean("aid"),nbt.getBoolean("select"));
	}

@Override
            public MapType convert(final MapType data, final long sourceVersion, final long toVersion) {
                final String id = data.getString("id");
                final String boatType = BOAT_TYPES_BY_ITEM_ID.get(id);

                if (boatType == null) {
                    return null;
                }

                final MapType components = data.getMap("components");
                if (components == null) {
                    return null;
                }

                final MapType entityData = components.getMap("minecraft:entity_data");
                if (entityData == null) {
                    return null;
                }

                entityData.setString("Type", boatType);

                return null;
            }

@Override
            public MapType convert(final MapType data, final long sourceVersion, final long toVersion) {
                final String id = data.getString("id");
                if (id == null) {
                    // wat
                    return null;
                }

                final boolean normalBoat = id.equals("minecraft:boat");
                final boolean chestBoat = id.equals("minecraft:chest_boat");

                if (!normalBoat && !chestBoat) {
                    return null;
                }

                final String type = data.getString("Type");
                data.remove("Type");

                if (normalBoat) {
                    data.setString("id", NORMAL_REMAPPING.getOrDefault(type, "minecraft:oak_boat"));
                } else {
                    data.setString("id", CHEST_REMAPPING.getOrDefault(type, "minecraft:oak_chest_boat"));
                }

                return null;
            }

@Override
            public MapType convert(final MapType data, final long sourceVersion, final long toVersion) {
                RenameHelper.renameSingle(data.getMap("minecraft:equippable"), "model", "asset_id");

                final Number modelData = data.getNumber("minecraft:custom_model_data");
                if (modelData != null) {
                    final TypeUtil<?> typeUtil = data.getTypeUtil();

                    final MapType newModelData = typeUtil.createEmptyMap();
                    data.setMap("minecraft:custom_model_data", newModelData);

                    final ListType floats = typeUtil.createEmptyList();
                    newModelData.setList("floats", floats);

                    floats.addFloat(modelData.floatValue());
                }

                return null;
            }

@Override
	public void deserializeNBT(NBTTagCompound nbt) {
		if (nbt == null) return;

		wasTamperedWith = NBTHelper.getBoolean(nbt, "tampered_with", wasTamperedWith);

		isDepressed = NBTHelper.getBoolean(nbt, "depressed", isDepressed);

		primaryColor = new Color(NBTHelper.getInteger(nbt, "primary_color", 0xFFFFFF));

		secondaryColor = new Color(NBTHelper.getInteger(nbt, "secondary_color", 0xFFFFFF));

		age = NBTHelper.getInteger(nbt, "age", age);

		owner = NBTHelper.getUniqueId(nbt, "owner_id");

		if (nbt.hasKey("mana_capability"))
			handler.deserializeNBT(NBTHelper.getCompoundTag(nbt, "mana_capability"));

		infusedSpell.clear();
		NBTTagList list = NBTHelper.getTagList(nbt, "infused_spell", Constants.NBT.TAG_COMPOUND);
		if (list != null) {
			for (NBTBase base : list) {
				if (base instanceof NBTTagCompound) {
					NBTTagCompound compound = (NBTTagCompound) base;

					SpellRing ring = SpellRing.deserializeRing(compound);
					infusedSpell.add(ring);
				}
			}
		}
	}

