@Override
    public final double injectAEPower(double amt, Actionable mode) {
        var inserted = this.stored.insert(amt, mode == Actionable.MODULATE);
        if (mode == Actionable.MODULATE && inserted > 0) {
            this.onAmountChanged();
        }
        return amt - inserted;
    }

@Override
    public final double extractAEPower(double amt, Actionable mode, PowerMultiplier pm) {
        return pm.divide(this.extractAEPower(pm.multiply(amt), mode));
    }

private double extractAEPower(double amt, Actionable mode) {
        var extracted = this.stored.extract(amt, mode == Actionable.MODULATE);
        if (mode == Actionable.MODULATE && extracted > 0) {
            this.onAmountChanged();
        }
        return extracted;
    }

@Override
    public TickRateModulation tickingRequest(IGridNode node, int ticksSinceLastCall) {
        if (Platform.areBlockEntitiesTicking(getLevel(), getBlockPos())) {
            if (neighborChangePending) {
                neighborChangePending = false;
                setChanged(); // update comparators
                updateStateForPowerLevel(); // and update block state
            }
            return TickRateModulation.SLEEP;
        } else {
            return TickRateModulation.IDLE;
        }
    }

public double insert(double amount, boolean commit) {
        if (amount < MIN_AMOUNT) {
            return 0; // This also prevents negative insertion
        }

        double inserted = Math.min(amount, maximum - stored);
        if (commit) {
            setStored(stored + inserted);
        }
        return inserted;
    }

public double extract(double amount, boolean commit) {
        if (amount < MIN_AMOUNT) {
            return 0; // This also prevents negative extraction
        }

        double extracted = Math.min(amount, this.stored);
        if (commit) {
            setStored(stored - extracted);
        }
        return extracted;
    }

public void setStored(double amount) {
        if (amount < MIN_AMOUNT) {
            amount = 0;
        }
        this.stored = Mth.clamp(amount, 0, maximum);

        sendEvents();
    }

@Override
    public double extractAEPower(double amt, Actionable mode, PowerMultiplier pm) {
        final double toExtract = pm.multiply(amt);
        double extracted = 0;

        for (EnergyService service : getConnectedServices()) {
            extracted += service.extractProviderPower(toExtract - extracted, mode);

            if (extracted >= toExtract) {
                break;
            }
        }

        return pm.divide(extracted);
    }

public double extractProviderPower(double amt, Actionable mode) {
        Preconditions.checkArgument(amt >= 0, "amt must be >= 0");

        double extractedPower = 0;

        final Iterator<IAEPowerStorage> it = this.providers.iterator();

        ongoingExtractOperation = true;
        try {
            while (extractedPower < amt && it.hasNext()) {
                final IAEPowerStorage node = it.next();

                final double req = amt - extractedPower;
                final double newPower = node.extractAEPower(req, mode, PowerMultiplier.ONE);
                extractedPower += newPower;

                if (newPower < req && mode == Actionable.MODULATE) {
                    it.remove();
                }
            }
        } finally {
            ongoingExtractOperation = false;
        }

        final double result = Math.min(extractedPower, amt);

        if (mode == Actionable.MODULATE) {
            // Be nice and try to push returned excess to the grid storage
            if (extractedPower > amt) {
                this.localStorage.injectAEPower(extractedPower - amt, Actionable.MODULATE);
            }

            this.globalAvailablePower -= result;
            this.tickDrainPerTick += result;
        }

        return result;
    }

public double injectProviderPower(double amt, Actionable mode) {
        Preconditions.checkArgument(amt >= 0, "amt must be >= 0");

        final double originalAmount = amt;

        var it = this.requesters.iterator();

        ongoingInjectOperation = true;
        try {
            while (amt > 0 && it.hasNext()) {
                final IAEPowerStorage node = it.next();
                amt = node.injectAEPower(amt, mode);

                if (amt > 0 && mode == Actionable.MODULATE) {
                    it.remove();
                }
            }
        } finally {
            ongoingInjectOperation = false;
        }

        final double overflow = Math.max(0.0, amt);

        if (mode == Actionable.MODULATE) {
            this.tickInjectionPerTick += originalAmount - overflow;
        }

        return overflow;
    }

private void addRequester(IAEPowerStorage requester) {
        Preconditions.checkState(!ongoingInjectOperation,
                "Cannot modify energy requesters while energy is being injected.");
        if (requester.getPowerFlow().isAllowInsertion()) {
            this.requesters.add(requester);
        }
    }

private void addProvider(IAEPowerStorage provider) {
        Preconditions.checkState(!ongoingExtractOperation,
                "Cannot modify energy providers while energy is being extracted.");
        if (provider.getPowerFlow().isAllowExtraction()) {
            this.providers.add(provider);
        }
    }

@Override
    public double injectAEPower(ItemStack is, double amount, Actionable mode) {
        final double internalCurrentPower = getAECurrentPower(is);
        final double internalMaxPower = this.getAEMaxPower(is);
        final double required = internalMaxPower - internalCurrentPower;
        final double overflow = Math.max(0, Math.min(amount - required, amount));

        if (mode == Actionable.MODULATE) {
            final double toAdd = Math.min(required, amount);
            final double newPowerStored = internalCurrentPower + toAdd;

            setAECurrentPower(is, newPowerStored);
        }

        return overflow;
    }

@Override
    public double extractAEPower(ItemStack is, double amount, Actionable mode) {
        final double internalCurrentPower = getAECurrentPower(is);
        final double fulfillable = Math.min(amount, internalCurrentPower);

        if (mode == Actionable.MODULATE) {
            final double newPowerStored = internalCurrentPower - fulfillable;

            setAECurrentPower(is, newPowerStored);
        }

        return fulfillable;
    }

@Override
    public void setPlacedBy(Level level, BlockPos pos, BlockState state, @Nullable LivingEntity placer,
            ItemStack is) {
        // Inherit the item stack's display name, but only if it's a user defined string rather than a translation
        // component, since our custom naming cannot handle untranslated I18N strings and we would translate it using
        // the server's locale :-(
        var blockEntity = this.getBlockEntity(level, pos);

        if (blockEntity == null) {
            return;
        }

        if (blockEntity instanceof IOwnerAwareBlockEntity ownerAware && placer instanceof Player player) {
            ownerAware.setOwner(player);
        }

        var hoverName = is.getHoverName();
        if (hoverName.getContents() instanceof PlainTextContents text) {
            blockEntity.setName(text.text());
        }

        Player player = null;
        if (placer instanceof Player) {
            player = (Player) placer;
        }
        blockEntity.importSettings(SettingsFrom.DISMANTLE_ITEM, is.getComponents(), player);
    }

@Override
    public List<ItemStack> getDrops(BlockState state, LootParams.Builder builder) {
        var drops = super.getDrops(state, builder);
        for (var drop : drops) {
            if (drop.getItem() instanceof BlockItem blockItem && blockItem.getBlock() == this) {
                builder = builder.withParameter(LootContextParams.BLOCK_STATE, state);
                var be = builder.getOptionalParameter(LootContextParams.BLOCK_ENTITY);
                if (be instanceof AEBaseBlockEntity aeBaseBlockEntity) {
                    var looter = builder.getOptionalParameter(LootContextParams.THIS_ENTITY);
                    Player player = null;
                    if (looter instanceof Player) {
                        player = (Player) looter;
                    }

                    var settings = aeBaseBlockEntity.exportSettings(SettingsFrom.DISMANTLE_ITEM, player);
                    drop.applyComponents(settings);
                }
                // Export settings at most for one item
                break;
            }
        }
        return drops;
    }

