public static byte[] unpackOffsets(int packed) {
        byte[] offsets = new byte[4];
        for (int i = 0; i < 4; i++) {
            offsets[i] = (byte) (packed >> (i * 5) & 0x1F);
        }
        return offsets;
    }

@Override
    protected void collectMiscComponents(DataComponentMap.Builder builder) {
        builder.set(FBContent.DC_TYPE_COLLAPSIBLE_BLOCK_DATA, new CollapsibleBlockData(packedOffsets));

        BlockState state = getBlockState();
        BlockItemStateProperties stateProperties = BlockItemStateProperties.EMPTY
                .with(PropertyHolder.NULLABLE_FACE, state)
                .with(PropertyHolder.ROTATE_SPLIT_LINE, state);
        builder.set(DataComponents.BLOCK_STATE, stateProperties);
    }

@Override
    protected void applyMiscComponents(DataComponentGetter input) {
        CollapsibleBlockData blockData = input.get(FBContent.DC_TYPE_COLLAPSIBLE_BLOCK_DATA);
        if (blockData != null) {
            packedOffsets = blockData.offsets();
        }
    }

@Override
    protected VoxelShape getShape(BlockState state, BlockGetter level, BlockPos pos, CollisionContext ctx) {
        if (isIntangible(state, level, pos, ctx)) {
            return Shapes.empty();
        }

        NullableDirection face = state.getValue(PropertyHolder.NULLABLE_FACE);
        if (face != NullableDirection.NONE) {
            if (level.getBlockEntity(pos) instanceof FramedCollapsibleBlockEntity be) {
                int offsets = be.getPackedOffsets(state);
                offsets |= (face.toDirection().get3DDataValue() << 20);
                return SHAPE_CACHE.computeIfAbsent(offsets, FramedCollapsibleBlock::buildShape);
            }
        }
        return Shapes.block();
    }

private static PaintRollerContents deserialize(Optional<Holder<BlockOverlay>> overlay, int count) {
        return overlay.isEmpty() ? NO_OVERLAY : new PaintRollerContents(overlay.get(), count);
    }

public PaintRollerContents insert(BlockOverlayCache cache, ItemStack stack) {
        if (stack.isEmpty()) {
            return this;
        }

        Holder<BlockOverlay> overlay;
        int count;
        if (this.overlay != null) {
            if (!stack.is(sourceItem())) {
                return this;
            }

            overlay = this.overlay;
            count = this.count;
        } else {
            overlay = cache.getOverlay(stack.getItem());
            count = 0;
        }
        int diff = Math.min(stack.getCount(), MAX_COUNT - count);
        stack.shrink(diff);
        return new PaintRollerContents(overlay, count + diff);
    }

public PaintRollerContents extract(SlotAccess output) {
        if (overlay == null) {
            return this;
        }

        Item srcItem = sourceItem();
        int outCount = Math.min(count, srcItem.getDefaultMaxStackSize());
        if (outCount > 0) {
            output.set(new ItemStack(srcItem, outCount));
        }
        int finalCount = count - outCount;
        Holder<BlockOverlay> overlay = finalCount == 0 ? null : this.overlay;
        return new PaintRollerContents(overlay, finalCount);
    }

public PaintRollerContents shrink() {
        int newCount = Math.max(count - 1, 0);
        return new PaintRollerContents(overlay, newCount);
    }

@Override
    public @NotNull InteractionResult useOn(UseOnContext context) {
        if (context.getClickedFace() != Direction.UP)
            return InteractionResult.FAIL;
        ItemStack stack = context.getItemInHand();
        if (stack.getTag() != null && !stack.getTag().getString("DragonHornEntityID").isEmpty()) {
            Level world = context.getLevel();
            String id = stack.getTag().getString("DragonHornEntityID");
            EntityType type = EntityType.byString(id).orElse(null);
            if (type != null) {
                Entity entity = type.create(world);
                if (entity instanceof EntityDragonBase) {
                    EntityDragonBase dragon = (EntityDragonBase) entity;
                    dragon.load(stack.getTag().getCompound("EntityTag"));
                }
                //Still needed to allow for intercompatibility
                if (stack.getTag().contains("EntityUUID"))
                    entity.setUUID(stack.getTag().getUUID("EntityUUID"));

                entity.absMoveTo(context.getClickedPos().getX() + 0.5D, (context.getClickedPos().getY() + 1), context.getClickedPos().getZ() + 0.5D, 180 + (context.getHorizontalDirection()).toYRot(), 0.0F);
                if (world.addFreshEntity(entity)) {
                    CompoundTag tag = stack.getTag();
                    tag.remove("DragonHornEntityID");
                    tag.remove("EntityTag");
                    tag.remove("EntityUUID");
                    stack.setTag(tag);
                }
            }
        }
        return InteractionResult.SUCCESS;
    }

@Override
    public @NotNull InteractionResult interactLivingEntity(@NotNull ItemStack stack, Player playerIn, @NotNull LivingEntity target, @NotNull InteractionHand hand) {
        ItemStack trueStack = playerIn.getItemInHand(hand);
        if (!playerIn.level.isClientSide && hand == InteractionHand.MAIN_HAND && target instanceof EntityDragonBase && ((EntityDragonBase) target).isOwnedBy(playerIn) && (trueStack.getTag() == null || (trueStack.getTag() != null && trueStack.getTag().getCompound("EntityTag").isEmpty()))) {
            CompoundTag newTag = new CompoundTag();

            CompoundTag entityTag = new CompoundTag();
            target.save(entityTag);
            newTag.put("EntityTag", entityTag);

            newTag.putString("DragonHornEntityID", Registry.ENTITY_TYPE.getKey(target.getType()).toString());
            trueStack.setTag(newTag);

            playerIn.swing(hand);
            playerIn.level.playSound(playerIn, playerIn.blockPosition(), SoundEvents.ZOMBIE_VILLAGER_CONVERTED, SoundSource.NEUTRAL, 3.0F, 0.75F);
            target.remove(Entity.RemovalReason.DISCARDED);
            return InteractionResult.SUCCESS;
        }

        return InteractionResult.FAIL;
    }

