public IafWorldData load(final CompoundTag tag) {
        FeatureType[] types = FeatureType.values();

        for (FeatureType type : types) {
            ListTag list = tag.getList(type.toString(), ListTag.TAG_COMPOUND);

            for (int i = 0; i < list.size(); i++) {
                CompoundTag entry = list.getCompound(i);
                String id = entry.getString("id");
                BlockPos position = NbtUtils.readBlockPos(entry.getCompound("position"));
                LAST_GENERATED.computeIfAbsent(type, key -> new ArrayList<>()).add(Pair.of(id, position));
            }
        }

        return this;
    }

public static IafWorldData get(final Level world) {
        if (world instanceof ServerLevel) {
            ServerLevel overworld = world.getServer().getLevel(world.dimension());
            DimensionDataStorage storage = overworld.getDataStorage();
            IafWorldData data = storage.computeIfAbsent(IafWorldData::new, IafWorldData::new, IDENTIFIER);
            data.setDirty();

            return data;
        }

        return null;
    }

public boolean check(final FeatureType type, final BlockPos position, final String id) {
        List<Pair<String, BlockPos>> entries = LAST_GENERATED.computeIfAbsent(type, key -> new ArrayList<>());

        boolean canGenerate = true;
        Pair<String, BlockPos> toRemove = null;

        for (Pair<String, BlockPos> entry : entries) {
            if (entry.getFirst().equals(id)) {
                toRemove = entry;
            }

            canGenerate = position.distSqr(entry.getSecond()) > IafConfig.dangerousWorldGenSeparationLimit * IafConfig.dangerousWorldGenSeparationLimit;
        }

        if (toRemove != null) {
            entries.remove(toRemove);
        }

        entries.add(Pair.of(id, position));

        return canGenerate;
    }

@Override
    public @NotNull CompoundTag save(@NotNull final CompoundTag tag) {
        LAST_GENERATED.forEach((key, value) -> {
            ListTag listTag = new ListTag();

            value.forEach(entry -> {
                CompoundTag subTag = new CompoundTag();
                subTag.putString("id", entry.getFirst());
                subTag.put("position", NbtUtils.writeBlockPos(entry.getSecond()));

                listTag.add(subTag);
            });

            tag.put(key.toString(), listTag);
        });

        return tag;
    }

private static void readStorageContents(CompoundTag nbt, ItemContentsStorage storage) {
		ListTag storageContents = nbt.getList(nbt.contains("shulkerBoxContents") ? "shulkerBoxContents" : "storageContents", Tag.TAG_COMPOUND);
		for (Tag n : storageContents) {
			CompoundTag uuidContentsPair = (CompoundTag) n;
			UUID uuid = NbtUtils.loadUUID(Objects.requireNonNull(uuidContentsPair.get("uuid")));
			CompoundTag contents = uuidContentsPair.getCompound("contents");
			LegacyStorageBlockDataMigration.normalizeStorageContents(contents);
			storage.storageContents.put(uuid, contents);
		}
	}

public static ItemContentsStorage get() {
		if (Thread.currentThread().getThreadGroup() == SidedThreadGroups.SERVER) {
			MinecraftServer server = ServerLifecycleHooks.getCurrentServer();
			if (server != null) {
				ServerLevel overworld = server.getLevel(Level.OVERWORLD);
				// noinspection ConstantConditions - by this time overworld is loaded
				DimensionDataStorage storage = overworld.getDataStorage();
				return storage.computeIfAbsent(new Factory<>(ItemContentsStorage::new, ItemContentsStorage::load), SAVED_DATA_NAME);
			}
		}
		return clientStorageCopy;
	}

public static ItemContentsStorage load(CompoundTag nbt, HolderLookup.Provider registries) {
		ItemContentsStorage storage = new ItemContentsStorage();
		readStorageContents(nbt, storage);
		return storage;
	}

private void writeStorageContents(CompoundTag ret) {
		ListTag storageContentsNbt = new ListTag();
		for (Map.Entry<UUID, CompoundTag> entry : storageContents.entrySet()) {
			CompoundTag uuidContentsPair = new CompoundTag();
			uuidContentsPair.put("uuid", NbtUtils.createUUID(entry.getKey()));
			uuidContentsPair.put("contents", entry.getValue());
			storageContentsNbt.add(uuidContentsPair);
		}
		ret.put("storageContents", storageContentsNbt);
	}

@Override
	public void setPlacedBy(Level level, BlockPos pos, BlockState state, @Nullable LivingEntity placer, ItemStack stack) {
		if (level.isClientSide()) {
			WorldHelper.getBlockEntity(level, pos, WoodStorageBlockEntity.class).ifPresent(be -> setRenderBlockRenderProperties(stack, be));
			return;
		}
		ServerLevel serverLevel = (ServerLevel) level;

		WorldHelper.getBlockEntity(level, pos, WoodStorageBlockEntity.class).ifPresent(be -> {
			LegacyStorageBlockDataMigration.normalizeLegacyData(stack);
			UUID storageUuid = stack.get(ModCoreDataComponents.STORAGE_UUID);
			if (storageUuid != null && !StorageBlockEntity.hasLinkedStorageEndpoint(stack)) {
				ItemContentsStorage itemContentsStorage = ItemContentsStorage.get();
				if (itemContentsStorage.has(storageUuid)) {
					be.setBeingUpgraded(true);
					be.loadAdditional(itemContentsStorage.getOrCreateStorageContents(storageUuid), level.registryAccess());
					itemContentsStorage.removeStorageContents(storageUuid);
					setNewSize(stack, be);
					setTicking(level, pos, state, !be.getStorageWrapper().getUpgradeHandler().getWrappersThatImplement(ITickableUpgrade.class).isEmpty());
				} else {
					SophisticatedStorage.LOGGER
							.error("No storage contents found for uuid: " + storageUuid + " when placing " + stack.getHoverName().getString());
				}
			}

			if (stack.has(DataComponents.CUSTOM_NAME) && (!StorageBlockEntity.hasLinkedStorageEndpoint(stack)
					|| StorageBlockEntity.getLinkedStorageEndpointRole(stack).orElse(null) == LinkedStorageEndpointRole.PRIMARY)) {
				be.setCustomName(stack.getHoverName());
			}
			if (stack.has(DataComponents.CUSTOM_NAME)
					&& StorageBlockEntity.getLinkedStorageEndpointRole(stack).orElse(null) == LinkedStorageEndpointRole.PRIMARY) {
				StorageLinkedStorageEndpointAdapter.synchronizePrimaryCarrier(serverLevel, stack);
			}
			setRenderBlockRenderProperties(stack, be);
			boolean restoredLinkedStorage = !StorageBlockEntity.hasLinkedStorageEndpoint(stack);
			if (shouldRestoreLinkedStorageEndpoint(stack) && !restoredLinkedStorage) {
				if (placer instanceof Player player && player.getAbilities().instabuild && StorageBlockEntity.hasLinkedStorageEndpoint(stack)) {
					restoredLinkedStorage = be.restoreCreativeLinkedStorageEndpoint(serverLevel, stack);
				} else {
					restoredLinkedStorage = be.restoreLinkedStorageEndpoint(serverLevel, stack);
				}
			}

			be.getStorageWrapper().onInit(level);
			if (restoredLinkedStorage) {
				be.tryToAddToController();
			}

			if (placer != null && placer.getOffhandItem().getItem() == ModItems.STORAGE_TOOL.get()) {
				StorageToolItem.useOffHandOnPlaced(placer.getOffhandItem(), be);
			}
			be.setBeingUpgraded(false);
		});
	}

