@Override
	public void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
		super.loadAdditional(tag, registries);
		if (!isBeingUpgraded() && getBlockState().getValue(ChestBlock.TYPE) == ChestType.SINGLE) {
			if (getBlockState().getBlock() instanceof ChestBlock chestBlock
					&& getStorageWrapper().getInventoryHandler().getSlots() > chestBlock.getNumberOfInventorySlots()) {
				dropSecondPartContents(chestBlock, worldPosition);
			}
		}
	}

public void dropSecondPartContents(ChestBlock chestBlock, BlockPos dropPosition) {
		if (isLinkedStorage()) {
			return;
		}
		InventoryHandler invHandler = getStorageWrapper().getInventoryHandler();

		List<ItemStack> dropItems = new ArrayList<>();

		for (int slot = chestBlock.getNumberOfInventorySlots(); slot < invHandler.getSlots(); slot++) {
			ItemStack slotStack = invHandler.getSlotStack(slot);

			if (!slotStack.isEmpty()) {
				dropItems.add(slotStack.copy());
				invHandler.setStackInSlot(slot, ItemStack.EMPTY);
			}
		}

		if (level instanceof ServerLevel serverLevel) {
			serverLevel.getServer().tell(new TickTask(serverLevel.getServer().getTickCount(), () -> dropItems
					.forEach(itemStack -> Containers.dropItemStack(serverLevel, dropPosition.getX(), dropPosition.getY(), dropPosition.getZ(), itemStack))));
		}

		int inventorySlotDiff = chestBlock.getNumberOfInventorySlots() - invHandler.getSlots();

		changeStorageSize(inventorySlotDiff, 0);
		deleteSettingsFromSlot(this, chestBlock.getNumberOfInventorySlots());
		getStorageWrapper().getSettingsHandler().getTypeCategory(ItemDisplaySettingsCategory.class).setDisplaySide(DisplaySide.FRONT);
		getStorageWrapper().getUpgradeHandler().refreshUpgradeWrappers();
		WorldHelper.notifyBlockUpdate(this);
	}

private StorageBlockEntity upgradeStorageBlock(BlockPos pos, Level level, StorageBlockEntity blockEntity, BlockState newBlockState,
				int newInventorySize, int newUpgradeSize) {
			CompoundTag beTag = new CompoundTag();
			blockEntity.saveAdditional(beTag, level.registryAccess());

			StorageBlockEntity newBlockEntity = newBlock().newBlockEntity(pos, newBlockState);
			// noinspection ConstantConditions - all storage blocks create a block entity so no chancde of null here
			newBlockEntity.setBeingUpgraded(true);
			newBlockEntity.loadAdditional(beTag, level.registryAccess());

			blockEntity.setBeingUpgraded(true);
			blockEntity.closeMenusForThisBlock();
			level.removeBlockEntity(pos);
			level.removeBlock(pos, false);

			level.setBlock(pos, newBlockState, 3);
			level.setBlockEntity(newBlockEntity);
			if (newBlockEntity.isLinkedStorage() && level instanceof ServerLevel serverLevel) {
				if (!newBlockEntity.completePrimaryLinkedStorageTierUpgrade(serverLevel, newInventorySize, newUpgradeSize)) {
					throw new IllegalStateException("Could not update linked storage capacity after a primary tier upgrade");
				}
			} else {
				newBlockEntity.changeStorageSize(newInventorySize - newBlockEntity.getStorageWrapper().getInventoryHandler().getSlots(),
						newUpgradeSize - newBlockEntity.getStorageWrapper().getUpgradeHandler().getSlots());
			}
			WorldHelper.notifyBlockUpdate(newBlockEntity);
			return newBlockEntity;
		}

private <B extends BlockEntity> InteractionResult tryUpgradeStorage(ItemStack stack, BlockPos pos, Level level, BlockState state,
			TierUpgradeDefinition<B> def, BlockEntity blockEntity, @Nullable Player player) {
		B be = def.blockEntityClass().cast(blockEntity);
		if (level instanceof ServerLevel serverLevel && be instanceof StorageBlockEntity storageBlockEntity
				&& !getTierUpgradePermissionStorage(storageBlockEntity).canUpgradeStorageTier(serverLevel)) {
			if (player != null) {
				player.playNotifySound(SoundEvents.NOTE_BLOCK_BASS.value(), SoundSource.PLAYERS, 1, 0.7F);
				player.displayClientMessage(StorageTranslationHelper.INSTANCE.translStatusMessage("tier_upgrade_main_linked_storage_only"), true);
			}
			return InteractionResult.FAIL;
		}
		if (def.isUpgradingBlocked().test(be)) {
			return InteractionResult.PASS;
		}

		if (player == null) {
			return InteractionResult.PASS;
		}

		int countRequired = def.getCountRequired(state);
		if (countRequired > stack.getCount()) {
			player.displayClientMessage(Component.translatable(StorageTranslationHelper.INSTANCE.translGui("status.too_low_tier_upgrade_count"), countRequired,
					stack.getHoverName()), true);
			return InteractionResult.FAIL;
		}

		if (!def.upgradeStorage(player, pos, level, state, be)) {
			return InteractionResult.PASS;
		}

		if (!player.getAbilities().instabuild) {
			stack.shrink(countRequired);
		}
		return InteractionResult.SUCCESS;
	}

@Override
		boolean upgradeStorage(@Nullable Player player, BlockPos pos, Level level, BlockState state, StorageBlockEntity blockEntity) {
			if (blockEntity instanceof ChestBlockEntity chestBlockEntity && state.getValue(ChestBlock.TYPE) != ChestType.SINGLE) {
				return upgradeDoubleChest(pos, level, state, chestBlockEntity);
			}

			BlockState newBlockState = getBlockState(state);
			if (!(newBlockState.getBlock() instanceof StorageBlockBase newStorageBlock)) {
				return false;
			}
			upgradeStorageBlock(pos, level, blockEntity, newBlockState, newStorageBlock.getNumberOfInventorySlots(), newStorageBlock.getNumberOfUpgradeSlots())
					.setBeingUpgraded(false);
			return true;
		}

private boolean upgradeDoubleChest(BlockPos pos, Level level, BlockState state, ChestBlockEntity chestBlockEntity) {
			BlockPos otherPos = pos.relative(ChestBlock.getConnectedDirection(state));
			ChestBlockEntity otherBlockEntity = WorldHelper.getBlockEntity(level, otherPos, ChestBlockEntity.class).orElse(null);
			BlockState otherBlockState = getBlockState(level.getBlockState(otherPos));
			if (otherBlockEntity == null || !(otherBlockState.getBlock() instanceof StorageBlockBase storageBlock)) {
				return false;
			}

			chestBlockEntity.setBeingUpgraded(true);
			otherBlockEntity.setBeingUpgraded(true);
			StorageBlockEntity newMainBE;
			if (chestBlockEntity.isMainChest()) {
				newMainBE = upgradeStorageBlock(pos, level, chestBlockEntity, getBlockState(state), storageBlock.getNumberOfInventorySlots() * 2,
						storageBlock.getNumberOfUpgradeSlots());
				upgradeStorageBlock(otherPos, level, otherBlockEntity, otherBlockState, storageBlock.getNumberOfInventorySlots(),
						storageBlock.getNumberOfUpgradeSlots()).setBeingUpgraded(false);
				newMainBE.setBeingUpgraded(false);
			} else {
				StorageBlockEntity newOtherBE = upgradeStorageBlock(pos, level, chestBlockEntity, getBlockState(state),
						storageBlock.getNumberOfInventorySlots(), storageBlock.getNumberOfUpgradeSlots());
				newMainBE = upgradeStorageBlock(otherPos, level, otherBlockEntity, otherBlockState, storageBlock.getNumberOfInventorySlots() * 2,
						storageBlock.getNumberOfUpgradeSlots());
				newMainBE.setBeingUpgraded(false);
				newOtherBE.setBeingUpgraded(false);
			}
			otherBlockState.updateNeighbourShapes(level, otherPos, 3);
			newMainBE.changeSlots(newMainBE.getStorageWrapper().getInventoryHandler().getSlots());

			return true;
		}

private StorageBlockEntity upgradeStorage(BlockPos pos, Level level, BlockState state, B be) {
			Component customName = be.getCustomName();
			NonNullList<ItemStack> items = NonNullList.create();
			for (int slot = 0; slot < be.getContainerSize(); slot++) {
				items.add(slot, be.getItem(slot));
			}

			BlockState newBlockState = getBlockState(state);
			StorageBlockEntity newBlockEntity = newBlock().newBlockEntity(pos, newBlockState);
			// noinspection ConstantConditions - all storage blocks create a block entity so no chancde of null here
			setStorageItemsNameAndWoodType(newBlockEntity, customName, items, woodType());
			newBlockEntity.setUpdateBlockRender();
			replaceBlockAndBlockEntity(newBlockState, newBlockEntity, pos, level);
			WorldHelper.notifyBlockUpdate(newBlockEntity);
			return newBlockEntity;
		}

@Override
		boolean upgradeStorage(@Nullable Player player, BlockPos pos, Level level, BlockState state, B be) {
			if (player == null || !be.canOpen(player)) {
				return false;
			}
			BlockState otherState;
			if (state.getBlock() instanceof net.minecraft.world.level.block.ChestBlock
					&& state.getValue(net.minecraft.world.level.block.ChestBlock.TYPE) != ChestType.SINGLE) {
				otherState = level.getBlockState(pos.relative(net.minecraft.world.level.block.ChestBlock.getConnectedDirection(state)));
				if (otherState.getBlock() != state.getBlock()) {
					otherState = null;
				}
			} else {
				otherState = null;
			}

			StorageBlockEntity upgradedBe = upgradeStorage(pos, level, state, be);
			upgradedBe.tryToAddToController();
			if (otherState != null && otherState.getValue(net.minecraft.world.level.block.ChestBlock.TYPE) != ChestType.SINGLE
					&& state.getBlock() instanceof net.minecraft.world.level.block.ChestBlock) {
				BlockPos otherPos = pos.relative(net.minecraft.world.level.block.ChestBlock.getConnectedDirection(state));
				B otherBE = WorldHelper.getBlockEntity(level, otherPos, blockEntityClass()).orElse(null);
				if (otherBE == null) {
					return true;
				}
				upgradeStorage(otherPos, level, otherState, otherBE);
				level.getBlockEntity(otherPos, ModBlocks.CHEST_BLOCK_ENTITY_TYPE.get()).ifPresent(otherChestBE -> {
					level.getBlockEntity(pos, ModBlocks.CHEST_BLOCK_ENTITY_TYPE.get()).ifPresent(mainBE -> {
						if (state.getValue(net.minecraft.world.level.block.ChestBlock.TYPE) == ChestType.LEFT) {
							mainBE.joinWithChest(otherChestBE);
						} else {
							otherChestBE.joinWithChest(mainBE);
						}
					});
					WorldHelper.notifyBlockUpdate(otherChestBE);
				});
				level.getBlockState(otherPos).updateNeighbourShapes(level, otherPos, 3);
			}
			return true;
		}

private void setStorageItemsNameAndWoodType(StorageBlockEntity newBe, @Nullable Component customName, NonNullList<ItemStack> items,
				@Nullable WoodType woodType) {
			if (customName != null) {
				newBe.setCustomName(customName);
			}
			StorageWrapper storageWrapper = newBe.getStorageWrapper();
			InventoryHandler inventoryHandler = storageWrapper.getInventoryHandler();
			if (inventoryHandler.getSlots() < items.size()) {
				inventoryHandler.setSize(items.size());
			}

			for (int slot = 0; slot < items.size(); slot++) {
				inventoryHandler.setStackInSlot(slot, items.get(slot));
			}

			if (woodType != null && newBe instanceof WoodStorageBlockEntity wbe) {
				wbe.setWoodType(woodType);
			}

			if (color != -1) {
				storageWrapper.setColors(color, color);
			}
		}

private void replaceBlockAndBlockEntity(BlockState newBlockState, BlockEntity newBlockEntity, BlockPos pos, Level level) {
			level.removeBlockEntity(pos);
			level.removeBlock(pos, false);

			level.setBlock(pos, newBlockState, 3);
