@Override
    public Collection<IBroomPart> getBroomParts(ItemStack broomStack) {
        if(!broomStack.isEmpty()) {
            List<IBroomPart> parts = Lists.newArrayList();
            if(broomStack.hasTag()) {
                ListTag tags = broomStack.getTag().getList(NBT_TAG_NAME, Tag.TAG_STRING);
                for (int i = 0; i < tags.size(); i++) {
                    String id = tags.getString(i);
                    IBroomPart part = getPart(new ResourceLocation(id));
                    if (part != null) {
                        parts.add(part);
                    }
                }
            }

            if(parts.isEmpty()) {
                // BroomParts.BRUSH_WHEAT can be null during mod loading
                if (BroomParts.BRUSH_WHEAT != null) {
                    return Lists.newArrayList(BroomParts.BRUSH_WHEAT, BroomParts.CAP_GEM_DARK, BroomParts.ROD_WOOD);
                }
            }

            return parts;
        }
        return Collections.emptyList();
    }

@Override
    public void setBroomParts(ItemStack broomStack, Collection<IBroomPart> broomParts) {
        ListTag list = new ListTag();
        for (IBroomPart broomPart : broomParts) {
            list.add(StringTag.valueOf(broomPart.getId().toString()));
        }
        if(!broomStack.hasTag()) {
            broomStack.setTag(new CompoundTag());
        }
        broomStack.getTag().put(NBT_TAG_NAME, list);
    }

@Override
    public Map<BroomModifier, Float> getBaseModifiersFromBroom(ItemStack broomStack) {
        Map<BroomModifier, Float> baseModifiers = Maps.newHashMap();
        for (IBroomPart part : getBroomParts(broomStack)) {
            for (Map.Entry<BroomModifier, Float> entry : BroomParts.REGISTRY.getBaseModifiersFromPart(part).entrySet()) {
                BroomModifier modifier = entry.getKey();
                if(baseModifiers.containsKey(modifier)) {
                    baseModifiers.put(modifier, entry.getValue() + baseModifiers.get(modifier));
                } else{
                    baseModifiers.put(modifier, entry.getValue());
                }
            }
        }
        return baseModifiers;
    }

@Override
    public Collection<BroomModifier> getModifiers() {
        return Collections.unmodifiableCollection(broomModifiers.values());
    }

@Override
    public Map<BroomModifier, Float> getModifiers(ItemStack broomStack) {
        if(broomStack != null) {
            Map<BroomModifier, Float> modifiers = Maps.newHashMap();

            // Base values
            for (BroomModifier modifier : getModifiers()) {
                if (modifier.isBaseModifier()) {
                    modifiers.put(modifier, modifier.getDefaultValue());
                }
            }

            // Hardcoded values
            if(broomStack.hasTag()) {
                ListTag tags = broomStack.getTag().getList(NBT_TAG_NAME, Tag.TAG_COMPOUND);
                for (int i = 0; i < tags.size(); i++) {
                    CompoundTag tag = tags.getCompound(i);
                    String id = tag.getString(NBT_TAG_KEY);
                    float value = tag.getFloat(NBT_TAG_VALUE);
                    BroomModifier modifier = broomModifiers.get(new ResourceLocation(id));
                    if (modifier != null) {
                        modifiers.put(modifier, value);
                    }
                }
            }

            return modifiers;
        }
        return Collections.emptyMap();
    }

@Override
    public void setModifiers(ItemStack broomStack, Map<BroomModifier, Float> modifiers) {
        // Write modifiers
        ListTag list = new ListTag();
        for (Map.Entry<BroomModifier, Float> entry : modifiers.entrySet()) {
            CompoundTag tag = new CompoundTag();
            tag.putString(NBT_TAG_KEY, entry.getKey().getId().toString());
            tag.putFloat(NBT_TAG_VALUE, entry.getValue());
            list.add(tag);
        }
        if(!broomStack.hasTag()) {
            broomStack.setTag(new CompoundTag());
        }
        broomStack.getTag().put(NBT_TAG_NAME, list);

        // Write corresponding modifier parts
        Collection<IBroomPart> parts = BroomParts.REGISTRY.getBroomParts(broomStack);
        for (Map.Entry<BroomModifier, Float> entry : modifiers.entrySet()) {
            if (entry.getValue() > 0) {
                IBroomPart part = getModifierPart(entry.getKey());
                int tier = BroomModifier.getTier(entry.getKey(), entry.getValue());
                if (part != null) {
                    for (int i = 0; i < tier; i++) {
                        parts.add(part);
                    }
                }
            }
        }
        BroomParts.REGISTRY.setBroomParts(broomStack, parts);
    }

