public static boolean canAttachTo(ICapabilityProvider obj) {
        try {
            if (obj.getCapability(INSTANCE).isPresent()) {
                return false;
            }
        } catch (NullPointerException ex) {
            ScalingHealth.LOGGER.error("Failed to get capabilities from {}", obj);
            return false;
        }
        return obj instanceof Player || (obj instanceof ServerLevel && ((ServerLevel) obj).dimension().equals(Level.OVERWORLD));
    }

public static int getCrystalsAfterDeath(Player player) {
      float healthDifference =  player.getMaxHealth() - MathUtils.clamp((int) EvalVars.apply(player, getMechanics().healthOnDeath.get()), minHealth(), maxHealth());
      int crystalDifference = (int) healthDifference / (2 * SHItems.heartCrystalIncreaseAmount());
      return getPlayerData(player).getHeartCrystals() - crystalDifference;
   }

public static int clampExtraHearts(int value) {
      return MathUtils.clamp(value,
              (minHealth() - startingHealth()) / 2,
              (maxHealth() - startingHealth()) / 2
      );
   }

public static int clampPowerCrystals(int value) {
      return MathUtils.clamp(value,
              0,
              maxPowerCrystals()
      );
   }

public static double getDifficultyAfterDeath(Player player) {
        return EvalVars.apply(player, getMechanics().mutators.onPlayerDeath().get());
    }

public static double apply(Player player, Expression expression) {
        return apply(player.level(), player.blockPosition(), player, expression);
    }

public static double apply(Level world, BlockPos pos, @Nullable Player player, Expression expression) {
        Context context = new Context(world, pos, player);
        for (EvalVars variable : values()) {
            expression.setVariable(variable.varName(), variable.value.apply(context).toString());
        }
        return expression.eval().doubleValue();
    }

