@Override
    public ItemStack assemble(CraftingInput container) {
        ItemStack foundCell = ItemStack.EMPTY;
        var componentsFound = 0;

        for (int i = 0; i < container.size(); i++) {
            var stack = container.getItem(i);
            if (!stack.isEmpty()) {
                if (stack.is(inputCell)) {
                    if (stack.getCount() > 1 || !foundCell.isEmpty()) {
                        return ItemStack.EMPTY; // More than one cell found
                    }
                    foundCell = stack;
                } else if (stack.is(inputComponent)) {
                    if (++componentsFound > 1) {
                        return ItemStack.EMPTY; // More than one component found
                    }
                } else {
                    return ItemStack.EMPTY; // Other item found
                }
            }
        }

        if (foundCell.isEmpty() || componentsFound == 0) {
            return ItemStack.EMPTY;
        } else {
            return foundCell.transmuteCopy(resultCell, 1);
        }
    }

private boolean loadPart(Direction side, ValueInput input) {
        var itemId = input.read("id", Identifier.CODEC).orElse(null);
        if (itemId == null) {
            return false;
        }
        var partItem = IPartItem.byId(itemId);
        if (partItem == null) {
            AELog.warn("Ignoring persisted part with non-part-item %s", itemId);
            return false;
        }

        var p = this.getPart(side);
        if (p != null && p.getPartItem() == partItem) {
            p.readFromNBT(input);
        } else {
            p = this.replacePart(partItem, side, null, null);
            if (p != null) {
                p.readFromNBT(input);
            } else {
                AELog.warn("Invalid NBT For CableBus Container: " + itemId
                        + " is not a valid part; it was ignored.");
            }
        }
        return true;
    }

