    {
        if (!level.isClientSide && entity instanceof LivingEntity living && living.tickCount % 5 == 0)
        {
            boolean shouldBeOn = false;
            try
            {
                if (!(isSelected || living.getOffhandItem() == stack || CompatManager.Curios.hasCurio(living, stack)))
                {   return;
                }
                double max = Temperature.get(living, Temperature.Trait.BURNING_POINT);

                double temp = Temperature.getModifier(living, Temperature.Trait.WORLD, SoulLampTempModifier.class)
                              .map(mod -> mod.getLastInput(Temperature.Trait.WORLD)).orElseGet(() -> Temperature.get(living, Temperature.Trait.WORLD));

                // Is in valid dimension
                if ((ConfigSettings.LAMP_DIMENSIONS.get(level.registryAccess()).contains(level.dimensionType()))
                // Is world temp more than max
                && temp > max && getFuel(stack) > 0)
                {
                    shouldBeOn = true;
                    // Drain fuel
                    if (!(living instanceof Player player && player.isCreative() || living.isSpectator()))
                    {   addFuel(stack, -0.005 * CSMath.clamp(temp - max, 1, 3));
                    }

                    // Affect nearby players
                    double radius = 5d;
                    AABB bb = new AABB(living.getX() - radius, living.getY() + (living.getBbHeight() / 2) - radius, living.getZ() - radius,
                                       living.getX() + radius, living.getY() + (living.getBbHeight() / 2) + radius, living.getZ() + radius);

                    if (Math.random() < 0.6)
                    {
                        AABB bb2 = bb.inflate(-3);
                        double x = bb2.minX + (bb2.maxX - bb2.minX) * Math.random();
                        double y = bb2.minY + (bb2.maxY - bb2.minY) * Math.random();
                        double z = bb2.minZ + (bb2.maxZ - bb2.minZ) * Math.random();
                        double xSpeed = (Math.random() - 0.5) * 0.02;
                        double zSpeed = (Math.random() - 0.5) * 0.02;
                        new ParticleBatchMessage(0).addParticle(ParticleTypes.SOUL_FIRE_FLAME, x, y, z, xSpeed, 0, zSpeed)
                                                   .sendEntity(living);
                    }

                    for (LivingEntity ent : WorldHelper.getEntitiesOfClass(LivingEntity.class, level, bb, e -> true))
                    {
                        if (!EntityTempManager.isTemperatureEnabled(ent))
                        {   continue;
                        }
                        // Extend modifier time if it is present
                        Optional<SoulLampTempModifier> mod = Temperature.getModifier(ent, Temperature.Trait.WORLD, SoulLampTempModifier.class);
                        if (mod.isPresent())
                        {   mod.get().setTicksExisted(0);
                        }
                        else
                        {   Temperature.replaceOrAddModifier(ent, new SoulLampTempModifier().expires(5).tickRate(5), Temperature.Trait.WORLD, Matcher.SAME_CLASS);
                        }
                    }
                }
            }
            finally
            {
                // If the conditions are not met, turn off the lamp
                if (isLit(stack) != shouldBeOn)
                {
                    setLit(stack, shouldBeOn);
                    if (getFuel(stack) < 0.5)
                    {   setFuel(stack, 0);
                    }
                    WorldHelper.playEntitySound(shouldBeOn ? ModSounds.SOUL_LAMP_ON : ModSounds.SOUL_LAMP_OFF, living, living.getSoundSource(), 1.5f, (float) Math.random() / 5f + 0.9f);
                }
            }
        }
    }

public static void setFuel(ItemStack stack, double fuel)
    {   stack.getOrCreateTag().putDouble("Fuel", fuel);
    }

public static double getFuel(ItemStack stack)
    {   return stack.getOrCreateTag().getDouble("Fuel");
    }

public static void addFuel(ItemStack stack, double amount)
    {   setFuel(stack, Math.min(64, getFuel(stack) + amount));
    }

public static void addFuel(ItemStack stack, ItemStack fuelStack)
    {   addFuel(stack, getFuelForStack(fuelStack) * fuelStack.getCount());
    }

public static double getFuelForStack(ItemStack item)
    {
        FuelData fuelData = ConfigHelper.getFirstOrNull(ConfigSettings.SOULSPRING_LAMP_FUEL, item.getItem(), data -> data.test(item));
        return CSMath.getIfNotNull(fuelData, data -> data.fuel(item), 0);
    }

public static boolean isLit(ItemStack stack)
    {   return stack.getOrCreateTag().getBoolean("Lit");
    }

public static void setLit(ItemStack stack, boolean lit)
    {   stack.getOrCreateTag().putBoolean("Lit", lit);
    }

@Override
    public void inventoryTick(ItemStack stack, Level world, Entity entity, int slot, boolean isSelected)
    {
        super.inventoryTick(stack, world, entity, slot, isSelected);
        if (!world.isClientSide() && EntityTempManager.isTemperatureEnabled(entity) && entity.tickCount % 5 == 0)
        {
            double itemTemp = stack.getOrCreateTag().getDouble(FilledWaterskinItem.NBT_TEMPERATURE);
            boolean shouldDrain = ConfigSettings.ITEM_TEMPERATURES.get().get(stack.getItem())
                                  .stream().anyMatch(c -> c.test(entity, stack, slot, null));
            if (shouldDrain)
            {
                double drainAmt = (DRAIN_RATE / 20) * ConfigSettings.WATERSKIN_NEUTRALIZE_SPEED.get() * 4;
                double newTemp = CSMath.shrink(itemTemp, drainAmt);
                stack.getOrCreateTag().putDouble(FilledWaterskinItem.NBT_TEMPERATURE, newTemp);
            }
        }
    }

@Override
    public ItemStack finishUsingItem(ItemStack stack, Level level, LivingEntity entity)
    {   double amount = stack.getOrCreateTag().getDouble(FilledWaterskinItem.NBT_TEMPERATURE) * (ConfigSettings.WATERSKIN_CONSUME_STRENGTH.get() / 50d);
        Temperature.addModifier(entity, new WaterskinTempModifier(amount / (100 * stack.getMaxDamage())).expires(100), Temperature.Trait.CORE, Placement.LAST);
        if (entity instanceof Player player && player.isCreative())
        {   return stack;
        }
        else
        {
            if (getDurability(stack) <= 1)
            {   return consumeWaterskin(stack, entity, entity.getUsedItemHand());
            }
            else
            {   stack.setDamageValue(stack.getDamageValue() + 1);
                return stack;
            }
        }
    }

public static ItemStack consumeWaterskin(ItemStack stack, LivingEntity entity, InteractionHand usedHand)
    {
        // Create empty waterskin item
        ItemStack emptyStack = stack.getCraftingRemainingItem();
        WaterskinEvent.Empty event = new WaterskinEvent.Empty(stack, emptyStack, entity instanceof Player player ? player : null);
        MinecraftForge.EVENT_BUS.post(event);
        emptyStack = event.getResultWaterskin();

        // Add the item to the player's inventory
        if (entity instanceof Player player && player.getInventory().contains(emptyStack))
        {   player.addItem(emptyStack);
            player.setItemInHand(usedHand, ItemStack.EMPTY);
            return ItemStack.EMPTY;
        }
        else
        {   entity.setItemInHand(usedHand, emptyStack);
            return emptyStack;
        }
    }

@Override
    public ItemStack getCraftingRemainingItem(ItemStack stack)
    {
        if (stack.getItem() instanceof FilledWaterskinItem)
        {
            ItemStack emptyWaterskin = new ItemStack(ModItems.WATERSKIN);

            // Preserve NBT (except temperature)
            emptyWaterskin.setTag(CSMath.orElse(stack.getTag(), new CompoundTag()).copy());
            emptyWaterskin.removeTagKey(FilledWaterskinItem.NBT_TEMPERATURE);
            emptyWaterskin.removeTagKey("Damage");
            emptyWaterskin.removeTagKey("Purity");
            return emptyWaterskin;
        }
        return stack;
    }

public WaterskinTempModifier()
    {   this(0.0);
    }

public WaterskinTempModifier(double temp)
    {   this.getNBT().putDouble("Temperature", temp);
    }

@Override
    public Function<Double, Double>  calculate(LivingEntity entity, Temperature.Trait trait)
    {   return temp -> temp + this.getNBT().getDouble("Temperature");
    }

@Override
    public Function<Double, Double> calculate(LivingEntity entity, Temperature.Trait trait)
    {
        double almostMax = Temperature.get(entity, Temperature.Trait.BURNING_POINT) * 0.99;
        return temp ->
        {
            if (temp < almostMax) return temp;

            return Math.max(temp * (1 - ConfigSettings.SOULSPRING_LAMP_STRENGTH.get()), almostMax);
        };
    }

@Override
    public void deserializeNBT(CompoundTag tag)
    {
        if (Objects.equals(tag, this.serializedData)) return;
        CODEC.decode(NbtOps.INSTANCE, tag).result().ifPresent(result ->
        {
            List<Pair<ItemStack, List<InsulatorData>>> newInsulation = result.getFirst().getInsulation();
            if (!newInsulation.equals(this.insulation))
            {
                this.insulation.clear();
                this.insulation.addAll(newInsulation);
                this.changed = true;
            }
        });
    }

@Override
    public CompoundTag serializeNBT()
    {
        if (!this.changed && this.serializedData != null)
        {   return serializedData;
        }
        DataResult<Tag> result = CODEC.encodeStart(NbtOps.INSTANCE, this);
        CompoundTag nbt = (CompoundTag) result.result().orElse(new CompoundTag());
        this.serializedData = nbt;
        this.changed = false;
        return nbt;
    }

@Override
    public void copy(IInsulatableCap cap)
    {
        this.insulation.clear();
        this.insulation.addAll(cap.getInsulation());
    }

public void addInsulationItem(ItemStack stack)
    {
        List<InsulatorData> insulation = ConfigSettings.INSULATION_ITEMS.get().get(stack.getItem()).stream().map(InsulatorData::copy).toList();

        if (!insulation.isEmpty())
        {   this.insulation.add(Pair.of(stack, insulation));
            this.changed = true;
        }
    }

public ItemStack removeInsulationItem(ItemStack stack)
    {
        Optional<Pair<ItemStack, List<InsulatorData>>> toRemove = this.insulation.stream().filter(entry -> entry.getFirst().equals(stack)).findFirst();
        toRemove.ifPresent(pair ->
        {
            this.insulation.remove(pair);
            this.changed = true;
        });
        return stack;
    }

public boolean canAddInsulationItem(ItemStack armorItem, ItemStack insulationItem)
    {
        Collection<InsulatorData> insulation = ConfigSettings.INSULATION_ITEMS.get().get(insulationItem.getItem())
                                               .stream().filter(insulator -> insulator.test(null, insulationItem))
                                               .toList();
        if (insulation.isEmpty())
        {   return false;
        }

        int appliedInsulators = 0;
        // Include builtin armor insulation as "applied" insulation
        for (InsulatorData data : ConfigSettings.INSULATING_ARMORS.get().get(armorItem.getItem()))
        {
            if (data.fillSlots(armorItem))
            {   appliedInsulators += Insulation.splitList(data.insulation()).size();
            }
        }
        // Count applied insulation on the armor item
        appliedInsulators += ItemInsulationManager.getSlotsFilled(armorItem, CSMath.append(insulation, this.getInsulators()));
        appliedInsulators = Math.max(1, appliedInsulators);
        return appliedInsulators <= ItemInsulationManager.getInsulationSlots(armorItem);
    }

public void calcAdaptiveInsulation(double worldTemp, double minTemp, double maxTemp)
    {
        for (Pair<ItemStack, List<InsulatorData>> entry : insulation)
        {
            for (InsulatorData insulatorData : entry.getSecond())
            {
                List<Insulation> entryDataList = insulatorData.insulation();
                for (int i = 0; i < entryDataList.size(); i++)
                {
                    Insulation entryInsul = entryDataList.get(i);
                    if (entryInsul instanceof AdaptiveInsulation insul)
                    {
                        double newFactor = AdaptiveInsulation.calculateChange(insul, worldTemp, minTemp, maxTemp);
                        insul.setFactor(newFactor);
                    }
                }
            }
        }
        this.changed = true;
    }

@SubscribeEvent
        public static void attachCapabilityToItemHandler(AttachCapabilitiesEvent<ItemStack> event)
        {
            ItemStack stack = event.getObject();
            if (isInsulatable(stack))
            {
                // Make a new capability instance to attach to the item
                ItemInsulationCap itemInsulationCap = new ItemInsulationCap();
                // Optional that holds the capability instance
                final LazyOptional<IInsulatableCap> capOptional = LazyOptional.of(() -> itemInsulationCap);
                Capability<IInsulatableCap> capability = ModCapabilities.ITEM_INSULATION;

                ICapabilityProvider provider = new ICapabilitySerializable<CompoundTag>()
                {
                    @Nonnull
                    @Override
                    public <T> LazyOptional<T> getCapability(@Nonnull Capability<T> cap, @Nullable Direction direction)
                    {
                        // If the requested cap is the insulation cap, return the insulation cap
                        if (cap == capability)
                        {   return capOptional.cast();
                        }
                        return LazyOptional.empty();
                    }

                    @Override
                    public CompoundTag serializeNBT()
                    {   return itemInsulationCap.serializeNBT();
                    }

                    @Override
                    public void deserializeNBT(CompoundTag nbt)
                    {   itemInsulationCap.deserializeNBT(nbt);
                    }
                };

                // Attach the capability to the item
                event.addCapability(new ResourceLocation(ColdSweat.MOD_ID, "item_insulation"), provider);
            }
        }

