@Unique
	private static <T extends Enum<?>> void create$moveTagToEnumComponent(ItemStackComponentizationFix.ItemStackData stack, String key, String component, Class<T> enumClass) {
		if (!enumClass.isEnum())
			throw new IllegalArgumentException("moveTagToEnumComponent must be called with a enum class!");

		T[] enumConstants = enumClass.getEnumConstants();

		stack.removeTag(key).result().ifPresent(itemDynamic -> {
			T enumConstant = enumConstants[itemDynamic.asInt(0)];
			String enumConstantName;

			if (enumConstant instanceof StringRepresentable stringRepresentable) {
				enumConstantName = stringRepresentable.getSerializedName();
			} else {
				throw new IllegalArgumentException("moveTagToEnumComponent must be called with a enum class that implements StringRepresentable!");
			}

			stack.setComponent(component, itemDynamic.emptyMap().createString(enumConstantName));
		});
	}

@Unique
	private static void create$moveItemStackHandlerToItemContainerContents(ItemStackComponentizationFix.ItemStackData stack, Dynamic<?> dynamic, String key, String component) {
		try {
			stack.removeTag(key).result().ifPresent(itemDynamic -> {
				List<Dynamic<?>> list = new ArrayList<>();
				Stream<? extends Dynamic<?>> stream = itemDynamic.get("Items").asStream();
				stream.forEach(d -> {
					int slot = d.get("Slot").asInt(0);
					String id = d.get("id").asString().getOrThrow();
					int count = d.get("Count").asInt(1);

					Dynamic<?> dynamicMain = dynamic.emptyMap();
					Dynamic<?> dynamicItem = dynamic.emptyMap();

					dynamicItem = dynamicItem.set("count", dynamic.createInt(count));
					dynamicItem = dynamicItem.set("id", dynamic.createString(id));

					dynamicMain = dynamicMain.set("item", dynamicItem);
					dynamicMain = dynamicMain.set("slot", dynamic.createInt(slot));

					list.add(dynamicMain);
				});
				stack.setComponent(component, dynamic.createList(list.stream()));
			});
		} catch(Throwable ignored) {}
	}

@Unique
	private static boolean create$isCheckWithDyeColors(ItemStackComponentizationFix.ItemStackData stack, String template) {
		Set<String> ids = new HashSet<>();
		for (DyeColor dyeColor : DyeColor.values()) {
			ids.add(template.replace("{}", dyeColor.getName()));
		}
		return stack.is(ids);
	}

@Inject(method = "makeRule", at = @At(value = "INVOKE", target = "Ljava/util/List;add(Ljava/lang/Object;)Z", ordinal = 0))
	private void create$addFixers(CallbackInfoReturnable<TypeRewriteRule> cir, @Local List<TypeRewriteRule> output) {
		for (DataFixerHelper.BlockPosFixer fixer : DataFixerHelper.BLOCK_POS_FIXERS_VIEW) {
			DSL.TypeReference ref = fixer.reference();
			String id = fixer.id();

			TypeRewriteRule rule;

			if (fixer.customFixer() != null) {
				OpticFinder<?> opticfinder = DSL.namedChoice(id, this.getInputSchema().getChoiceType(ref, id));
				rule = fixTypeEverywhereTyped("BlockPos format for " + id + " (" + ref.typeName() + ")",
						getInputSchema().getType(ref),
						typed -> typed.updateTyped(opticfinder, data ->
									data.update(DSL.remainderFinder(), dynamic ->
										fixer.customFixer().apply(dynamic)
									)
								)
				);
			} else {
				rule = createEntityFixer(ref, id, fixer.renames());
			}

			output.add(rule);
		}
	}

private static void restoreUpgrades(Player player, ExportedUpgrades desiredUpgrades,
            IUpgradeableObject upgradeableObject) {
        var upgrades = upgradeableObject.getUpgrades();

        // In creative mode, just set it exactly as the memory card says
        if (player.getAbilities().instabuild) {
            // Clear it out first
            for (int i = 0; i < upgrades.size(); i++) {
                upgrades.setItemDirect(i, ItemStack.EMPTY);
            }
            for (var upgrade : desiredUpgrades.upgrades()) {
                upgrades.addItems(upgrade);
            }
        }

        var upgradeSources = new ArrayList<InternalInventory>();
        upgradeSources.add(new PlayerInternalInventory(player.getInventory()));

        // Search the player for a network tool
        var networkTool = NetworkToolItem.findNetworkToolInv(player);
        if (networkTool != null) {
            upgradeSources.add(networkTool.getInventory());
        }

        // Map of desired upgrade (ignoring the count in the key) to the desired count
        var desiredUpgradeCounts = new Reference2IntOpenHashMap<Item>(desiredUpgrades.upgrades().size());
        for (var desiredUpgrade : desiredUpgrades.upgrades()) {
            desiredUpgradeCounts.put(desiredUpgrade.getItem(), desiredUpgrade.getCount());
        }

        // Move out excess
        for (int i = 0; i < upgrades.size(); i++) {
            var current = upgrades.getStackInSlot(i);
            if (current.isEmpty()) {
                continue;
            }

            var desiredCount = desiredUpgradeCounts.getOrDefault(current, 0);
            var totalInstalled = upgradeableObject.getInstalledUpgrades(current.getItem());
            var toRemove = totalInstalled - desiredCount;
            if (toRemove > 0) {
                var removed = upgrades.extractItem(i, toRemove, false);

                for (var upgradeSource : upgradeSources) {
                    if (!removed.isEmpty()) {
                        removed = upgradeSource.addItems(removed);
                    }
                }
                if (!removed.isEmpty()) {
                    player.drop(removed, false, Prediction.SERVER_ONLY);
                }
            }
        }

        // Move in what's still missing
        for (var entry : desiredUpgradeCounts.reference2IntEntrySet()) {
            var missingAmount = entry.getIntValue() - upgradeableObject.getInstalledUpgrades(entry.getKey());
            if (missingAmount > 0) {
                var potential = new ItemStack(entry.getKey(), missingAmount);
                // Determine how many can we *actually* insert
                var overflow = upgrades.addItems(potential, true);
                if (!overflow.isEmpty()) {
                    missingAmount -= overflow.getCount();
                }

                // Try getting them from the network tool or player inventory
                for (var upgradeSource : upgradeSources) {
                    var cards = upgradeSource.removeItems(missingAmount, potential, null);
                    if (!cards.isEmpty()) {
                        overflow = upgrades.addItems(cards);
                        if (!overflow.isEmpty()) {
                            player.getInventory().placeItemBackInInventory(overflow, Prediction.SERVER_ONLY);
                        }
                        missingAmount -= cards.getCount();
                    }
                    if (missingAmount <= 0) {
                        break;
                    }
                }

                if (missingAmount > 0 && !player.level().isClientSide()) {
                    player.sendOverlayMessage(
                            PlayerMessages.MissingUpgrades.text(entry.getKey().getDefaultInstance().getItemName(),
                                    missingAmount));
                }
            }
        }
    }

public static IWaystone read(CompoundTag compound) {
        UUID waystoneUid = NbtUtils.loadUUID(Objects.requireNonNull(compound.get("WaystoneUid")));
        String name = compound.getString("Name");
        ResourceKey<Level> dimensionType = ResourceKey.create(Registries.DIMENSION, new ResourceLocation(compound.getString("World")));
        BlockPos pos = NbtUtils.readBlockPos(compound.getCompound("BlockPos"));
        boolean wasGenerated = compound.getBoolean("WasGenerated"); // legacy
        WaystoneOrigin origin = wasGenerated ? WaystoneOrigin.WILDERNESS : WaystoneOrigin.UNKNOWN;
        if (compound.contains("Origin")) {
            try {
                origin = WaystoneOrigin.valueOf(compound.getString("Origin"));
            } catch (IllegalArgumentException ignored) {
            }
        }
        UUID ownerUid = compound.contains("OwnerUid") ? NbtUtils.loadUUID(Objects.requireNonNull(compound.get("OwnerUid"))) : null;
        ResourceLocation waystoneType = compound.contains("Type") ? new ResourceLocation(compound.getString("Type")) : WaystoneTypes.WAYSTONE;
        Waystone waystone = new Waystone(waystoneType, waystoneUid, dimensionType, pos, origin, ownerUid);
        waystone.setName(name);
        waystone.setGlobal(compound.getBoolean("IsGlobal"));
        return waystone;
    }

public static CompoundTag write(IWaystone waystone, CompoundTag compound) {
        compound.put("WaystoneUid", NbtUtils.createUUID(waystone.getWaystoneUid()));
        compound.putString("Type", waystone.getWaystoneType().toString());
        compound.putString("Name", waystone.getName());
        compound.putString("World", waystone.getDimension().location().toString());
        compound.put("BlockPos", NbtUtils.writeBlockPos(waystone.getPos()));
        compound.putString("Origin", waystone.getOrigin().name());
        if (waystone.getOwnerUid() != null) {
            compound.put("OwnerUid", NbtUtils.createUUID(waystone.getOwnerUid()));
        }
        compound.putBoolean("IsGlobal", waystone.isGlobal());
        return compound;
    }

@Override
    public boolean isOwner(Player player) {
        return ownerUid == null || player.getGameProfile().getId().equals(ownerUid) || player.getAbilities().instabuild;
    }

@Override
    public boolean isValidInLevel(ServerLevel level) {
        BlockState state = level.getBlockState(pos);
        return state.is(ModBlockTags.IS_TELEPORT_TARGET);
    }

@Override
    public TeleportDestination resolveDestination(ServerLevel level) {
        BlockState state = level.getBlockState(pos);
        Direction direction = state.getValue(WaystoneBlock.FACING);
        // Use a list to keep order intact - it might check one direction twice, but no one cares
        List<Direction> directionCandidates = Lists.newArrayList(direction, Direction.EAST, Direction.WEST, Direction.SOUTH, Direction.NORTH);
        for (Direction candidate : directionCandidates) {
            BlockPos offsetPos = pos.relative(candidate);
            BlockPos offsetPosUp = offsetPos.above();
            if (level.getBlockState(offsetPos).isSuffocating(level, offsetPos) || level.getBlockState(offsetPosUp).isSuffocating(level, offsetPosUp)) {
                continue;
            }

            direction = candidate;
            break;
        }

        BlockPos targetPos = getWaystoneType().equals(WaystoneTypes.WARP_PLATE) ? getPos() : getPos().relative(direction);
        Vec3 location = new Vec3(targetPos.getX() + 0.5, targetPos.getY() + 0.5, targetPos.getZ() + 0.5);
        return new TeleportDestination(level, location, direction);
    }

public static WaystoneManager read(CompoundTag tagCompound) {
        WaystoneManager waystoneManager = new WaystoneManager();
        ListTag tagList = tagCompound.getList(TAG_WAYSTONES, Tag.TAG_COMPOUND);
        for (Tag tag : tagList) {
            CompoundTag compound = (CompoundTag) tag;
            IWaystone waystone = Waystone.read(compound);
            // Remove unnamed sharestones as a cleanup workaround for #1133.
            if (!waystone.hasName() && WaystoneTypes.isSharestone(waystone.getWaystoneType())) {
                continue;
            }
            waystoneManager.waystones.put(waystone.getWaystoneUid(), waystone);
        }
        return waystoneManager;
    }

@Override
    public CompoundTag save(CompoundTag tagCompound) {
        ListTag tagList = new ListTag();
        for (IWaystone waystone : waystones.values()) {
            tagList.add(Waystone.write(waystone, new CompoundTag()));
        }
        tagCompound.put(TAG_WAYSTONES, tagList);
        return tagCompound;
    }

