@Override
    public void onInitialize() {
        BalmLoadContexts.register("balm", EmptyLoadContext.INSTANCE);

        ((FabricBalmRuntime) Balm.getRuntime()).initializeRuntime();

        ((FabricBalmHooks) Balm.getHooks()).initialize();

        ServerPlayerEvents.COPY_FROM.register((oldPlayer, newPlayer, alive) -> {
            CompoundTag data = ((BalmEntity) oldPlayer).getFabricBalmData();
            ((BalmEntity) newPlayer).setFabricBalmData(data);
        });

        ItemStorage.SIDED.registerFallback(new BlockApiLookup.BlockApiProvider<>() {
            private boolean running;

            @Override
            public @Nullable Storage<ItemVariant> find(Level world, BlockPos pos, BlockState state, @Nullable BlockEntity blockEntity, Direction direction) {
                if (running) {
                    return null;
                }

                if (blockEntity instanceof BalmContainerProvider containerProvider) {
                    final var container = direction != null ? containerProvider.getContainer(direction) : containerProvider.getContainer();
                    if (container != null) {
                        return InventoryStorage.of(container, direction);
                    }
                } else if (blockEntity != null) {
                    running = true;
                    final var container = Balm.getCapabilities().getCapability(blockEntity, direction, CommonCapabilities.CONTAINER);
                    running = false;
                    if (container != null) {
                        return InventoryStorage.of(container, direction);
                    }
                }

                return null;
            }
        });

        FluidStorage.SIDED.registerFallback(new BlockApiLookup.BlockApiProvider<>() {
            private boolean running;

            @Override
            public @Nullable Storage<FluidVariant> find(Level world, BlockPos pos, BlockState state, @Nullable BlockEntity blockEntity, Direction direction) {
                if (running) {
                    return null;
                }

                if (blockEntity instanceof BalmFluidTankProvider fluidTankProvider) {
                    final var fluidTank = direction != null ? fluidTankProvider.getFluidTank(direction) : fluidTankProvider.getFluidTank();
                    if (fluidTank != null) {
                        return new BalmFluidStorage(fluidTank);
                    }
                } else if (blockEntity != null) {
                    running = true;
                    // Backwards compatibility requires us to use Void as context. Fixed in 1.21.5+
                    final var fluidTank = Balm.getCapabilities().getCapability(blockEntity, null, CommonCapabilities.FLUID_TANK);
                    running = false;
                    if (fluidTank != null) {
                        return new BalmFluidStorage(fluidTank);
                    }
                }

                return null;
            }
        });

        var providers = ((FabricBalmProviders) Balm.getProviders());
        providers.registerProvider(new ResourceLocation("balm", "container"), Container.class);
        providers.registerProvider(new ResourceLocation("balm", "fluid_tank"), FluidTank.class);
        providers.registerProvider(new ResourceLocation("balm", "energy_storage"), EnergyStorage.class);

        Balm.getNetworking().registerServerboundPacket(new ResourceLocation("balm", "mod_list"),
                ServerboundModListMessage.class, (message, buf) -> {
                    buf.writeVarInt(message.modList().size());
                    message.modList().forEach((modId, versions) -> {
                        buf.writeUtf(modId);
                        buf.writeUtf(versions.modVersion());
                        buf.writeUtf(versions.networkVersion());
                        buf.writeBoolean(versions.requireRemote());
                    });
                }, (buf) -> {
                    final var modVersions = new HashMap<String, NetworkVersions>();
                    final var modCount = buf.readVarInt();
                    for (int i = 0; i < modCount; i++) {
                        String modId = buf.readUtf();
                        modVersions.put(modId, new NetworkVersions(buf.readUtf(), buf.readUtf(), buf.readBoolean()));
                    }
                    return new ServerboundModListMessage(modVersions);
                }, (player, message) -> {
                    final var networking = (FabricBalmNetworking) Balm.getNetworking();
                    for (final var entry : message.modList().entrySet()) {
                        final var modId = entry.getKey();
                        final var clientVersions = entry.getValue();
                        final var serverVersionsOpt = networking.getNetworkVersions(modId, BalmEnvironment.SERVER);
                        if (serverVersionsOpt.isEmpty()) {
                            if (clientVersions.requireRemote()) {
                                player.connection.disconnect(Component.translatable("disconnect.balm.mod_missing_on_server",
                                        Component.literal(modId).withStyle(ChatFormatting.RED)));
                                return;
                            } else {
                                continue;
                            }
                        }

                        final var serverVersions = serverVersionsOpt.get();
                        if (!clientVersions.networkVersion().equals(serverVersions.networkVersion())) {
                            player.connection.disconnect(Component.translatable("disconnect.balm.mod_version_mismatch",
                                    Component.literal(modId).withStyle(ChatFormatting.GOLD),
                                    Component.literal(serverVersions.modVersion()).withStyle(ChatFormatting.GREEN),
                                    Component.literal(clientVersions.modVersion()).withStyle(ChatFormatting.RED)));
                            return;
                        }
                    }

                    for (final var modId : networking.getRegisteredMods()) {
                        final var serverVersions = networking.getNetworkVersions(modId, BalmEnvironment.SERVER).orElseThrow();
                        if (serverVersions.requireRemote() && !message.modList().containsKey(modId)) {
                            final var serverModVersion = serverVersions.modVersion();
                            player.connection.disconnect(Component.translatable("disconnect.balm.mod_missing_on_client",
                                    Component.literal(modId).withStyle(ChatFormatting.RED),
                                    Component.literal(modId).withStyle(ChatFormatting.GOLD),
                                    Component.literal(serverModVersion).withStyle(ChatFormatting.GREEN)));
                            return;
                        }
                    }
                });

        Balm.initializeIfLoaded("team_reborn_energy", "net.blay09.mods.balm.fabric.compat.energy.RebornEnergy");
    }

@Override
	public boolean onEntityItemUpdate(ItemStack stack, ItemEntity entity) {
		Level world = entity.level();
		ItemStack itemStack = entity.getItem();
		Vec3 positionVec = entity.position();
		CRecipes config = AllConfigs.server().recipes;

		if (world.isClientSide) {
			int light = getLight(itemStack);
			if (world.random.nextInt(config.lightSourceCountForRefinedRadiance.get() + 20) < light) {
				Vec3 start = VecHelper.offsetRandomly(positionVec, world.random, 3);
				Vec3 motion = positionVec.subtract(start)
					.normalize()
					.scale(.2f);
				world.addParticle(ParticleTypes.END_ROD, start.x, start.y, start.z, motion.x, motion.y, motion.z);
			}
			return false;
		}

		double y = entity.getY();
		double yMotion = entity.getDeltaMovement().y;
		int minHeight = world.getMinBuildHeight();
		CompoundTag data = entity.getPersistentData();

		// Convert to Shadow steel if in void
		if (y < minHeight && y - yMotion < -10 + minHeight && config.enableShadowSteelRecipe.get()) {
			ItemStack newStack = AllItems.SHADOW_STEEL.asStack();
			newStack.setCount(stack.getCount());
			data.putBoolean("JustCreated", true);
			entity.setItem(newStack);
		}

		if (!config.enableRefinedRadianceRecipe.get())
			return false;

		// Convert to Refined Radiance if eaten enough light sources
		if (getLight(itemStack) >= config.lightSourceCountForRefinedRadiance.get()) {
			ItemStack newStack = AllItems.REFINED_RADIANCE.asStack();
			ItemEntity newEntity = new ItemEntity(world, entity.getX(), entity.getY(), entity.getZ(), newStack);
			newEntity.setDeltaMovement(entity.getDeltaMovement());
			newEntity.getPersistentData()
				.putBoolean("JustCreated", true);
			itemStack.remove(AllDataComponents.CHROMATIC_COMPOUND_COLLECTING_LIGHT);
			world.addFreshEntity(newEntity);

			stack.split(1);
			entity.setItem(stack);
			if (stack.isEmpty())
				entity.discard();
			return false;
		}

		// Is inside beacon beam?
		boolean isOverBeacon = false;
		int entityX = Mth.floor(entity.getX());
		int entityZ = Mth.floor(entity.getZ());
		int localWorldHeight = world.getHeight(Heightmap.Types.WORLD_SURFACE, entityX, entityZ);

		BlockPos.MutableBlockPos testPos =
			new BlockPos.MutableBlockPos(entityX, Math.min(Mth.floor(entity.getY()), localWorldHeight), entityZ);

		while (testPos.getY() > minHeight) {
			testPos.move(Direction.DOWN);
			BlockState state = world.getBlockState(testPos);
			if (state.getLightBlock(world, testPos) >= 15 && state.getBlock() != Blocks.BEDROCK)
				break;
			if (state.getBlock() == Blocks.BEACON) {
				BlockEntity be = world.getBlockEntity(testPos);

				if (!(be instanceof BeaconBlockEntity bte))
					break;

				if (!bte.beamSections.isEmpty())
					isOverBeacon = true;

				break;
			}
		}

		if (isOverBeacon) {
			ItemStack newStack = AllItems.REFINED_RADIANCE.asStack();
			newStack.setCount(stack.getCount());
			data.putBoolean("JustCreated", true);
			entity.setItem(newStack);
			return false;
		}

		// Find a light source and eat it.
		RandomSource r = world.random;
		int range = 3;
		float rate = 1 / 2f;
		if (r.nextFloat() > rate)
			return false;

		BlockPos randomOffset = BlockPos.containing(VecHelper.offsetRandomly(positionVec, r, range));
		BlockState state = world.getBlockState(randomOffset);

		TransportedItemStackHandlerBehaviour behaviour =
			BlockEntityBehaviour.get(world, randomOffset, TransportedItemStackHandlerBehaviour.TYPE);

		// Find a placed light source
		if (behaviour == null) {
			if (checkLight(stack, entity, world, itemStack, positionVec, randomOffset, state))
				world.destroyBlock(randomOffset, false);
			return false;
		}

		// Find a light source from a depot/belt (chunk rebuild safe)
		MutableBoolean success = new MutableBoolean(false);
		behaviour.handleProcessingOnAllItems(ts -> {

			ItemStack heldStack = ts.stack;
			if (!(heldStack.getItem() instanceof BlockItem blockItem))
				return TransportedResult.doNothing();

			if (blockItem.getBlock() == null)
				return TransportedResult.doNothing();

			BlockState stateToCheck = blockItem.getBlock()
				.defaultBlockState();

			if (!success.getValue()
				&& checkLight(stack, entity, world, itemStack, positionVec, randomOffset, stateToCheck)) {
				success.setTrue();
				if (ts.stack.getCount() == 1)
					return TransportedResult.removeItem();
				TransportedItemStack left = ts.copy();
				left.stack.shrink(1);
				return TransportedResult.convertTo(left);
			}

			return TransportedResult.doNothing();

		});
		return false;
	}

public boolean checkLight(ItemStack stack, ItemEntity entity, Level world, ItemStack itemStack, Vec3 positionVec,
							  BlockPos randomOffset, BlockState state) {
		if (state.getLightEmission(world, randomOffset) == 0)
			return false;
		if (state.getDestroySpeed(world, randomOffset) == -1)
			return false;
		if (state.getBlock() == Blocks.BEACON)
			return false;

		ClipContext context = new ClipContext(positionVec.add(new Vec3(0, 0.5, 0)), VecHelper.getCenterOf(randomOffset),
			Block.COLLIDER, Fluid.NONE, entity);
		if (!randomOffset.equals(world.clip(context)
			.getBlockPos()))
			return false;

		DataComponentMap components = itemStack.getComponents();
		ItemStack newStack = stack.split(1);
		newStack.set(AllDataComponents.CHROMATIC_COMPOUND_COLLECTING_LIGHT, getLight(components) + 1);
		ItemEntity newEntity = new ItemEntity(world, entity.getX(), entity.getY(), entity.getZ(), newStack);
		newEntity.setDeltaMovement(entity.getDeltaMovement());
		newEntity.setDefaultPickUpDelay();
		world.addFreshEntity(newEntity);
		entity.lifespan = 6000;
		if (stack.isEmpty())
			entity.discard();
		return true;
	}

@Override
	public boolean onEntityItemUpdate(ItemStack stack, ItemEntity entity) {
		Level world = entity.level();
		Vec3 pos = entity.position();
		CompoundTag persistentData = entity.getPersistentData();

		if (world.isClientSide) {
			if (world.random.nextFloat() < getIdleParticleChance(entity)) {
				Vec3 ppos = VecHelper.offsetRandomly(pos, world.random, .5f);
				world.addParticle(ParticleTypes.END_ROD, ppos.x, pos.y, ppos.z, 0, -.1f, 0);
			}

			if (entity.isSilent() && !persistentData.getBoolean("PlayEffects")) {
				Vec3 basemotion = new Vec3(0, 1, 0);
				world.addParticle(ParticleTypes.FLASH, pos.x, pos.y, pos.z, 0, 0, 0);
				for (int i = 0; i < 20; i++) {
					Vec3 motion = VecHelper.offsetRandomly(basemotion, world.random, 1);
					world.addParticle(ParticleTypes.WITCH, pos.x, pos.y, pos.z, motion.x, motion.y, motion.z);
					world.addParticle(ParticleTypes.END_ROD, pos.x, pos.y, pos.z, motion.x, motion.y, motion.z);
				}
				persistentData.putBoolean("PlayEffects", true);
			}

			return false;
		}

		entity.setNoGravity(true);

		if (!persistentData.contains("JustCreated"))
			return false;
		onCreated(entity, persistentData);
		return false;
	}

@Override
	protected void read(CompoundTag compound, HolderLookup.Provider registries, boolean clientPacket) {
		super.read(compound, registries, clientPacket);

		BlockPos controllerBefore = controller;
		int prevSize = width;
		int prevHeight = height;
		int prevLum = luminosity;

		updateConnectivity = compound.contains("Uninitialized");
		luminosity = compound.getInt("Luminosity");

		lastKnownPos = null;
		if (compound.contains("LastKnownPos"))
			lastKnownPos = NBTHelper.readBlockPos(compound, "LastKnownPos");

		controller = null;
		if (compound.contains("Controller"))
			controller = NBTHelper.readBlockPos(compound, "Controller");

		if (isController()) {
			window = compound.getBoolean("Window");
			width = compound.getInt("Size");
			height = compound.getInt("Height");
			tankInventory.setCapacity(getTotalTankSize() * getCapacityMultiplier());

			tankInventory.readFromNBT(registries, compound.getCompound("TankContent"));
			if (tankInventory.getSpace() < 0)
				tankInventory.drain(-tankInventory.getSpace(), FluidAction.EXECUTE);
		}

		boiler.read(compound.getCompound("Boiler"), width * width * height);

		if (compound.contains("ForceFluidLevel") || fluidLevel == null)
			fluidLevel = LerpedFloat.linear()
				.startWithValue(getFillState());

		updateCapability = true;

		if (!clientPacket)
			return;

		boolean changeOfController = !Objects.equals(controllerBefore, controller);
		if (changeOfController || prevSize != width || prevHeight != height) {
			if (hasLevel())
				level.sendBlockUpdated(getBlockPos(), getBlockState(), getBlockState(), 16);
			if (isController())
				tankInventory.setCapacity(getCapacityMultiplier() * getTotalTankSize());
			invalidateRenderBoundingBox();
		}
		if (isController()) {
			float fillState = getFillState();
			if (compound.contains("ForceFluidLevel") || fluidLevel == null)
				fluidLevel = LerpedFloat.linear()
					.startWithValue(fillState);
			fluidLevel.chase(fillState, 0.5f, Chaser.EXP);
		}
		if (luminosity != prevLum && hasLevel())
			level.getChunkSource()
				.getLightEngine()
				.checkBlock(worldPosition);

		if (compound.contains("LazySync"))
			fluidLevel.chase(fluidLevel.getChaseTarget(), 0.125f, Chaser.EXP);
	}

@Override
	protected boolean updateCustomBlockEntityTag(BlockPos blockPos, Level level, Player player,
		ItemStack itemStack, BlockState blockState) {
		MinecraftServer minecraftserver = level.getServer();
		if (minecraftserver == null)
			return false;
		CustomData blockEntityData = itemStack.get(DataComponents.BLOCK_ENTITY_DATA);
		if (blockEntityData != null) {
			CompoundTag nbt = blockEntityData.copyTag();
			nbt.remove("Luminosity");
			nbt.remove("Size");
			nbt.remove("Height");
			nbt.remove("Controller");
			nbt.remove("LastKnownPos");
			if (nbt.contains("TankContent")) {
				FluidStack fluid = FluidStack.parseOptional(minecraftserver.registryAccess(), nbt.getCompound("TankContent"));
				if (!fluid.isEmpty()) {
					fluid.setAmount(Math.min(FluidTankBlockEntity.getCapacityMultiplier(), fluid.getAmount()));
					nbt.put("TankContent", fluid.saveOptional(minecraftserver.registryAccess()));
				}
			}
			BlockEntity.addEntityType(nbt, ((IBE<?>) this.getBlock()).getBlockEntityType());
			itemStack.set(DataComponents.BLOCK_ENTITY_DATA, CustomData.of(nbt));
		}
		return super.updateCustomBlockEntityTag(blockPos, level, player, itemStack, blockState);
	}

@Override
  public void storeInventory(IDeathStorage deathStorage) {
    PlayerEntity player = deathStorage.getPlayer();

    if (player != null) {
      PlayerInventory inventory = player.inventory;
      InventorySetting setting = deathStorage.getSettings().getInventorySettings();
      ListNBT list = new ListNBT();

      for (int i = 0; i < 9; i++) {
        InventoryHelper.process(player, inventory.getStackInSlot(i), i, list,
            i == inventory.currentItem ? InventorySection.MAINHAND : InventorySection.HOTBAR,
            setting);
      }

      for (int i = 9; i < 36; i++) {
        InventoryHelper
            .process(player, inventory.getStackInSlot(i), i, list, InventorySection.MAIN, setting);
      }
      InventoryHelper
          .process(player, inventory.getStackInSlot(36), 36, list, InventorySection.FEET, setting);
      InventoryHelper
          .process(player, inventory.getStackInSlot(37), 37, list, InventorySection.LEGS, setting);
      InventoryHelper
          .process(player, inventory.getStackInSlot(38), 38, list, InventorySection.CHEST, setting);
      InventoryHelper
          .process(player, inventory.getStackInSlot(39), 39, list, InventorySection.HEAD, setting);
      InventoryHelper
          .process(player, inventory.getStackInSlot(40), 40, list, InventorySection.OFFHAND,
              setting);
      deathStorage.addInventory("vanilla", list);
    }
  }

@Override
  public void retrieveInventory(IDeathStorage newStorage, IDeathStorage oldStorage) {
    PlayerEntity player = newStorage.getPlayer();
    PlayerEntity oldPlayer = oldStorage.getPlayer();

    if (player != null && oldPlayer != null) {
      ListNBT list = (ListNBT) oldStorage.getInventory("vanilla");

      if (list != null) {
        PlayerInventory inventory = player.inventory;

        for (int i = 0; i < list.size(); ++i) {
          CompoundNBT compoundnbt = list.getCompound(i);
          int slot = compoundnbt.getInt("Slot");
          ItemStack itemstack = ItemStack.read(compoundnbt);
          if (!itemstack.isEmpty()) {
            ItemStack existing = inventory.getStackInSlot(slot);

            if (existing.isEmpty()) {
              inventory.setInventorySlotContents(slot, itemstack);
            } else {
              ItemHandlerHelper.giveItemToPlayer(inventory.player, itemstack);
            }
          }
        }
      }
    }
  }

@SubscribeEvent(priority = EventPriority.HIGH)
  public void playerDeath(final LivingDeathEvent evt) {

    if (!(evt.getEntityLiving() instanceof PlayerEntity)) {
      return;
    }
    PlayerEntity playerEntity = (PlayerEntity) evt.getEntityLiving();
    World world = playerEntity.getEntityWorld();

    if (!world.isRemote() && !world.getGameRules().getBoolean(GameRules.KEEP_INVENTORY)) {
      DeathStorageCapability.getCapability(playerEntity).ifPresent(
          deathStorage -> STORAGE.forEach(storage -> storage.storeInventory(deathStorage)));
    }
  }

@SubscribeEvent(priority = EventPriority.LOWEST, receiveCanceled = true)
  public void canceledDeath(final LivingDeathEvent evt) {

    if (!(evt.getEntityLiving() instanceof PlayerEntity) || !evt.isCanceled()) {
      return;
    }
    PlayerEntity playerEntity = (PlayerEntity) evt.getEntityLiving();
    World world = playerEntity.getEntityWorld();

    if (!world.isRemote() && !world.getGameRules().getBoolean(GameRules.KEEP_INVENTORY)) {
      DeathStorageCapability.getCapability(playerEntity).ifPresent(deathStorage -> {
        STORAGE.forEach(storage -> storage.retrieveInventory(deathStorage, deathStorage));
        deathStorage.clearDeathInventory();
      });
    }
  }

@SubscribeEvent(priority = EventPriority.LOW)
  public void playerRespawn(final PlayerEvent.Clone evt) {

    if (evt.isWasDeath()) {
      PlayerEntity original = evt.getOriginal();
      original.revive();
      DeathStorageCapability.getCapability(evt.getPlayer()).ifPresent(
          newStorage -> DeathStorageCapability.getCapability(evt.getOriginal()).ifPresent(
              oldStorage -> STORAGE
                  .forEach(storage -> storage.retrieveInventory(newStorage, oldStorage))));
      original.remove();
    }
  }

public static void process(PlayerEntity player, ItemStack stack, int index, ListNBT list,
                             InventorySection section, InventorySetting setting) {
    DropMode inventoryRule = getDropModeOverride(stack, setting);
    SectionSettings defaultSettings = setting.getInventorySettings().get(InventorySection.DEFAULT);
    SectionSettings sectionSettings = setting.getInventorySettings().get(section);
    double keepChance =
        sectionSettings.keepChance >= 0 ? sectionSettings.keepChance : defaultSettings.keepChance;
    double destroyChance = sectionSettings.destroyChance >= 0 ? sectionSettings.destroyChance
        : defaultSettings.destroyChance;

    if (inventoryRule != null) {
      if (inventoryRule == DropMode.KEEP) {
        keepChance = 1.0D;
      } else if (inventoryRule == DropMode.DESTROY) {
        destroyChance = 1.0D;
      } else if (inventoryRule == DropMode.DROP) {
        keepChance = 0.0D;
      }
    }
    ItemStack keep = stack.split(getRandomAmount(stack.getCount(), keepChance));

    if (!keep.isEmpty()) {
      double keepDurabilityLoss =
          sectionSettings.keepDurabilityLoss >= 0 ? sectionSettings.keepDurabilityLoss
              : defaultSettings.keepDurabilityLoss;
      double finalKeepDurabilityLoss = keepDurabilityLoss;
      keepDurabilityLoss = ItemOverrideManager.getOverride(keep.getItem())
          .map(override -> override.getKeepDurabilityLoss().orElse(finalKeepDurabilityLoss))
          .orElse(keepDurabilityLoss);
      applyDurabilityLoss(player, keep, setting, keepDurabilityLoss);
      CompoundNBT compoundnbt = new CompoundNBT();
      compoundnbt.putInt("Slot", index);
      keep.write(compoundnbt);
      list.add(compoundnbt);
    }
    double dropDurabilityLoss =
        sectionSettings.dropDurabilityLoss >= 0 ? sectionSettings.dropDurabilityLoss
            : defaultSettings.dropDurabilityLoss;
    double finalDropDurabilityLoss = dropDurabilityLoss;
    dropDurabilityLoss = ItemOverrideManager.getOverride(stack.getItem())
        .map(override -> override.getDropDurabilityLoss().orElse(finalDropDurabilityLoss))
        .orElse(dropDurabilityLoss);
    applyDurabilityLoss(player, stack, setting, dropDurabilityLoss);
    stack.shrink(getRandomAmount(stack.getCount(), destroyChance));
  }

@Nullable
  public static DropMode getDropModeOverride(ItemStack stack, InventorySetting setting) {

    if (saveSoulbound(stack)) {
      return DropMode.KEEP;
    } else if (EnchantmentHelper.hasVanishingCurse(stack)) {
      return DropMode.DESTROY;
    }
    return setting.getItems().get(stack.getItem());
  }

public static void applyDurabilityLoss(PlayerEntity playerEntity, ItemStack stack,
                                         InventorySetting setting, double durabilityLoss) {

    if (!stack.isDamageable()) {
      return;
    }
    LazyOptional<IEnergyStorage> energyStorage = stack.getCapability(CapabilityEnergy.ENERGY);

    energyStorage.ifPresent(energy -> {
      int energyLoss = (int) Math.round(energy.getMaxEnergyStored() * durabilityLoss);
      if (energy.canExtract()) {
        energy.extractEnergy(energyLoss, false);
      }
    });
    int maxLoss = setting.isLimitDurabilityLoss() ? stack.getMaxDamage() - stack.getDamage() - 1
        : stack.getMaxDamage();
    int loss = (int) Math.round(stack.getMaxDamage() * durabilityLoss);
    stack.damageItem(Math.min(maxLoss, loss), playerEntity, damager -> {
    });
  }

public static int getRandomAmount(int num, double chance) {

    if (chance >= 1.0D) {
      return num;
    } else if (chance <= 0.0D) {
      return 0;
    }
    int amount = 0;

    for (int i = 0; i < num; i++) {
      if (RAND.nextDouble() < chance) {
        amount++;
      }
    }
    return amount;
  }

private static boolean saveSoulbound(ItemStack stack) {
    int level = 0;
    Enchantment enchantment = null;

    for (Map.Entry<Enchantment, Integer> enchantmentIntegerEntry : EnchantmentHelper
        .getEnchantments(stack).entrySet()) {

      if (enchantmentIntegerEntry.getKey().isIn(SOULBOUND)) {
        level = enchantmentIntegerEntry.getValue();
        enchantment = enchantmentIntegerEntry.getKey();
        break;
      }
    }

    if (level <= 0 || enchantment == null) {
      return false;
    }

    double savePercent =
        CorpseComplexConfig.baseSave + CorpseComplexConfig.extraSavePerLevel * (level - 1);
    boolean activated = false;

    if (RAND.nextDouble() < savePercent) {
      activated = true;
    }
    double levelDropChance = CorpseComplexConfig.levelDropChance;

    if (levelDropChance > 0 && activated) {
      if (RAND.nextDouble() < levelDropChance) {
        level = Math.max(0, level - 1);
      }

      Map<Enchantment, Integer> enchMap = EnchantmentHelper.getEnchantments(stack);
      enchMap.remove(enchantment);

      if (level > 0) {
        enchMap.put(enchantment, level);
      }
      EnchantmentHelper.setEnchantments(enchMap, stack);
    }
    return activated;
  }

public static void register() {
    CapabilityManager.INSTANCE.register(IDeathStorage.class, new IStorage<IDeathStorage>() {

      @Override
      public INBT writeNBT(Capability<IDeathStorage> capability, IDeathStorage instance,
          Direction side) {
        CompoundNBT compound = new CompoundNBT();
        CompoundNBT inventories = new CompoundNBT();
        instance.getDeathInventory().forEach(inventories::put);
        compound.put(INVENTORIES, inventories);
        ListNBT effects = new ListNBT();
        instance.getEffects().forEach(effectInstance -> {
          CompoundNBT effect = new CompoundNBT();
          effectInstance.write(effect);
          effects.add(effect);
        });
        compound.put(EFFECTS, effects);
        DeathInfo info = instance.getDeathInfo();
        if (info != null) {
          info.write(compound);
        }
        return compound;
      }

      @Override
      public void readNBT(Capability<IDeathStorage> capability, IDeathStorage instance,
          Direction side, INBT nbt) {
        CompoundNBT compound = (CompoundNBT) nbt;
        CompoundNBT inventories = compound.getCompound(INVENTORIES);
        inventories.keySet().forEach(modid -> instance.addInventory(modid, inventories.get(modid)));
        ListNBT effects = compound.getList(EFFECTS, NBT.TAG_COMPOUND);
        effects.forEach(effect -> {
          EffectInstance effectInstance = EffectInstance.read((CompoundNBT) effect);
          instance.addEffectInstance(effectInstance);
        });
        DeathInfo deathDamageSource = new DeathInfo();
        deathDamageSource.read(compound);
        instance.setDeathDamageSource(deathDamageSource);
      }
    }, DeathStorage::new);
  }

