@Override
	protected void read(CompoundTag tag, HolderLookup.Provider registries, boolean clientPacket) {
		super.read(tag, registries, clientPacket);

		consumedItem = ItemStack.parseOptional(registries, tag.getCompound("Item"));

		BlockState prevMaterial = material;
		if (!tag.contains("Material")) {
			consumedItem = ItemStack.EMPTY;
			return;
		}

		material = NbtUtils.readBlockState(blockHolderGetter(), tag.getCompound("Material"));

		// Validate Material
		if (material != null && !clientPacket) {
			BlockState blockState = getBlockState();
			if (blockState == null)
				return;
			if (!(blockState.getBlock() instanceof CopycatBlock cb))
				return;
			BlockState acceptedBlockState = cb.getAcceptedBlockState(level, worldPosition, consumedItem, null);
			if (acceptedBlockState != null && material.is(acceptedBlockState.getBlock()))
				return;
			consumedItem = ItemStack.EMPTY;
			material = AllBlocks.COPYCAT_BASE.getDefaultState();
		}

		if (clientPacket && prevMaterial != material)
			redraw();
	}

@Override
	protected void read(CompoundTag compound, HolderLookup.Provider registries, boolean clientPacket) {
		super.read(compound, registries, clientPacket);
		if (clientPacket && compound.contains("DestroyEffect") && level != null)
			spawnDestroyParticles(NBTHelper.readBlockPos(compound, "DestroyEffect"));

		int sizeBefore = connections.size();
		connections.clear();
		CatnipCodecUtils.decode(CatnipCodecs.set(BlockPos.CODEC), registries, compound.get("Connections")).ifPresent(connections::addAll);
		travellingPackages.clear();
		NBTHelper.iterateCompoundList(compound.getList("TravellingPackages", Tag.TAG_COMPOUND),
			c -> travellingPackages.put(NBTHelper.readBlockPos(c, "Target"),
				NBTHelper.readCompoundList(c.getList("Packages", Tag.TAG_COMPOUND), t -> ChainConveyorPackage.read(t, registries))));
		loopingPackages = NBTHelper.readCompoundList(compound.getList("LoopingPackages", Tag.TAG_COMPOUND),
			t -> ChainConveyorPackage.read(t, registries));
		connectionStats = null;
		updateBoxWorldPositions();
		updateChainShapes();

		if (connections.size() != sizeBefore && level != null && level.isClientSide)
			invalidateRenderBoundingBox();
	}

@Override
	protected void read(CompoundTag compound, HolderLookup.Provider registries, boolean clientPacket) {
		super.read(compound, registries, clientPacket);
		flowScore = compound.getInt("FlowScore");

		BlockState prevMaterial = material;
		if (!compound.contains("Material"))
			return;

		material = NbtUtils.readBlockState(blockHolderGetter(), compound.getCompound("Material"));
		if (material.isAir())
			material = Blocks.SPRUCE_PLANKS.defaultBlockState();

		if (clientPacket && prevMaterial != material)
			redraw();
	}

private boolean reload(LivingEntity entity, ItemStack crossbowStack) {
        int count = Math.max(getEffectLevel(crossbowStack, ItemEffect.ammoCapacity), 1);
        boolean infinite = CastOptional.cast(entity, Player.class)
                .map(player -> player.getAbilities().instabuild)
                .orElse(false);

        // todo: this has to be improved
        ItemStack ammoStack = ItemStack.EMPTY;

        for (int i = 0; i < count; i++) {
            if (ammoStack.isEmpty()) {
                ammoStack = findAmmo(entity);
            }

            if (ammoStack.isEmpty() && infinite) {
                ammoStack = new ItemStack(Items.ARROW);
            }

            if (!loadProjectiles(entity, crossbowStack, ammoStack, infinite && ammoStack.getItem() instanceof ArrowItem)) {
                return i > 0;
            }
        }

        return true;
    }

