public static CompoundTag serializeHandler(ItemStackHandler handler) {
        return serializeNBT(handler);
    }

public static CompoundTag serializeNBT(ItemStackHandler handler) {
        ListTag nbtTagList = new ListTag();
        for(int i = 0; i < handler.getSlots(); i++) {
            CompoundTag itemTag = new CompoundTag();
            itemTag.putInt("Slot", i);
            handler.getStackInSlot(i).save(itemTag);
            nbtTagList.add(itemTag);
        }
        CompoundTag nbt = new CompoundTag();
        nbt.put("Items", nbtTagList);
        nbt.putInt("Size", nbtTagList.size());
        return nbt;
    }

public static CompoundTag getHandlerNbt(ItemStack stack, String key) {
        return stack.getTag().getCompound(key);
    }

public static CompoundTag expandTag(ItemStack stack, String key, int defaultSize) {
        CompoundTag tag = getHandlerNbt(stack, key);
        NonNullList<ItemStack> stacks = NonNullList.withSize(defaultSize, ItemStack.EMPTY);
        ListTag tagList = tag.getList("Items", 10);
        for(int i = 0; i < tagList.size(); ++i) {
            CompoundTag itemTags = tagList.getCompound(i);
            int slot = itemTags.getInt("Slot");
            if(slot >= 0 && slot < stacks.size()) {
                stacks.set(slot, ItemStack.of(itemTags));
            }
        }
        return serializeHandler(new ItemStackHandler(stacks));
    }

public static NonNullList<ItemStack> deserializeHandler(ItemStack stack, String key) {
        ListTag tagList = stack.getTag().getCompound(key).getList("Items", 10);
        int size = stack.getTag().contains("Size") ? stack.getTag().getCompound(key).getInt("Size") : tagList.size();
        NonNullList<ItemStack> stacks = NonNullList.withSize(size, ItemStack.EMPTY);

        for(int i = 0; i < tagList.size(); ++i) {
            CompoundTag itemTags = tagList.getCompound(i);
            int slot = itemTags.getInt("Slot");
            if(slot >= 0 && slot < stacks.size()) {
                stacks.set(slot, ItemStack.of(itemTags));
            }
        }
        return stacks;
    }

public static void update(ItemStack backpack, String key, int defaultSize, int slot, ItemStack stack) {
        if(backpack.hasTag() && backpack.getTag().contains(key)) {
            CompoundTag unboxed = backpack.getTag().getCompound(key);
            ListTag itemsListed = unboxed.getList("Items", 10);

            CompoundTag newItemTag = new CompoundTag();
            newItemTag.putInt("Slot", slot);
            stack.save(newItemTag);

            if(slot >= 0 && slot < itemsListed.size()) {
                itemsListed.set(slot, newItemTag);
            }
        } else {
            ListTag nbtTagList = new ListTag();

            for(int i = 0; i < defaultSize; ++i) {
                CompoundTag itemTag = new CompoundTag();
                itemTag.putInt("Slot", i);
                ItemStack.EMPTY.copy().save(itemTag);
                nbtTagList.add(itemTag);
            }

            CompoundTag newItemTag = new CompoundTag();
            newItemTag.putInt("Slot", slot);
            stack.save(newItemTag);

            if(slot >= 0 && slot < nbtTagList.size()) {
                nbtTagList.set(slot, newItemTag);
            }

            CompoundTag nbt = new CompoundTag();
            nbt.put("Items", nbtTagList);
            nbt.putInt("Size", nbtTagList.size());
            backpack.getOrCreateTag().put(key, nbt);
        }
    }

public static CompoundTag serializeFluids(Fluids fluids) {
        CompoundTag tag = new CompoundTag();
        tag.put("leftFluidStack", fluids.leftFluidStack().writeToNBT(new CompoundTag()));
        tag.put("rightFluidStack", fluids.rightFluidStack().writeToNBT(new CompoundTag()));
        return tag;
    }

public static FluidStack deserializeLeftFluidStack(CompoundTag tag) {
        return FluidStack.loadFluidStackFromNBT(tag.getCompound("leftFluidStack"));
    }

public static FluidStack deserializeRightFluidStack(CompoundTag tag) {
        return FluidStack.loadFluidStackFromNBT(tag.getCompound("rightFluidStack"));
    }

public UpgradeManager(BackpackWrapper wrapper) {
        this.wrapper = wrapper;
        this.upgradesHandler = wrapper.getUpgrades();
        this.mappedUpgrades = HashBiMap.create();
        initializeUpgrades();
    }

public void initializeUpgrades() {
        for(int i = 0; i < getUpgradesHandler().getSlots(); i++) {
            applyUpgrade(i);
        }
    }

public boolean applyUpgrade(int slot) {
        AtomicBoolean atomic = new AtomicBoolean(false);
        ItemStack upgradeStack = getUpgradesHandler().getStackInSlot(slot);
        if(upgradeStack.getItem() instanceof UpgradeItem upgradeItem) {
            if(canAddUpgrade(upgradeItem)) {
                upgradeItem.getUpgrade().apply(this, slot, upgradeStack).ifPresent(upgrade -> {
                    this.upgrades.add(upgrade);
                    this.mappedUpgrades.put(slot, Optional.of(upgrade));
                    atomic.set(true);
                });
            }
        }
        return atomic.get();
    }

public boolean canAddUpgrade(UpgradeItem upgradeItem) {
        return upgrades.stream().noneMatch(u -> u.getClass().equals(upgradeItem.getUpgradeClass()));
    }

public void detectedChange(ItemStackHandler tracker, int slot) {
        boolean updatePosition = false;
        boolean needsUpdate = applyUpgrade(slot);

        //Update if tab changed status
        boolean changedTabStatus = getTabStatus(tracker.getStackInSlot(slot)) != getTabStatus(getUpgradesHandler().getStackInSlot(slot));
        boolean isTagSelector = isTagSelector(getUpgradesHandler().getStackInSlot(slot), tracker.getStackInSlot(slot));

        if(changedTabStatus || isTagSelector) {
            if(!needsUpdate && changedTabStatus) {
                updatePosition = true;
            }
            needsUpdate = true;
            ItemStack stackToSet = getUpgradesHandler().getStackInSlot(slot).copy();
            tracker.setStackInSlot(slot, stackToSet);
        }

        if(mappedUpgrades.containsKey(slot)) {
            if(!(getUpgradesHandler().getStackInSlot(slot).getItem() instanceof UpgradeItem)) {
                needsUpdate = this.invalidateUpgrade(slot);
                updatePosition = false;
            }
        }

        //Update menu and screen
        if(needsUpdate) {
            if(!getWrapper().getPlayersUsing().isEmpty()) {
                getWrapper().getPlayersUsing().stream().filter(player -> !player.level().isClientSide).forEach(player -> player.containerMenu.broadcastChanges());
            }
            if(!updatePosition) {
                getWrapper().requestMenuAndScreenUpdate();
            } else {
                getWrapper().requestMenuAndScreenUpdate(slot);
            }
        }
    }

public boolean invalidateUpgrade(int slot) {
        Optional<UpgradeBase<?>> upgrade = this.mappedUpgrades.get(slot);

        //Update upgrade tracker
        getWrapper().upgradesTracker.setStackInSlot(slot, ItemStack.EMPTY);

        //Error - item in slot is not an upgrade, just return
        if(upgrade == null) {
            return false;
        }

        upgrade.ifPresent(upg -> {
            this.mappedUpgrades.remove(slot);
            upg.remove();
            upgrades.remove(upg);
        });
        return true;
    }

