        return wrapper.getUnsortableSlots().contains(slot) ? ItemStack.EMPTY : parent.extractItem(slot, amount, simulate);
    }

public int matchesStack(ItemStack inserted, Pair<Integer, Pair<ItemStack, Boolean>> memorizedStack) {
        if(memorizedStack.getSecond().getSecond()) {
            return ItemStackUtils.isSameItemSameTags(inserted, memorizedStack.getSecond().getFirst()) ? memorizedStack.getFirst() : -1;
        } else {
            return ItemStack.isSameItem(inserted, memorizedStack.getSecond().getFirst()) ? memorizedStack.getFirst() : -1;
        }
    }

public static boolean isSameItemSameTags(ItemStack stack1, ItemStack stack2) {
        //Hose patch
        if(stack1.getItem() instanceof HoseItem && stack1.is(stack2.getItem())) return true;

        return isSameItemSameComponents(stack1, stack2);
    }

public static boolean isSameItemSameComponents(ItemStack pStack, ItemStack pOther) {
        if(!pStack.is(pOther.getItem())) {
            return false;
        } else {
            return pStack.isEmpty() && pOther.isEmpty() || checkComponentsIgnoreDamage(pStack.hasTag() ? pStack.getTag() : new CompoundTag(), pOther.hasTag() ? pOther.getTag() : new CompoundTag());
        }
    }

public static boolean checkComponentsIgnoreDamage(CompoundTag map, CompoundTag other) {
        CompoundTag mapCopy = map.copy();
        CompoundTag otherCopy = other.copy();
        mapCopy.remove("Damage");
        otherCopy.remove("Damage");
        return mapCopy.equals(otherCopy);
    }

public static void handle(ServerboundSlotPacket message, Supplier<NetworkEvent.Context> ctx) {
        ctx.get().enqueueWork(() -> {
            Player player = ctx.get().getSender();
            if(player instanceof ServerPlayer serverPlayer && serverPlayer.containerMenu instanceof BackpackSettingsMenu menu) {
                String syncKey = null;

                if(message.selectType == UNSORTABLES) {
                    menu.getWrapper().setUnsortableSlots((List<Integer>)message.slotsData);
                    syncKey = ModDataHelper.UNSORTABLE_SLOTS;
                }
                if(message.selectType == MEMORY) {
                    List<Pair<Integer, Pair<ItemStack, Boolean>>> oldMemoryStacks = menu.getWrapper().getMemorySlots();
                    List<Pair<Integer, Pair<ItemStack, Boolean>>> memoryStacks = new ArrayList<>();
                    for(Pair<Integer, Boolean> memorizedSlot : (List<Pair<Integer, Boolean>>)message.slotsData) {
                        ItemStack retrievedStack = memorizedSlot.getSecond() ? menu.getSlot(memorizedSlot.getFirst()).getItem() : menu.getSlot(memorizedSlot.getFirst()).getItem().getItem().getDefaultInstance();
                        if(retrievedStack.isEmpty()) {
                            for(Pair<Integer, Pair<ItemStack, Boolean>> oldMemorizedSlot : oldMemoryStacks) {
                                if(oldMemorizedSlot.getFirst().equals(memorizedSlot.getFirst())) {
                                    retrievedStack = oldMemorizedSlot.getSecond().getFirst();
                                    break;
                                }
                            }
                        }
                        if(retrievedStack.isEmpty()) {
                            continue; //not allowed in codec
                        }
                        memoryStacks.add(Pair.of(memorizedSlot.getFirst(), Pair.of(retrievedStack, memorizedSlot.getSecond())));
                    }
                    menu.getWrapper().setMemorySlots(memoryStacks);
                    syncKey = ModDataHelper.MEMORY_SLOTS;
                }

                //Update backpack data on clients
                if(syncKey != null) {
                    menu.getWrapper().sendDataToClients(syncKey);
                }
            }
        });

        ctx.get().setPacketHandled(true);
    }

public static ServerboundSlotPacket decode(FriendlyByteBuf buffer) {
        int selectType = buffer.readInt();
        List<?> slotsData = new ArrayList<>();
        if(selectType == UNSORTABLES) {
            slotsData = buffer.readIntIdList().intStream().boxed().collect(Collectors.toList());
        }
        if(selectType == MEMORY) {
            slotsData = NbtHelper.deserializeMemorySlotsPacket(buffer.readNbt());
        }
        return new ServerboundSlotPacket(selectType, slotsData);
    }

public static void encode(ServerboundSlotPacket message, FriendlyByteBuf buffer) {
        buffer.writeInt(message.selectType);
        List<?> slotsData = message.slotsData;
        if(message.selectType == UNSORTABLES) {
            List<Integer> unsortables = (List<Integer>)slotsData;
            buffer.writeIntIdList(new IntArrayList(unsortables.stream().mapToInt(Integer::intValue).toArray()));
        }
        if(message.selectType == MEMORY) {
            buffer.writeNbt(NbtHelper.serializeMemorySlotsPacket((List<Pair<Integer, Boolean>>)slotsData));
        }
    }

public static CompoundTag serializeMemorySlotsPacket(List<Pair<Integer, Boolean>> memorySlots) {
        ListTag nbtTagList = new ListTag();
        for(int i = 0; i < memorySlots.size(); i++) {
            CompoundTag pairTag = new CompoundTag();
            pairTag.putInt("Slot", memorySlots.get(i).getFirst());
            pairTag.putBoolean("matchNbt", memorySlots.get(i).getSecond());
            nbtTagList.add(pairTag);
        }
        CompoundTag tag = new CompoundTag();
        tag.put(ModDataHelper.MEMORY_SLOTS, nbtTagList);
        return tag;
    }

public static List<Pair<Integer, Boolean>> deserializeMemorySlotsPacket(CompoundTag tag) {
        ListTag tagList = tag.getList(ModDataHelper.MEMORY_SLOTS, Tag.TAG_COMPOUND);
        List<Pair<Integer, Boolean>> memorySlots = new ArrayList<>();
        for(int i = 0; i < tagList.size(); i++) {
            CompoundTag pairTag = tagList.getCompound(i);
            int index = pairTag.getInt("Slot");
            boolean matchNbt = pairTag.getBoolean("matchNbt");
            memorySlots.add(Pair.of(index, matchNbt));
        }
        return memorySlots;
    }

@NotNull
    @Override
    public <T> LazyOptional<T> getCapability(@NotNull final Capability<T> cap, @Nullable final Direction side) {
        Direction direction = getBlockDirection();
        if(cap == ForgeCapabilities.ITEM_HANDLER) {
            if(getWrapper() != BackpackWrapper.DUMMY) {
                return this.inventoryCapability.cast();
            }
            return LazyOptional.of(() -> new ItemStackHandler(0)).cast();
        }

        if(cap == ForgeCapabilities.FLUID_HANDLER) {
            if(getWrapper() != BackpackWrapper.DUMMY && getWrapper().getUpgradeManager().getUpgrade(TanksUpgrade.class).isPresent()) {
                if(side == null)
                    return this.leftFluidTankCapability.cast();

                if(direction == Direction.NORTH) {
                    switch(side) {
                        case WEST:
                            return this.rightFluidTankCapability.cast();
                        case EAST:
                            return this.leftFluidTankCapability.cast();
                    }
                }
                if(direction == Direction.SOUTH) {
                    switch(side) {
                        case EAST:
                            return this.rightFluidTankCapability.cast();
                        case WEST:
                            return this.leftFluidTankCapability.cast();
                    }
                }

                if(direction == Direction.EAST) {
                    switch(side) {
                        case NORTH:
                            return this.rightFluidTankCapability.cast();
                        case SOUTH:
                            return this.leftFluidTankCapability.cast();
                    }
                }

                if(direction == Direction.WEST) {
                    switch(side) {
                        case SOUTH:
                            return this.rightFluidTankCapability.cast();
                        case NORTH:
                            return this.leftFluidTankCapability.cast();
                    }
                }
                return this.leftFluidTankCapability.cast();
            }
            return LazyOptional.of(() -> new FluidTank(0)).cast();
        }
        return super.getCapability(cap, side);
    }

public ClientboundSyncCapabilityPacket(int entityID, ItemStack serverBackpack) {
        this(entityID, serverBackpack, false);
