@Nonnull
    @Override
    public Handler<PktRequestTeleport> handler() {
        return (packet, context, side) -> {
            context.enqueueWork(() -> {
                //TODO 1.16.2 re-check once worlds are not all constantly loaded
                PlayerEntity player = context.getSender();
                TileCelestialGateway gate = MiscUtils.getTileAt(player.world, Vector3.atEntityCorner(player).toBlockPos(), TileCelestialGateway.class, false);
                if (gate != null && gate.hasMultiblock() && gate.doesSeeSky()) {
                    MinecraftServer server = LogicalSidedProvider.INSTANCE.get(LogicalSide.SERVER);
                    if (server != null) {
                        World to = server.getWorld(packet.dim);
                        if (to != null) {
                            GatewayCache.GatewayNode node = DataAS.DOMAIN_AS.getData(to, DataAS.KEY_GATEWAY_CACHE).getGatewayNode(packet.pos);
                            if (node != null && node.hasAccess(player)) {
                                AstralSorcery.getProxy().scheduleDelayed(() -> MiscUtils.transferEntityTo(player, to.getDimensionKey(), packet.pos));
                            }
                        }
                    }
                }
            });
        };
    }

@Override
    public ActionResultType onBlockActivated(BlockState state, World world, BlockPos pos, PlayerEntity player, Hand hand, BlockRayTraceResult hit) {
        TileCelestialGateway gateway = MiscUtils.getTileAt(world, pos, TileCelestialGateway.class, false);
        if (gateway != null &&
                gateway.getOwner() != null &&
                gateway.getOwner().isPlayer(player)) {

            if (gateway.isLocked()) {
                if (!world.isRemote()) {
                    ItemStack remaining = ItemUtils.dropItemToPlayer(player, new ItemStack(ItemsAS.AQUAMARINE));
                    if (!remaining.isEmpty()) {
                        ItemUtils.dropItemNaturally(world, player.getPosX(), player.getPosY(), player.getPosZ(), remaining);
                    }
                    gateway.unlock();
                }
                return ActionResultType.SUCCESS;
            } else {
                ItemStack held = player.getHeldItem(hand);
                if (held.getItem() instanceof ItemAquamarine) {
                    if (!world.isRemote()) {
                        held.shrink(1);
                        gateway.lock();
                    }
                    return ActionResultType.SUCCESS;
                }
            }
        }
        return ActionResultType.PASS;
    }

@Override
    public void onReplaced(BlockState state, World world, BlockPos pos, BlockState newState, boolean moving) {
        if (state != newState && !world.isRemote()) {
            DataAS.DOMAIN_AS.getData(world, DataAS.KEY_GATEWAY_CACHE).removePosition(world, pos);
            TileCelestialGateway gateway = MiscUtils.getTileAt(world, pos, TileCelestialGateway.class, true);
            if (gateway != null && gateway.isLocked()) {
                ItemUtils.dropItemNaturally(world, pos.getX(), pos.getY(), pos.getZ(), new ItemStack(ItemsAS.AQUAMARINE));
            }
        }

        super.onReplaced(state, world, pos, newState, moving);
    }

@Nullable
    public static <T> T getTileAt(IBlockReader world, BlockPos pos, Class<T> tileClass, boolean forceChunkLoad) {
        if (world == null || pos == null) return null; //Duh.
        if (world instanceof IWorld) {
            if (!((IWorld) world).getChunkProvider().isChunkLoaded(new ChunkPos(pos)) && !forceChunkLoad) {
                return null;
            }
        }
        TileEntity te = world.getTileEntity(pos);
        if (te == null) return null;
        if (tileClass.isInstance(te)) return (T) te;
        return null;
    }

@Nullable
    public static <T extends Entity> T transferEntityTo(T entity, RegistryKey<World> target, BlockPos targetPos) {
        if (entity.getEntityWorld().isRemote) {
            return null; //No transfers on clientside.
        }
        entity.setSneaking(false);
        RegistryKey<World> src = entity.getEntityWorld().getDimensionKey();
        if (!src.equals(target)) {
            if (!ForgeHooks.onTravelToDimension(entity, target)) {
                return null;
            }

            MinecraftServer srv = LogicalSidedProvider.INSTANCE.get(LogicalSide.SERVER);
            ServerWorld targetWorld = srv.getWorld(target);
            if (targetWorld == null) {
                return null;
            }
            if (entity instanceof ServerPlayerEntity) {
                ((ServerPlayerEntity) entity).teleport(targetWorld,
                        targetPos.getX() + 0.5,
                        targetPos.getY() + 0.1,
                        targetPos.getZ() + 0.5,
                        entity.rotationYaw,
                        entity.rotationPitch);
            } else {
                entity = (T) entity.changeDimension(targetWorld, new NoOpTeleporter(targetWorld, targetPos));
                if (entity == null) {
                    return null;
                }
            }
        }
        entity.setPositionAndUpdate(targetPos.getX() + 0.5, targetPos.getY(), targetPos.getZ() + 0.5);
        return entity;
    }

