public static void handle(MessageMorphTome msg, Supplier<NetworkEvent.Context> ctx) {
		NetworkEvent.Context context = ctx.get();
		Player player = context.getSender();
		if (player != null) {
			context.enqueueWork(() -> {
				ItemStack tomeStack = player.getMainHandItem();
				InteractionHand hand = InteractionHand.MAIN_HAND;

				boolean hasTome = !tomeStack.isEmpty() && tomeStack.is(Registries.TOME.get());
				if (!hasTome) {
					tomeStack = player.getOffhandItem();
					hasTome = !tomeStack.isEmpty() && tomeStack.is(Registries.TOME.get());
					hand = InteractionHand.OFF_HAND;
				}

				if (hasTome) {
					ItemStack newStack = MorphingHandler.getShiftStackForMod(tomeStack, msg.modid);
					player.setItemInHand(hand, newStack);
				}
			});
		}
		context.setPacketHandled(true);
	}

public static void handle(MessageUnmorphTome msg, Supplier<NetworkEvent.Context> ctx) {
		NetworkEvent.Context context = ctx.get();
		Player player = context.getSender();
		if (player != null) {
			context.enqueueWork(() -> {
				ItemStack stack = player.getMainHandItem();
				if (!stack.isEmpty() && MorphingHandler.isAkashicTome(stack) && !stack.is(Registries.TOME.get())) {
					ItemStack newStack = MorphingHandler.getShiftStackForMod(stack, MorphingHandler.MINECRAFT);
					var inventory = player.getInventory();
					inventory.setItem(inventory.selected, newStack);
					AkashicTome.proxy.updateEquippedItem();
				}
			});
		}
		context.setPacketHandled(true);
	}

