@SubscribeEvent
	public void onItemBroken(PlayerDestroyItemEvent event) {
		removeItemFromTool(event.getEntity(), event.getOriginal(), true, (ItemStack morph) -> event.getEntity().setItemInHand(event.getHand(), morph));
	}

public static void removeItemFromTool(Entity e, ItemStack stack, boolean itemBroken, Consumer<ItemStack> consumer) {
		if (stack != null && !stack.isEmpty() && isMorphTool(stack) && !stack.is(Registries.MORPH_TOOL.get())) {
			CompoundTag morphData = stack.getTag().getCompound(TAG_MORPH_TOOL_DATA).copy();

			ItemStack morph = makeMorphedStack(stack, MINECRAFT, morphData);
			CompoundTag newMorphData = morph.getTag().getCompound(TAG_MORPH_TOOL_DATA);
			newMorphData.remove(getModFromStack(stack));

			if (!itemBroken) {
				if (!e.getCommandSenderWorld().isClientSide) {
					ItemEntity newItem = new ItemEntity(e.getCommandSenderWorld(), e.getX(), e.getY(), e.getZ(), morph);
					e.getCommandSenderWorld().addFreshEntity(newItem);
				}

				ItemStack copy = stack.copy();
				CompoundTag copyCmp = copy.getTag();
				if (copyCmp == null) {
					copyCmp = new CompoundTag();
					copy.setTag(copyCmp);
				}

				copyCmp.remove("display");

				copyCmp.remove(TAG_MORPHING_TOOL);
				copyCmp.remove(TAG_MORPH_TOOL_DISPLAY_NAME);
				copyCmp.remove(TAG_MORPH_TOOL_DATA);

				consumer.accept(copy);
			} else {
				consumer.accept(morph);
			}
		}
	}

public static HitResult raycast(Entity e, double len) {
		Vec3 vec = new Vec3(e.getX(), e.getY(), e.getZ());
		if (e instanceof Player) {
			vec = vec.add(new Vec3(0, e.getEyeHeight(), 0));
		}

		Vec3 look = e.getLookAngle();
		if (look == null) {
			return null;
		}

		return raycast(e, vec, look, len);
	}

public static HitResult raycast(Entity e, Vec3 origin, Vec3 ray, double len) {
		Vec3 end = origin.add(ray.normalize().scale(len));
		return e.getCommandSenderWorld().clip(new ClipContext(origin, end, ClipContext.Block.OUTLINE, ClipContext.Fluid.NONE, e));
	}

@Override
	public boolean matches(CraftingContainer var1, Level var2) {
		boolean foundTool = false;
		boolean foundTarget = false;

		for (int i = 0; i < var1.getContainerSize(); i++) {
			ItemStack stack = var1.getItem(i);
			if (!stack.isEmpty()) {
				if (isTarget(stack)) {
					if (foundTarget) {
						return false;
					}
					foundTarget = true;
				} else if (stack.is(Registries.MORPH_TOOL.get())) {
					if (foundTool) {
						return false;
					}
					foundTool = true;
				} else {
					return false;
				}
			}
		}

		return foundTool && foundTarget;
	}

@Override
	public ItemStack assemble(CraftingContainer var1, RegistryAccess pRegistryAccess) {
		ItemStack tool = ItemStack.EMPTY;
		ItemStack target = ItemStack.EMPTY;

		for (int i = 0; i < var1.getContainerSize(); i++) {
			ItemStack stack = var1.getItem(i);
			if (!stack.isEmpty()) {
				if (stack.is(Registries.MORPH_TOOL.get())) {
					tool = stack;
				} else {
					target = stack;
				}
			}
		}

		ItemStack copy = tool.copy();
		CompoundTag cmp = copy.getTag();
		if (cmp == null) {
			cmp = new CompoundTag();
			copy.setTag(cmp);
		}

		if (!cmp.contains(MorphingHandler.TAG_MORPH_TOOL_DATA)) {
			cmp.put(MorphingHandler.TAG_MORPH_TOOL_DATA, new CompoundTag());
		}

		CompoundTag morphData = cmp.getCompound(MorphingHandler.TAG_MORPH_TOOL_DATA);
		String mod = MorphingHandler.getModFromStack(target);

		if (morphData.contains(mod)) {
			return ItemStack.EMPTY;
		}

		CompoundTag modCmp = new CompoundTag();
		target.save(modCmp);
		morphData.put(mod, modCmp);

		return copy;
	}

public boolean isTarget(ItemStack stack) {
		if (stack.isEmpty() || MorphingHandler.isMorphTool(stack)) {
			return false;
		}

		String mod = MorphingHandler.getModFromStack(stack);
		if (mod.equals(MorphingHandler.MINECRAFT)) {
			return false;
		}

		if (ConfigHandler.allItems.get()) {
			return true;
		}

		if (ConfigHandler.blacklistedMods.get().contains(mod)) {
			return false;
		}

		ResourceLocation registryNameRL = ForgeRegistries.ITEMS.getKey(stack.getItem());
		String registryName = registryNameRL.toString();
		if (ConfigHandler.whitelistedItems.get().contains(registryName) || ConfigHandler.whitelistedItems.get().contains(registryName + ":" + stack.getDamageValue())) {
			return true;
		}

		String itemName = registryNameRL.getPath().toLowerCase();
		for (String s : ConfigHandler.whitelistedNames.get()) {
			if (itemName.contains(s.toLowerCase())) {
				return true;
			}
		}

		return false;
	}

