public InteractionResultHolder<ItemStack> use(Level worldIn, Player playerIn, InteractionHand handIn) {
        ItemStack itemstack = playerIn.getItemInHand(handIn);
        HitResult raytraceresult = getPlayerPOVHitResult(worldIn, playerIn, ClipContext.Fluid.ANY);
        if (raytraceresult.getType() == HitResult.Type.MISS) {
            return InteractionResultHolder.pass(itemstack);
        } else {
            Vec3 vector3d = playerIn.getViewVector(1.0F);
            double d0 = 5.0D;
            List<Entity> list = worldIn.getEntities(playerIn, playerIn.getBoundingBox().expandTowards(vector3d.scale(5.0D)).inflate(1.0D), ENTITY_PREDICATE);
            if (!list.isEmpty()) {
                Vec3 vector3d1 = playerIn.getEyePosition(1.0F);

                for (Entity entity : list) {
                    AABB axisalignedbb = entity.getBoundingBox().inflate(entity.getPickRadius());
                    if (axisalignedbb.contains(vector3d1)) {
                        return InteractionResultHolder.pass(itemstack);
                    }
                }
            }

            if (raytraceresult.getType() == HitResult.Type.BLOCK) {
                EntityStraddleboard boatentity = new EntityStraddleboard(worldIn, raytraceresult.getLocation().x, raytraceresult.getLocation().y, raytraceresult.getLocation().z);
                boatentity.setDefaultColor(!this.hasCustomColor(itemstack));
                boatentity.setItemStack(itemstack.copy());
                boatentity.setColor(this.getColor(itemstack));
                boatentity.setYRot(playerIn.getYRot());
                if (!worldIn.noCollision(boatentity, boatentity.getBoundingBox().inflate(-0.1D))) {
                    return InteractionResultHolder.fail(itemstack);
                } else {
                    if (!worldIn.isClientSide) {
                        worldIn.addFreshEntity(boatentity);
                        if (!playerIn.getAbilities().instabuild) {
                            itemstack.shrink(1);
                        }
                    }

                    playerIn.awardStat(Stats.ITEM_USED.get(this));
                    return InteractionResultHolder.sidedSuccess(itemstack, worldIn.isClientSide());
                }
            } else {
                return InteractionResultHolder.pass(itemstack);
            }
        }
    }

@Override
    public void onCompiled(ItemStack stack, ModularRouterBlockEntity router) {
        super.onCompiled(stack, router);
        router.addPermittedIds(getPlayerIDs(stack));
    }

private Set<UUID> getPlayerIDs(ItemStack stack) {
        CompoundTag compound = stack.getTag();
        if (compound == null) {
            return Collections.emptySet();
        }

        Set<UUID> res = Sets.newHashSet();
        UUID ownerID = getOwnerID(stack);
        if (ownerID == null) return Collections.emptySet();
        res.add(ownerID);

        if (compound.contains(NBT_PLAYERS)) {
            CompoundTag p = compound.getCompound(NBT_PLAYERS);
            res.addAll(p.getAllKeys().stream().map(UUID::fromString).toList());
        }
        return res;
    }

private static Result addPlayer(ItemStack stack, String id, String name) {
        CompoundTag compound = stack.getTag();
        if (compound != null) {
            if (!compound.contains(NBT_PLAYERS)) {
                compound.put(NBT_PLAYERS, new CompoundTag());
            }
            CompoundTag p = compound.getCompound(NBT_PLAYERS);
            if (p.contains(id)) {
                return Result.ALREADY_ADDED;  // already there, do nothing
            }
            if (p.size() >= MAX_PLAYERS) {
                return Result.FULL;  // items full
            }
            p.putString(id, name);
            return Result.ADDED;
        }
        return Result.ERROR;
    }

private static Result removePlayer(ItemStack stack, String id) {
        CompoundTag compound = stack.getTag();
        if (compound != null) {
            if (!compound.contains(NBT_PLAYERS)) {
                compound.put(NBT_PLAYERS, new CompoundTag());
            }
            CompoundTag p = compound.getCompound(NBT_PLAYERS);
            if (p.contains(id)) {
                p.remove(id);
                return Result.REMOVED;
            } else {
                return Result.NOT_PRESENT;
            }
        }
        return Result.ERROR;
    }

@Override
    public InteractionResultHolder<ItemStack> use(Level world, Player player, InteractionHand hand) {
        ItemStack stack = player.getItemInHand(hand);
        if (!player.getCommandSenderWorld().isClientSide && player.isSteppingCarefully()) {
            setOwner(stack, player);
            player.displayClientMessage(Component.translatable("modularrouters.itemText.security.owner", player.getDisplayName().getString()), false);
            return InteractionResultHolder.success(stack);
        }
        return InteractionResultHolder.pass(stack);
    }

@Override
    public InteractionResult interactLivingEntity(ItemStack stack, Player player, LivingEntity entity, InteractionHand hand) {
        if (entity instanceof Player targetPlayer) {
            String id = targetPlayer.getUUID().toString();
            String name = targetPlayer.getDisplayName().toString();
            Result res = player.isSteppingCarefully() ? removePlayer(stack, id) : addPlayer(stack, id, name);
            if (player.level().isClientSide) {
                player.playSound(res.isError() ? ModSounds.ERROR.get() : ModSounds.SUCCESS.get(),
                        ConfigHolder.client.sound.bleepVolume.get().floatValue(), 1.0f);
            } else {
                player.displayClientMessage(Component.translatable("modularrouters.chatText.security." + res.toString(), name), false);
            }
            return InteractionResult.SUCCESS;
        }
        return InteractionResult.PASS;
    }

default UUID getOwnerID(ItemStack stack) {
        if (!stack.hasTag() || !Objects.requireNonNull(stack.getTag()).contains(NBT_OWNER)) return null;

        ListTag l = stack.getTag().getList(NBT_OWNER, Tag.TAG_STRING);
        return UUID.fromString(l.getString(1));
    }

default String getOwnerName(ItemStack stack) {
        if (!stack.hasTag() || !Objects.requireNonNull(stack.getTag()).contains(NBT_OWNER)) return null;

        ListTag l = stack.getTag().getList(NBT_OWNER, Tag.TAG_STRING);
        return l.getString(0);
    }

default void setOwner(ItemStack stack, Player player) {
        CompoundTag compound = stack.getOrCreateTag();
        ListTag owner = new ListTag();
        owner.add(StringTag.valueOf(player.getDisplayName().getString()));
        owner.add(StringTag.valueOf(player.getUUID().toString()));
        compound.put(NBT_OWNER, owner);
        stack.setTag(compound);
    }

