public boolean mayProcreateAgain(long time) {
        int intTime = (int) time;
        Integer trackedValue = entity.getTrackedValue(LAST_PROCREATION);
        int delta = intTime - trackedValue;
        return trackedValue == 0 || delta < 0 || delta > Config.getInstance().procreationCooldown;
    }

public void startProcreating(long time) {
        procreateTick = 60;
        entity.setTrackedValue(IS_PROCREATING, true);
        entity.setTrackedValue(LAST_PROCREATION, (int) time);
    }

public void tick(int age) {
        if (age % 20 == 0) {
            pregnancy.tick();
        }

        if (!isProcreating()) {
            return;
        }

        if (procreateTick > 0) {
            procreateTick--;
            entity.getNavigation().stop();
            entity.getWorld().sendEntityStatus(entity, Status.VILLAGER_HEARTS);
        } else {
            getFamilyTree().getOrCreate(entity);
            getPartner().ifPresent(spouse -> {
                pregnancy.procreate(spouse);

                entity.setTrackedValue(IS_PROCREATING, false);
            });
        }
    }

private boolean handleSpecialCaseGift(ServerPlayerEntity player, ItemStack stack) {
        Item item = stack.getItem();

        if (item instanceof SpecialCaseGift) {
            if (((SpecialCaseGift) item).handle(player, entity)) {
                stack.decrement(1);
            }
            return true;
        }

        if (item == Items.CAKE && !entity.isBaby()) {
            if (pregnancy.tryStartGestation()) {
                player.getWorld().sendEntityStatus(entity, Status.VILLAGER_HEARTS);
                stack.decrement(1);
                entity.sendChatMessage(player, "gift.cake.success");
            } else {
                entity.sendChatMessage(player, "gift.cake.fail");
            }

            return true;
        }

        if (item == Items.GOLDEN_APPLE && entity.isInfected()) {
            entity.setInfected(false);
            entity.eatFood(entity.getWorld(), stack);
            return true;
        }

        if (item instanceof DyeItem dye) {
            entity.setHairDye(dye.getColor());
            stack.decrement(1);
            return true;
        }

        if (item == Items.WET_SPONGE) {
            entity.clearHairDye();
            stack.decrement(1);
            return true;
        }

        if (item == Items.NAME_TAG) {
            if (stack.hasCustomName()) {
                entity.setCustomSkin(stack.getName().getString());
            } else {
                entity.setCustomSkin("");
            }
            stack.decrement(1);
            return true;
        }

        if (item == Items.GOLDEN_APPLE && entity.isBaby()) {
            // increase age by 20 minutes
            entity.growUp(1200 * 20);
            stack.decrement(1);
            return true;
        }

        return false;
    }

@Override
    public void readCustomDataFromNbt(NbtCompound nbt) {
        super.readCustomDataFromNbt(nbt);
        getTypeDataManager().load(this, nbt);
        relations.readFromNbt(nbt);
        longTermMemory.readFromNbt(nbt);

        playerModel = PlayerModel.VALUES[nbt.getInt("playerModel")];

        updateSpeed();

        inventory.clear();
        InventoryUtils.readFromNBT(inventory, nbt);

        if (nbt.contains("DespawnDelay")) {
            this.despawnDelay = nbt.getInt("DespawnDelay");
        }

        if (nbt.contains("InteractedWith")) {
            this.interactedWith = nbt.getBoolean("InteractedWith");
        }

        if (nbt.contains("clothes")) {
            validateClothes();
        }

        if (getVillagerBrain().getPersonality() == Personality.UNASSIGNED) {
            getVillagerBrain().randomize();
        }
    }

@Override
    public final void writeCustomDataToNbt(NbtCompound nbt) {
        super.writeCustomDataToNbt(nbt);
        getTypeDataManager().save(this, nbt);
        relations.writeToNbt(nbt);
        longTermMemory.writeToNbt(nbt);
        nbt.putInt("DespawnDelay", this.despawnDelay);
        nbt.putBoolean("InteractedWith", this.interactedWith);
        InventoryUtils.saveToNBT(inventory, nbt);

        if (interactedWith) {
            VillagerTrackerManager.update(this);
        }
    }

@Override
    public void tickMovement() {
        tickHandSwing();

        super.tickMovement();

        burned--;
        if (isOnFire()) {
            burned = Config.getInstance().burnedClothingTickLength;
        }
        if (burned > 0) {
            spawnBurntParticles();
        }

        if (!getWorld().isClient) {
            if (age % 200 == 0
                    && getHealth() < getMaxHealth()
                    && !getBrain().getOptionalMemory(MemoryModuleType.ATTACK_TARGET).isPresent()) {
                // if the villager has food they should try to eat.
                ItemStack food = getMainHandStack();

                if (food.isFood()) {
                    eatFood(getWorld(), food);
                } else {
                    //noinspection ConstantConditions
                    if (!findAndEquipToMain(i -> i.isFood()
                                                 && i.getItem().getFoodComponent().getHunger() > 0
                                                 && i.getItem().getFoodComponent().getStatusEffects().stream().noneMatch(e -> StatusEffectDangerSet.isDanger.contains(e.getFirst().getEffectType())))) {
                        heal(1); // natural regeneration
                    }
                }
            }

            tickDespawnDelay();

            residency.tick();

            relations.tick(age);

            inventory.update(this);

            if (age % Config.getInstance().pardonPlayerTicks == 0) {
                pardonPlayers();
            }

            // Brain and pregnancy depend on the above states, so we tick them last
            // Every 1 second
            mcaBrain.think();

            // pop a item from the desaturation queue
            if (age % Config.getInstance().giftDesaturationReset == 0) {
                getRelationships().getGiftSaturation().pop();
            }

            // track the position from time to time
            if (interactedWith && age % Config.getInstance().trackVillagerPositionEveryNTicks == 0) {
                VillagerTrackerManager.update(this);
            }
        }
    }

@Nullable
    @Override
    public EntityData initialize(ServerWorldAccess world, LocalDifficulty difficulty, SpawnReason spawnReason, @Nullable EntityData entityData, @Nullable NbtCompound entityNbt) {
        EntityData data = super.initialize(world, difficulty, spawnReason, entityData, entityNbt);

        initialize(spawnReason);

        setAgeState(AgeState.byCurrentAge(getBreedingAge()));

        FamilyTreeNode entry = getRelationships().getFamilyEntry();
        if (!FamilyTreeNode.isValid(entry.father()) && !FamilyTreeNode.isValid(entry.mother())) {
            FamilyTree tree = FamilyTree.get(world.toServerWorld());
            FamilyTreeNode father = tree.getOrCreate(UUID.randomUUID(), Names.pickCitizenName(Gender.MALE), Gender.MALE);
            FamilyTreeNode mother = tree.getOrCreate(UUID.randomUUID(), Names.pickCitizenName(Gender.FEMALE), Gender.FEMALE);
            father.setDeceased(true);
            mother.setDeceased(true);
            entry.setFather(father);
            entry.setMother(mother);
        }

        return data;
    }

