                PlayerSave data = PlayerData.getDataFromPlayer(this.mc.player);
                data.didBookTutorial = true;
                PacketHandlerHelper.sendPlayerDataToServer(false, 1);
            }
        } else {
            super.actionPerformed(button);
        }
