@Override
    public double getDurabilityForDisplay(ItemStack stack) {
        EntityPlayer player = ActuallyAdditions.PROXY.getCurrentPlayer();
        if (player != null) {
            PlayerData.PlayerSave data = PlayerData.getDataFromPlayer(player);
            if (data != null) {
