		this.activateHeadsOnLoad(compound.getByteOr("NumHeads", (byte) 0));
		List<String> names = compound.read("HeadNames", Codec.STRING.listOf()).orElse(Collections.emptyList());
		if (!names.isEmpty()) {
			for (int i = 0; i < names.size(); i++) {
				String name = names.get(i);
				this.hc[i].headEntity.setCustomName(Component.literal(name));
			}
			this.getEntityData().set(HEAD_NAMES, names);
		}
	}

private void activateHeadsOnLoad(byte heads) {
		for (int i = 0; i < MAX_HEADS; i++) {
			if ((heads & 1 << i) != 0) {
				this.hc[i].setNextState(HydraHeadContainer.State.IDLE);
				this.hc[i].endCurrentAction();
			}
		}
	}

@Override
	public void addAdditionalSaveData(ValueOutput compound) {
		byte headData = 0;
		for (int i = 0; i < MAX_HEADS; i++) {
			if (this.hc[i].isActive()) {
				headData |= (byte) (1 << i);
			}
		}
		compound.putByte("NumHeads", headData);
		compound.store("HeadNames", Codec.STRING.listOf(), this.getEntityData().get(HEAD_NAMES));
		super.addAdditionalSaveData(compound);
	}

@Override
	protected void customServerAiStep(ServerLevel server) {
		super.customServerAiStep(server);
		this.xxa = 0.0F;
		this.zza = 0.0F;
		float f = 48.0F;


		if (this.ticksSinceDamaged > TICKS_BEFORE_HEALING && this.ticksSinceDamaged % 5 == 0) {
			this.heal(1);
		}

		// kill heads that have taken too much damage
		for (int i = 0; i < MAX_HEADS; i++) {
			if (!this.hc[i].isDead() && this.hc[i].getDamageTaken() > HEAD_MAX_DAMAGE) {
				this.hc[i].setNextState(HydraHeadContainer.State.DYING);
				this.hc[i].endCurrentAction();

				// set this head and a random dead head to respawn
				this.hc[i].setRespawnCounter(HEAD_RESPAWN_TICKS);
				int otherHead = this.getRandomDeadHead();
				if (otherHead != -1) {
					this.hc[otherHead].setRespawnCounter(HEAD_RESPAWN_TICKS);
				}
			}
		}

		if (this.getRandom().nextFloat() < 0.7F) {
			Player entityplayer1 = this.level().getNearestPlayer(this, f);

			if (entityplayer1 != null && !entityplayer1.isCreative()) {
				setTarget(entityplayer1);
				this.numTicksToChaseTarget = 100 + this.getRandom().nextInt(20);
			} else {
				this.randomYawVelocity = (this.getRandom().nextFloat() - 0.5F) * 20F;
			}
		}

		// destroy blocks
		this.destroyBlocksInAABB(server, this.body.getBoundingBox());
		this.destroyBlocksInAABB(server, this.tail.getBoundingBox());

		for (int i = 0; i < MAX_HEADS; i++) {
			if (!this.hc[i].isDead()) {
				this.destroyBlocksInAABB(server, this.hc[i].headEntity.getBoundingBox());
			}
		}

		// smash blocks beneath us too
		if (this.tickCount % 20 == 0) {
			if (this.isUnsteadySurfaceBeneath()) {
				this.destroyBlocksInAABB(server, this.getBoundingBox().move(0, -1, 0));
			}
		}

		if (this.getTarget() != null) {
			this.lookAt(this.getTarget(), 10.0F, this.getMaxHeadXRot());

			// have any heads not currently attacking switch to the primary target
			for (int i = 0; i < MAX_HEADS; i++) {
				if (!this.hc[i].isAttacking() && !this.hc[i].isSecondaryAttacking) {
					this.hc[i].setTargetEntity(this.getTarget());
				}
			}

			// let's pick an attack
			if (this.getTarget().isAlive()) {
				float distance = this.getTarget().distanceTo(this);

				if (this.getSensing().hasLineOfSight(this.getTarget())) {
					this.attackEntity(this.getTarget(), distance);
				}
			}

			if (this.numTicksToChaseTarget-- <= 0 || !this.getTarget().isAlive() || this.getTarget().distanceToSqr(this) > f * f) {
				this.setTarget(null);
			}
		} else {
			if (this.getRandom().nextFloat() < 0.05F) {
				this.randomYawVelocity = (this.getRandom().nextFloat() - 0.5F) * 20F;
			}

			this.setYRot(this.getYRot() + this.randomYawVelocity);
			this.setXRot(0);

			// TODO: while we are idle, consider having the heads breathe fire on passive mobs

			// set idle heads to no target
			for (int i = 0; i < MAX_HEADS; i++) {
				if (this.hc[i].isIdle()) {
					this.hc[i].setTargetEntity(null);
				}
			}
		}

		// heads that are free at this point may consider attacking secondary targets
		this.secondaryAttacks();
	}

public boolean attackEntityFromPart(HydraPart part, DamageSource source, float damage) {
		if (!(this.level() instanceof ServerLevel server)) {
			return false;
		}

		// if we're in a wall, kill that wall
		if (source.is(DamageTypes.IN_WALL)) {
			this.destroyBlocksInAABB(server, part.getBoundingBox());
		}

		if (source.getEntity() == this || source.getDirectEntity() == this)
			return false;
		if (this.getParts() != null)
			for (PartEntity<?> partEntity : this.getParts())
				if (partEntity == source.getEntity() || partEntity == source.getDirectEntity())
					return false;

		HydraHeadContainer headCon = null;

		for (int i = 0; i < MAX_HEADS; i++) {
			if (this.hc[i].headEntity == part) {
				headCon = this.hc[i];
			} else if (part instanceof HydraNeck neck && this.hc[i].headEntity == neck.head && this.hc[i].isDead())
				return false;
		}

		double range = this.calculateRange(source);

		// Give some leeway for reflected mortars
		if (range > 400 + (source.getDirectEntity() instanceof HydraMortar ? 200 : 0)) {
			return false;
		}

		// ignore hits on dying heads, it's weird
		if (headCon != null && headCon.isDead()) {
			return false;
		}

		boolean tookDamage;
		if (headCon != null && headCon.getCurrentMouthOpen() > 0.5) {
			tookDamage = super.hurtServer(server, source, damage);
			headCon.addDamage(damage);
		} else {
			int armoredDamage = Math.round(damage / ARMOR_MULTIPLIER);
			tookDamage = super.hurtServer(server, source, armoredDamage);

			if (headCon != null) {
				headCon.addDamage(armoredDamage);
			}
		}

		if (tookDamage) {
			this.ticksSinceDamaged = 0;
		}

		return tookDamage;
	}

@SuppressWarnings({"this-escape", "unchecked"})
	public HydraHeadContainer(Hydra hydra, int number, boolean startActive) {
		this.headNum = number;
		this.hydra = hydra;

		this.damageTaken = 0;
		this.respawnCounter = -1;

		this.headEntity = new HydraHead(hydra);
		this.headEntity.setPos(hydra.getX(), hydra.getY(), hydra.getZ());

		this.necka = new HydraNeck(this.headEntity);
		this.neckb = new HydraNeck(this.headEntity);
		this.neckc = new HydraNeck(this.headEntity);
		this.neckd = new HydraNeck(this.headEntity);
		this.necke = new HydraNeck(this.headEntity);

		// state positions, where is each state positioned?
		this.stateNeckLength = (Map<State, Float>[]) new Map<?, ?>[Hydra.MAX_HEADS];
		this.stateXRotations = (Map<State, Float>[]) new Map<?, ?>[Hydra.MAX_HEADS];
		this.stateYRotations = (Map<State, Float>[]) new Map<?, ?>[Hydra.MAX_HEADS];
		this.stateMouthOpen = (Map<State, Float>[]) new Map<?, ?>[Hydra.MAX_HEADS];

		for (int i = 0; i < Hydra.MAX_HEADS; i++) {
			this.stateNeckLength[i] = new EnumMap<>(State.class);
			this.stateXRotations[i] = new EnumMap<>(State.class);
			this.stateYRotations[i] = new EnumMap<>(State.class);
			this.stateMouthOpen[i] = new EnumMap<>(State.class);
		}

		this.setupStateRotations();

		if (startActive) {
			this.prevState = State.IDLE;
			this.currentState = State.IDLE;
			this.nextState = NEXT_AUTOMATIC;
			this.ticksNeeded = 60;
			this.ticksProgress = 60;
		} else {
			this.prevState = State.DEAD;
			this.currentState = State.DEAD;
			this.nextState = NEXT_AUTOMATIC;
			this.ticksNeeded = 20;
			this.ticksProgress = 20;
			if (!hydra.level().isClientSide()) {
				headEntity.deactivate();
				performOnAllNecks(HydraPart::deactivate);
			}
		}
		this.setHeadPosition();
		this.setNeckPosition();
	}

public void tick() {

		this.headEntity.tick();
		// neck updates
		this.performOnAllNecks(HydraPart::tick);

		// adjust for difficulty
		this.setDifficultyVariables();

		// only actually do these things on the server
		if (!this.hydra.level().isClientSide()) {
			// make sure this is set up
			if (!this.isDead() && this.headEntity.dimensions.width() == 0) {
				this.headEntity.activate();
				this.performOnAllNecks(HydraPart::activate);
			} else if (!this.isActive() && this.headEntity.dimensions.width() > 0) {
				this.headEntity.deactivate();
				this.performOnAllNecks(HydraPart::deactivate);
			}
			this.advanceRespawnCounter();
			this.advanceHeadState();
			this.setHeadPosition();
			this.setHeadFacing();
			this.executeAttacks();
			this.playSounds();
		} else {
			this.addMouthParticles();
		}
		this.animateHeadDeath();
		this.setNeckPosition();
	}

private void advanceRespawnCounter() {
		if (this.currentState == State.DEAD && this.respawnCounter > -1) {
			if (--this.respawnCounter <= 0) {
				this.setNextState(State.BORN);
				this.damageTaken = 0;
				this.endCurrentAction();
				this.respawnCounter = -1;
			}
		}
	}

private void advanceHeadState() {
		// check head state
		if (++this.ticksProgress >= this.ticksNeeded) {
			State myNext;

			// advance state
			if (this.nextState == NEXT_AUTOMATIC) {
				myNext = State.NEXT_STATE.get(this.currentState);
				if (myNext != this.currentState) {
					// when returning from a secondary attack, no attack cooldown
					if (this.isSecondaryAttacking && myNext == State.ATTACK_COOLDOWN) {
						this.isSecondaryAttacking = false;
						myNext = State.IDLE;
					}
				}
			} else {
				myNext = this.nextState;
				this.nextState = NEXT_AUTOMATIC;
			}

			this.ticksNeeded = myNext.duration;
			this.ticksProgress = 0;

			this.prevState = this.currentState;
			this.currentState = myNext;
		}
		// set datawatcher so client can properly animate
		if (this.headEntity.getState() != this.currentState) {
			this.headEntity.setState(this.currentState);
		}
	}

public void setNextState(State next) {
		this.nextState = next;
	}

public void endCurrentAction() {
		this.ticksProgress = this.ticksNeeded;
	}

public boolean isActive() {
		return this.currentState != State.DEAD;
	}

public boolean isDead() {
		return this.currentState == State.DYING || this.currentState == State.DEAD;
	}

public void addDamage(float damageAmount) {
		this.damageTaken += (int) damageAmount;
	}

