@Override
	public void performRitual(IMasterRitualStone masterRitualStone)
	{
		Level world = masterRitualStone.getWorldObj();

		if (world.isClientSide)
		{
			return;
		}

		AreaDescriptor itemRange = masterRitualStone.getBlockRange(CHECK_RANGE);

		List<ItemEntity> itemList = world.getEntitiesOfClass(ItemEntity.class, itemRange.getAABB(masterRitualStone.getMasterBlockPos()));

		for (ItemEntity entityItem : itemList)
		{
			if (!entityItem.isAlive())
			{
				continue;
			}

			ItemStack stack = entityItem.getItem();

			RecipeMeteor recipe = BloodMagicAPI.INSTANCE.getRecipeRegistrar().getMeteor(world, stack);
			if (recipe != null)
			{
				int syphonAmount = recipe.getSyphon();
				int currentEssence = masterRitualStone.getOwnerNetwork().getCurrentEssence();
//				syphonAmount = 0;

				if (currentEssence < syphonAmount)
				{
					return;
				}

				if (syphonAmount > 0)
					masterRitualStone.getOwnerNetwork().syphon(masterRitualStone.ticket(syphonAmount));

				EntityMeteor meteor = new EntityMeteor(world, masterRitualStone.getMasterBlockPos().getX() + 0.5, world.getMaxBuildHeight() + 10, masterRitualStone.getMasterBlockPos().getZ() + 0.5);
				meteor.lerpMotion(0, -0.1, 0);
				meteor.setContainedStack(stack.split(1));
				world.addFreshEntity(meteor);

				if (stack.isEmpty())
					entityItem.remove(RemovalReason.KILLED);

//				entityItem.getItem().setCount(newStack.getCount());

//				masterRitualStone.setActive(false);

				return;
			}
		}
	}

@Nullable
	public RecipeMeteor getMeteor(Level world, @Nonnull ItemStack input)
	{
		Preconditions.checkNotNull(input, "input cannot be null.");
		if (input.isEmpty())
			return null;

		List<RecipeMeteor> meteorRecipes = world.getRecipeManager().getAllRecipesFor(BloodMagicRecipeType.METEOR.get());
//		System.out.println("Number of recipes: " + meteorRecipes.size());

		for (RecipeMeteor recipe : meteorRecipes) if (recipe.getInput().test(input))
			return recipe;

		return null;
	}

public void spawnMeteorInWorld(Level world, BlockPos centerPos)
	{
		if (explosionRadius > 0)
			world.explode(null, centerPos.getX(), centerPos.getY(), centerPos.getZ(), explosionRadius, true, Level.ExplosionInteraction.TNT);

		Map<Integer, MeteorLayer> layerMap = new HashMap<>();
		for (MeteorLayer layer : layerList)
		{
			layerMap.put(layer.layerRadius, layer);
		}

		List<Integer> keyList = new ArrayList<>(layerMap.keySet());
		Collections.sort(keyList);

		int prevRadius = -1;
		for (int i = 0; i < keyList.size(); i++)
		{
			MeteorLayer layer = layerMap.get(keyList.get(i));
			layer.buildLayer(world, centerPos, prevRadius);
			prevRadius = layer.layerRadius;
		}
	}

public static MeteorLayer deserialize(JsonObject json)
	{
		int layerRadius = GsonHelper.getAsInt(json, Constants.JSON.RADIUS);
		int maxWeight = GsonHelper.getAsInt(json, Constants.JSON.ADDITIONAL_MAX_WEIGHT);
		int minWeight = GsonHelper.getAsInt(json, Constants.JSON.MIN_WEIGHT);
		List<Pair<RandomBlockContainer, Integer>> weightList = new ArrayList<>();

		if (json.has(Constants.JSON.WEIGHT_MAP) && GsonHelper.isArrayNode(json, Constants.JSON.WEIGHT_MAP))
		{
			JsonArray mainArray = GsonHelper.getAsJsonArray(json, Constants.JSON.WEIGHT_MAP);

			for (JsonElement element : mainArray)
			{
				JsonObject obj = element.getAsJsonObject();
				Pair<RandomBlockContainer, Integer> weightedEntry = RandomBlockContainer.deserializeWeightedPair(obj);
				if (weightedEntry != null)
				{
					weightList.add(weightedEntry);
				}
			}
		}

		// Includes logic for backwards compatibility
		RandomBlockContainer fillBlock = null;
		if (GsonHelper.isValidPrimitive(json, Constants.JSON.FILL))
		{
			fillBlock = RandomBlockContainer.parseEntry(GsonHelper.getAsString(json, Constants.JSON.FILL));
		} else
		{
			JsonObject fillObj = GsonHelper.getAsJsonObject(json, Constants.JSON.FILL);
			fillBlock = RandomBlockContainer.deserializeContainer(fillObj);
		}

		MeteorLayer layer = new MeteorLayer(layerRadius, maxWeight, weightList, fillBlock);
		if (GsonHelper.isValidNode(json, Constants.JSON.SHELL))
		{
			RandomBlockContainer shellBlock = null;
			if (GsonHelper.isValidPrimitive(json, Constants.JSON.SHELL))
			{
				shellBlock = RandomBlockContainer.parseEntry(GsonHelper.getAsString(json, Constants.JSON.SHELL));
			} else
			{
				JsonObject shellObj = GsonHelper.getAsJsonObject(json, Constants.JSON.SHELL);
				shellBlock = RandomBlockContainer.deserializeContainer(shellObj);
			}

			layer.addShellBlock(shellBlock);
		}

		layer.setMinWeight(minWeight);

		return layer;
	}

public void buildLayer(Level world, BlockPos centerPos, int emptyRadius)
	{
		recalculateMaxWeight(world.random, world);

		int radius = layerRadius;
		for (int i = -radius; i <= radius; i++)
		{
			for (int j = -radius; j <= radius; j++)
			{
				for (int k = -radius; k <= radius; k++)
				{
					if (emptyRadius >= 0 && checkIfSphere(emptyRadius, i, j, k))
					{
						continue;
					}

					if (checkIfSphere(radius, i, j, k))
					{
						BlockPos pos = centerPos.offset(i, j, k);
						BlockState currentState = world.getBlockState(pos);
						BlockPlaceContext ctx = new BlockPlaceContext(world, null, InteractionHand.MAIN_HAND, ItemStack.EMPTY, BlockHitResult.miss(new Vec3(0, 0, 0), Direction.UP, pos));
						if (!currentState.canBeReplaced(ctx))
						{
							continue;
						}
						if (shellBlock != null && checkIfSphereShell(radius, i, j, k))
						{
							world.setBlockAndUpdate(pos, shellBlock.getRandomBlock(world.random, world).defaultBlockState());
						} else
						{
							world.setBlockAndUpdate(pos, getRandomState(world.random, world));
						}
					}
				}
			}
		}
	}

public JsonObject serialize()
	{
		JsonObject json = new JsonObject();

		json.addProperty(Constants.JSON.RADIUS, layerRadius);
		json.addProperty(Constants.JSON.ADDITIONAL_MAX_WEIGHT, additionalTotalWeight);
		json.addProperty(Constants.JSON.MIN_WEIGHT, minWeight);

		if (weightList.size() > 0)
		{
			JsonArray mainArray = new JsonArray();
			for (Pair<RandomBlockContainer, Integer> weightedPair : weightList)
			{
				JsonObject jsonObj = weightedPair.getKey().serialize(weightedPair.getValue());

				mainArray.add(jsonObj);
			}

			json.add(Constants.JSON.WEIGHT_MAP, mainArray);
		}

		json.add(Constants.JSON.FILL, fillBlock.serialize());
		if (shellBlock != null)
		{
//			json.addProperty(Constants.JSON.SHELL, shellBlock.getEntry());
			json.add(Constants.JSON.SHELL, shellBlock.serialize());
		}

		return json;
	}

public static MeteorLayer read(@Nonnull FriendlyByteBuf buffer)
	{
		int layerRadius = buffer.readInt();
		int maxWeight = buffer.readInt();
		int minWeight = buffer.readInt();
		int listSize = buffer.readInt();
		List<Pair<RandomBlockContainer, Integer>> weightList = new ArrayList<>();
		for (int i = 0; i < listSize; i++)
		{
			String entry = buffer.readUtf();
			int weight = buffer.readInt();
			if (!entry.isEmpty())
			{
				RandomBlockContainer container = RandomBlockContainer.parseEntry(entry);

				weightList.add(Pair.of(container, weight));
			}
		}

		RandomBlockContainer fillBlock = RandomBlockContainer.parseEntry(buffer.readUtf());

		MeteorLayer layer = new MeteorLayer(layerRadius, maxWeight, weightList, fillBlock);
		String shellEntry = buffer.readUtf();
		if (!shellEntry.isEmpty())
		{
			layer.addShellBlock(RandomBlockContainer.parseEntry(shellEntry));
		}

		layer.setMinWeight(minWeight);

		return layer;
	}

public static RandomBlockContainer parseEntry(String str)
	{
		if (str.startsWith("#"))
		{
			String[] splitStr = str.split("#");

			int index = -1;
			String tagName = splitStr[1];
//			ForgeRegistries.BLOCKS.tags().tag
			TagKey<Block> tag = TagKey.create(Registries.BLOCK, new ResourceLocation(tagName));
//			TagKey<Block> tag = SerializationTags.getInstance().getBlocks().getTag(new ResourceLocation(tagName));

			if (splitStr.length > 2)
			{
				try
				{
					index = Integer.parseInt(splitStr[2]);
				} catch (NumberFormatException ex)
				{

				}
			}

			return new RandomBlockTagContainer(tag, index);
		} else if (str.startsWith(";"))
		{
			String[] splitStr = str.split(";");
			String fluidName = splitStr[1];

			return parseFluidEntry(fluidName);
		} else
		{
			return parseBlockEntry(str);
		}
	}

public static Pair<RandomBlockContainer, Integer> deserializeWeightedPair(JsonObject obj)
	{
		if (obj.has(Constants.JSON.TAG))
		{
			String entry = GsonHelper.getAsString(obj, Constants.JSON.TAG);
			int weight = GsonHelper.getAsInt(obj, Constants.JSON.WEIGHT);
			if (obj.has(Constants.JSON.INDEX))
			{
				// Using new method
				int tagIndex = GsonHelper.getAsInt(obj, Constants.JSON.INDEX);
				RandomBlockContainer container = RandomBlockContainer.parseTagEntry(entry, tagIndex);

				if (container != null)
				{
					return Pair.of(container, weight);
				}
			} else
			{
				// Using the old method of parsing the entry
				RandomBlockContainer container = RandomBlockContainer.parseEntry(entry);
//				ITag<Block> itag = TagCollectionManager.getManager().getBlockTags().get(new ResourceLocation(JSONUtils.getString(obj, Constants.JSON.TAG)));

				if (container != null)
				{
					return Pair.of(container, weight);
				}
			}
		} else if (obj.has(Constants.JSON.FLUID))
		{
			String entry = GsonHelper.getAsString(obj, Constants.JSON.FLUID);
			int weight = GsonHelper.getAsInt(obj, Constants.JSON.WEIGHT);
			RandomBlockContainer container = RandomBlockContainer.parseFluidEntry(entry);

			if (container != null)
			{
				return Pair.of(container, weight);
			}
		} else if (obj.has(Constants.JSON.BLOCK))
		{
			String entry = GsonHelper.getAsString(obj, Constants.JSON.BLOCK);
			int weight = GsonHelper.getAsInt(obj, Constants.JSON.WEIGHT);
			RandomBlockContainer container = RandomBlockContainer.parseBlockEntry(entry);

			if (container != null)
			{
				return Pair.of(container, weight);
			}
		}

		return null;
	}

public static RandomBlockContainer deserializeContainer(JsonObject obj)
	{
		if (obj.has(Constants.JSON.TAG))
		{
			String entry = GsonHelper.getAsString(obj, Constants.JSON.TAG);
			if (obj.has(Constants.JSON.INDEX))
			{
				// Using new method
				int tagIndex = GsonHelper.getAsInt(obj, Constants.JSON.INDEX);
				RandomBlockContainer container = RandomBlockContainer.parseTagEntry(entry, tagIndex);

				if (container != null)
				{
					return container;
				}
			} else
			{
				// Using the old method of parsing the entry
				RandomBlockContainer container = RandomBlockContainer.parseEntry(entry);
//				ITag<Block> itag = TagCollectionManager.getManager().getBlockTags().get(new ResourceLocation(JSONUtils.getString(obj, Constants.JSON.TAG)));

				if (container != null)
				{
					return container;
				}
			}
		} else if (obj.has(Constants.JSON.FLUID))
		{
			String entry = GsonHelper.getAsString(obj, Constants.JSON.FLUID);
			RandomBlockContainer container = RandomBlockContainer.parseFluidEntry(entry);

			if (container != null)
			{
				return container;
			}
		} else if (obj.has(Constants.JSON.BLOCK))
		{
			String entry = GsonHelper.getAsString(obj, Constants.JSON.BLOCK);
			RandomBlockContainer container = RandomBlockContainer.parseBlockEntry(entry);

			if (container != null)
			{
				return container;
			}
		}

		return null;
	}

public static RandomBlockContainer parseTagEntry(String str, int index)
	{
		TagKey<Block> tag = TagKey.create(Registries.BLOCK, new ResourceLocation(str));
		return new RandomBlockTagContainer(tag, index);
	}

public static RandomBlockContainer parseBlockEntry(String str)
	{
		Block block = ForgeRegistries.BLOCKS.getValue(new ResourceLocation(str));
		if (block == null)
		{
			return null;
		}

		return new StaticBlockContainer(block);
	}

public static RandomBlockContainer parseFluidEntry(String str)
	{
		String fluidName = str;
		Optional<Holder<Fluid>> holderOptional = ForgeRegistries.FLUIDS.getHolder(new ResourceLocation(fluidName));
		if (holderOptional.isPresent())
		{
			Fluid fluid = holderOptional.get().value();
			return new FluidBlockContainer(fluid);
		}

		return null;
	}

@Nonnull
	@Override
	public RECIPE fromJson(@Nonnull ResourceLocation recipeId, @Nonnull JsonObject json)
	{

		JsonElement input = GsonHelper.isArrayNode(json, Constants.JSON.INPUT)
				? GsonHelper.getAsJsonArray(json, Constants.JSON.INPUT)
				: GsonHelper.getAsJsonObject(json, Constants.JSON.INPUT);

		Ingredient inputIng = Ingredient.fromJson(input);

		int syphon = GsonHelper.getAsInt(json, Constants.JSON.SYPHON);
		float explosionRadius = GsonHelper.getAsInt(json, Constants.JSON.EXPLOSION);

		List<MeteorLayer> layerList = new ArrayList<>();
		if (json.has(Constants.JSON.LAYER) && GsonHelper.isArrayNode(json, Constants.JSON.LAYER))
		{
			JsonArray mainArray = GsonHelper.getAsJsonArray(json, Constants.JSON.LAYER);

			for (JsonElement element : mainArray)
			{
				JsonObject obj = element.getAsJsonObject();
				MeteorLayer layer = MeteorLayer.deserialize(obj);

				layerList.add(layer);
			}
		}

		return this.factory.create(recipeId, inputIng, syphon, explosionRadius, layerList);
	}

