public static MeteorLayer read(@Nonnull FriendlyByteBuf buffer)
	{
		int layerRadius = buffer.readInt();
		int maxWeight = buffer.readInt();
		int minWeight = buffer.readInt();
		int listSize = buffer.readInt();
		List<Pair<RandomBlockContainer, Integer>> weightList = new ArrayList<>();
		for (int i = 0; i < listSize; i++)
		{
			String entry = buffer.readUtf();
			int weight = buffer.readInt();
			if (!entry.isEmpty())
			{
				RandomBlockContainer container = RandomBlockContainer.parseEntry(entry);

				weightList.add(Pair.of(container, weight));
			}
		}

		RandomBlockContainer fillBlock = RandomBlockContainer.parseEntry(buffer.readUtf());

		MeteorLayer layer = new MeteorLayer(layerRadius, maxWeight, weightList, fillBlock);
		String shellEntry = buffer.readUtf();
		if (!shellEntry.isEmpty())
		{
			layer.addShellBlock(RandomBlockContainer.parseEntry(shellEntry));
		}

		layer.setMinWeight(minWeight);

		return layer;
	}

@Override
    public EnumActionResult onItemUseFirst(EntityPlayer player, World world, BlockPos pos, EnumFacing side, float hitX, float hitY, float hitZ, EnumHand hand) {
        ItemStack heldStack = player.getHeldItem(hand);
        if (player.isSneaking()) {
            TileEntity tileHit = world.getTileEntity(pos);
            if (tileHit != null && this.start.isInstance(tileHit)) {
                if (!world.isRemote) {

                    //Copy Slots
                    IItemHandlerModifiable chest = null;
                    if (tileHit instanceof IInventory) {
                        chest = new InvWrapper((IInventory) tileHit);
                    } else if (tileHit instanceof TileEntityInventoryBase) {
                        chest = ((TileEntityInventoryBase) tileHit).inv;
                    }

                    if (chest != null) {
                        ItemStack[] stacks = new ItemStack[chest.getSlots()];
                        for (int i = 0; i < stacks.length; i++) {
                            ItemStack aStack = chest.getStackInSlot(i);
                            stacks[i] = aStack.copy();
                        }

                        //Set New Block
                        world.playEvent(2001, pos, Block.getStateId(world.getBlockState(pos)));

                        world.removeTileEntity(pos);
                        world.setBlockState(pos, this.end, 2);
                        if (!player.capabilities.isCreativeMode) heldStack.shrink(1);

                        //Copy Items into new Chest
                        TileEntity newTileHit = world.getTileEntity(pos);
                        if (newTileHit instanceof TileEntityInventoryBase) {
                            IItemHandlerModifiable newChest = ((TileEntityInventoryBase) newTileHit).inv;

                            for (int i = 0; i < stacks.length; i++) {
                                if (StackUtil.isValid(stacks[i])) {
                                    if (newChest.getSlots() > i) {
                                        newChest.setStackInSlot(i, stacks[i].copy());
                                    }
                                }
                            }
                        }
                    }
                }
                return EnumActionResult.SUCCESS;
            }
        }

        return EnumActionResult.PASS;
    }

