public Map<String, Double> getConsolidatedModifierMap(Player player) {
		Map<String, Double> mapOut = new HashMap<>();
		if (player instanceof FakePlayer) return mapOut;		

		//BIOME Modification
		ResourceLocation biomeID = RegistryUtil.getId(player.level().getBiome(player.blockPosition()));
		for (Map.Entry<String, Double> modMap : getObjectModifierMap(ObjectType.BIOME, biomeID, ModifierDataType.BIOME, new CompoundTag()).entrySet()) {
			mapOut.merge(modMap.getKey(), modMap.getValue(), (o, n) -> {return o + (n-1);});
		}

		//DIMENSION Modification
		ResourceLocation dimensionID = player.level().dimension().location();
		for (Map.Entry<String, Double> modMap : getObjectModifierMap(ObjectType.DIMENSION, dimensionID, ModifierDataType.DIMENSION, new CompoundTag()).entrySet()) {
			mapOut.merge(modMap.getKey(), modMap.getValue(), (o, n) -> {return o + (n-1);});
		}

		Map<String, Double> modifiers = new HashMap<>();
		//HELD Modification
		for (ItemStack stack : List.of(player.getOffhandItem(), player.getMainHandItem())) {
			ResourceLocation itemID = RegistryUtil.getId(stack);
			modifiers = tooltips.bonusTooltipExists(itemID, ModifierDataType.HELD) 
					? tooltips.getBonusTooltipData(itemID, ModifierDataType.HELD, stack) 
					: getObjectModifierMap(ObjectType.ITEM, itemID, ModifierDataType.HELD, TagUtils.stackTag(stack));
			for (Map.Entry<String, Double> modMap : modifiers.entrySet()) {
				mapOut.merge(modMap.getKey(), modMap.getValue(), (o, n) -> {return o + (n-1);});
			}		
		}

		//WORN Modification
		List<ItemStack> wornItems = new ArrayList<>();
		player.getArmorSlots().forEach(wornItems::add);
		if (CurioCompat.hasCurio)
			CurioCompat.getItems(player).forEach(wornItems::add);
		wornItems.forEach((stack) -> {
			ResourceLocation itemID = RegistryUtil.getId(stack);
			Map<String, Double> modifers = tooltips.bonusTooltipExists(itemID, ModifierDataType.WORN) ?
					tooltips.getBonusTooltipData(itemID, ModifierDataType.WORN, stack):
					getObjectModifierMap(ObjectType.ITEM, itemID, ModifierDataType.WORN
							, stack.getTag() == null
								? new CompoundTag()
								: stack.getTag());
			for (Map.Entry<String, Double> modMap : modifers.entrySet()) {
				mapOut.merge(modMap.getKey(), modMap.getValue(), (o, n) -> {return o + (n-1);});
			}
		});

		MsLoggy.DEBUG.log(LOG_CODE.XP, "Modifier Map: {}", MsLoggy.mapToString(mapOut));
		return loader.PLAYER_LOADER.getData(new ResourceLocation(player.getUUID().toString()))
				.mergeWithPlayerBonuses(CoreUtils.processSkillGroupBonus(mapOut));
	}

public static Map<String, Integer> processSkillGroupReqs(Map<String, Integer> map) {
		new HashMap<>(map).forEach((skill, level) -> {
			SkillData data = SkillsConfig.SKILLS.get().getOrDefault(skill, SkillData.Builder.getDefault());
			if (data.isSkillGroup() && !data.getUseTotalLevels()) {
				map.remove(skill);
				data.getGroupReq(level).forEach((member, xp) -> {
					map.merge(member, xp, Integer::sum);
				});																						
			}
		});
		return map;
	}

public static Map<String, Long> processSkillGroupXP(Map<String, Long> map) {
		new HashMap<>(map).forEach((skill, baseXP) -> {
			SkillData data = SkillsConfig.SKILLS.get().getOrDefault(skill, SkillData.Builder.getDefault());
			if (data.isSkillGroup()) {
				map.remove(skill);
				data.getGroupXP(baseXP).forEach((member, xp) -> {
					map.merge(member, xp, Long::sum);
				});																					
			}
		});
		return  map;
	}

public static Map<String, Double> processSkillGroupBonus(Map<String, Double> map) {
		new HashMap<>(map).forEach((skill, level) -> {
			SkillData data = SkillsConfig.SKILLS.get().getOrDefault(skill, SkillData.Builder.getDefault());
			if (data.isSkillGroup()) {
				map.remove(skill);
				map.putAll(data.getGroupBonus(level));																					
			}
		});
		return map;
	}

public static Map<String, Long> deserializeAwardMap(CompoundTag nbt) {
		return new HashMap<>(CodecTypes.LONG_CODEC
				.parse(NbtOps.INSTANCE, nbt)
				.resultOrPartial(str -> MsLoggy.ERROR.log(LOG_CODE.API, "Error Deserializing Award Map from API: {}",str))
				.orElse(new HashMap<>()));
	}

public static Map<String, Long> mergeXpMapsWithSummateCondition(Map<String, Long> ogMap, Map<String, Long> newMap) {
		boolean summate = Config.SUMMATED_MAPS.get();
		if (!summate) return newMap;
		for (Map.Entry<String, Long> entry : newMap.entrySet()) {
			ogMap.merge(entry.getKey(), entry.getValue(), (a, b) -> a > b ? a : b);
		}
		return ogMap;
	}

public static Map<String, Long> applyXpModifiers(Map<String, Long> mapIn, Map<String, Double> modifiers) {
		modifiers.forEach((skill, modifier) -> {
			mapIn.computeIfPresent(skill, (key, xp) -> (long)(xp * modifier));
		});
		return mapIn;
	}

public void registerLevelProvider(BiFunction<String, Integer, Integer> provider) {
