public int process(String skill, int nativeLevel) {
		int outLevel = nativeLevel;
		for (BiFunction<String, Integer, Integer> provider : providers) {
			outLevel = provider.apply(skill, outLevel);
		}
		return outLevel;
	}

public CompoundTag executePerk(EventType cause, Player player, @NotNull CompoundTag dataIn) {
		if (player == null) return new CompoundTag();
		CompoundTag output = new CompoundTag();
		PerksConfig.PERK_SETTINGS.get().getOrDefault(cause, new ArrayList<>()).forEach(src -> {
			ResourceLocation perkID = new ResourceLocation(src.getString("perk"));
			Perk perk = perks.getOrDefault(perkID, Perk.empty());
			CompoundTag fullSrc = new CompoundTag()
					.merge(perk.propertyDefaults().copy())
					.merge(src.copy())
					.merge(dataIn.copy())
					.merge(output.copy());
			fullSrc.putInt(APIUtils.SKILL_LEVEL, fullSrc.contains(APIUtils.SKILLNAME)
					? Core.get(player.level()).getData().getPlayerSkillLevel(fullSrc.getString(APIUtils.SKILLNAME), player.getUUID())
					: 0);
			if (perk.canActivate(player, fullSrc)) {
				MsLoggy.DEBUG.log(LOG_CODE.FEATURE, "Perk Executed: %s".formatted(fullSrc.toString()));
				CompoundTag executionOutput = perk.start(player, fullSrc);
				tickTracker.add(new TickSchedule(perk, player, fullSrc.copy(), new AtomicInteger(0)));
				if (fullSrc.contains(APIUtils.COOLDOWN) && isPerkCooledDown(player, fullSrc))
					coolTracker.add(new PerkCooldown(perkID, player, fullSrc, player.level().getGameTime()));
				output.merge(executionOutput);
			}
		});
		return output;
	}

public boolean isPerkCooledDown(Player player, CompoundTag src) {
		ResourceLocation perkID = new ResourceLocation(src.getString("perk"));
		return coolTracker.stream().noneMatch(cd -> cd.player().equals(player) && cd.perkID().equals(perkID));
	}

public static void handle(PlayerLoggedInEvent event) {		
		Player player = event.getEntity();
		Core core = Core.get(player.level());

		if (core.getSide().equals(LogicalSide.SERVER)) {
			//===========UPDATE DATA MIRROR=======================
			Networking.sendToClient(new CP_ResetXP(), (ServerPlayer) player);
			for (Map.Entry<String, Long> skillMap : core.getData().getXpMap(player.getUUID()).entrySet()) {
				Networking.sendToClient(new CP_UpdateExperience(skillMap.getKey(), skillMap.getValue()), (ServerPlayer) player);
			}
			Networking.sendToClient(new CP_UpdateLevelCache(((PmmoSavedData)core.getData()).getLevelCache()), (ServerPlayer) player);
			Networking.sendToClient(new CP_SyncVein(VeinMiningLogic.getCurrentCharge(player)), (ServerPlayer) player);

			//===========EXECUTE FEATURE LOGIC====================
			((PmmoSavedData)core.getData()).awardScheduledXP(player.getUUID());
		}
		else {
			Networking.sendToServer(new SP_SetVeinLimit(Config.VEIN_LIMIT.get()));
		}
	}

public static void handle(LivingDeathEvent event) {
		//we can skip the heavier instanceof calculation if there is no loss on death
		if (Config.LOSS_ON_DEATH.get() == 0.0) return;

		//IMPORTANT  this is confirmed by the call in EventHandler.  this assumption is critical to this cast
		Player player = (Player) event.getEntity();
		Core core = Core.get(player.level());

		new HashMap<>(core.getData().getXpMap(player.getUUID())).forEach((skill, xp) -> {
			int currentLevel = core.getData().getLevelFromXP(xp);
			long levelXpThreshold = core.getData().getBaseXpForLevel(currentLevel);
			long safeXP = Config.LOSE_LEVELS_ON_DEATH.get() ? 0L : levelXpThreshold;
			long xpToCalculateLoss = Config.LOSE_ONLY_EXCESS.get() ? xp - safeXP : xp;

			long rawLoss = Double.valueOf((double)xpToCalculateLoss * Config.LOSS_ON_DEATH.get()).longValue();
			long finalXp = Math.max(safeXP, xp - rawLoss);

			core.getData().setXpRaw(player.getUUID(), skill, finalXp);
		});
	}

