public static List<ServerPlayer> getPartyMembers(ServerPlayer player) {
		if (player.getTeam() == null)
			return List.of(player);
		else
			return player.getTeam().getPlayers().stream()
				.map(str -> player.getServer().getPlayerList().getPlayerByName(str))
				.filter(Objects::nonNull).toList();
	}

public static List<ServerPlayer> getPartyMembersInRange(ServerPlayer player) {
		List<ServerPlayer> inRange = new ArrayList<>();
		for (ServerPlayer member : getPartyMembers(player)) {
			if (Config.PARTY_RANGE.get() == -2
					|| (Config.PARTY_RANGE.get() == -1 && player.level().equals(member.level()))
					|| player.position().distanceTo(member.position()) <= Config.PARTY_RANGE.get())
				inRange.add(member);
		}
		return inRange;
	}

public void awardXP(List<ServerPlayer> players, Map<String, Long> xpValues) {
		CoreUtils.processSkillGroupXP(xpValues);

		new HashMap<>(xpValues).forEach((skill, value) -> {
			xpValues.put(skill, (long)((double)value * Config.SKILL_MODIFIERS.get().getOrDefault(skill, Config.GLOBAL_MODIFIER.get())));
		});
		for (int i = 0; i < players.size(); i++) {
			if (players.get(i) instanceof FakePlayer || players.get(i).isDeadOrDying()) continue;
			for (Map.Entry<String, Long> award : xpValues.entrySet()) {
				long xpAward = award.getValue();
				if (players.size() > 1)
					xpAward = Double.valueOf((double)xpAward * (Config.partyBonus(award.getKey()) * (double)players.size())).longValue();
				getData().setXpDiff(players.get(i).getUUID(), award.getKey(), xpAward/players.size());
			}
		}
	  }

