public boolean doesPlayerMeetReq(UUID playerID, Map<String, Integer> requirements) {
		//convert skill groups which do not use total levels into constituent skills
		CoreUtils.processSkillGroupReqs(requirements);
		for (Map.Entry<String, Integer> req : requirements.entrySet()) {
			int skillLevel = getData().getPlayerSkillLevel(req.getKey(), playerID);
			if (SkillsConfig.SKILLS.get().getOrDefault(req.getKey(), SkillData.Builder.getDefault()).isSkillGroup()) {	
				SkillData skillData = SkillsConfig.SKILLS.get().get(req.getKey());
				if (skillData.getUseTotalLevels()) {
					int total = skillData.getGroup().keySet().stream().map(skill -> getData().getPlayerSkillLevel(skill, playerID)).mapToInt(Integer::intValue).sum();
					if (req.getValue() > total) {
						MsLoggy.DEBUG.log(LOG_CODE.REQ, "Req not met.  required {} but only {} in {} skill", req.getValue(), total, req.getKey());
						return false;
					}
				}
			}
			else if (req.getValue() > skillLevel)
				return false;
		}
		return true;
	}

@Override
	public boolean setXpDiff(UUID playerID, String skillName, long change) {
		long oldValue = getXpRaw(playerID, skillName);
		ServerPlayer player = ServerLifecycleHooks.getCurrentServer().getPlayerList().getPlayer(playerID);

		//if player is not online, schedule the XP for player join.
		if (player == null) {
			scheduledXP.computeIfAbsent(playerID, (id) -> new HashMap<>()).merge(skillName, change, (o, n) -> o + n);
			return true;
		}
		//If player is online proceed with xp events, perks and committing xp to master map
		XpEvent gainXpEvent = new XpEvent(player, skillName, oldValue, change, TagBuilder.start().build());
		if (MinecraftForge.EVENT_BUS.post(gainXpEvent))
			return false;

		setXpRaw(playerID, gainXpEvent.skill, oldValue + gainXpEvent.amountAwarded);
		return true;
	}

@Override
	public void setXpRaw(UUID playerID, String skillName, long value) {
		long formerRaw = getLevelFromXP(getXpRaw(playerID, skillName));
		xp.computeIfAbsent(playerID, s -> new HashMap<>()).put(skillName, value);
		this.setDirty();
		ServerPlayer player;
		if ((player = ServerLifecycleHooks.getCurrentServer().getPlayerList().getPlayer(playerID)) != null) {
			Networking.sendToClient(new CP_UpdateExperience(skillName, value), player);
			MsLoggy.DEBUG.log(LOG_CODE.XP, "Skill Update Packet sent to Client"+playerID.toString());
			//capture command cases for XP gain which should prompt a skillup event
			long newLevel = getLevelFromXP(value);
			if (formerRaw < newLevel) {
				SkillUpTrigger.SKILL_UP.trigger(player);
				Core.get(LogicalSide.SERVER).getPerkRegistry().executePerk(EventType.SKILL_UP, player,
					TagBuilder.start().withString(FireworkHandler.FIREWORK_SKILL, skillName).build());
			}
			else if (formerRaw > newLevel) {
				Core.get(LogicalSide.SERVER).getPerkRegistry().executePerk(EventType.SKILL_DOWN, player,
						TagBuilder.start().withString(FireworkHandler.FIREWORK_SKILL, skillName).build());
			}
		}
	}

public void awardScheduledXP(UUID playerID) {
		//Clone the original scheduled XP so that we can remove the original
		//This is vital because a disconnect while this is running would result in 
		//the player having their scheduledXP rescheduled, and we cannot modify
		//a collection whilst iterating over it.
		Map<String, Long> queue = new HashMap<>(scheduledXP.getOrDefault(playerID, new HashMap<>()));
		scheduledXP.remove(playerID);
		for (Map.Entry<String, Long> scheduledValue : queue.entrySet()) {
			setXpDiff(playerID, scheduledValue.getKey(), scheduledValue.getValue());
		}
	}

public static Map<String, Long> processSkillGroupXP(Map<String, Long> map) {
		new HashMap<>(map).forEach((skill, baseXP) -> {
			SkillData data = SkillsConfig.SKILLS.get().getOrDefault(skill, SkillData.Builder.getDefault());
			if (data.isSkillGroup()) {
				map.remove(skill);
				data.getGroupXP(baseXP).forEach((member, xp) -> {
					map.merge(member, xp, Long::sum);
				});																					
			}
		});
		return  map;
	}

public CompoundTag executePerk(EventType cause, Player player, @NotNull CompoundTag dataIn) {
		if (player == null) return new CompoundTag();
		CompoundTag output = new CompoundTag();
		PerksConfig.PERK_SETTINGS.get().getOrDefault(cause, new ArrayList<>()).forEach(src -> {
			ResourceLocation perkID = new ResourceLocation(src.getString("perk"));
			Perk perk = perks.getOrDefault(perkID, Perk.empty());
			CompoundTag fullSrc = new CompoundTag()
					.merge(perk.propertyDefaults().copy())
					.merge(src.copy())
					.merge(dataIn.copy())
					.merge(output.copy());
			fullSrc.putInt(APIUtils.SKILL_LEVEL, fullSrc.contains(APIUtils.SKILLNAME)
					? Core.get(player.level()).getData().getPlayerSkillLevel(fullSrc.getString(APIUtils.SKILLNAME), player.getUUID())
					: 0);
			if (perk.canActivate(player, fullSrc)) {
				MsLoggy.DEBUG.log(LOG_CODE.FEATURE, "Perk Executed: %s".formatted(fullSrc.toString()));
				CompoundTag executionOutput = perk.start(player, fullSrc);
				tickTracker.add(new TickSchedule(perk, player, fullSrc.copy(), new AtomicInteger(0)));
				if (fullSrc.contains(APIUtils.COOLDOWN) && isPerkCooledDown(player, fullSrc))
					coolTracker.add(new PerkCooldown(perkID, player, fullSrc, player.level().getGameTime()));
				output.merge(executionOutput);
			}
		});
		return output;
	}

public boolean isPerkCooledDown(Player player, CompoundTag src) {
		ResourceLocation perkID = new ResourceLocation(src.getString("perk"));
		return coolTracker.stream().noneMatch(cd -> cd.player().equals(player) && cd.perkID().equals(perkID));
	}

