@Nullable
	@Override
	public Object getServerGuiElement(int id, EntityPlayer player, World world, int x, int y, int z) {
		TileEntity te;
		switch (id) {
			case POUCH_ID:
				return new ContainerPouch(player, true);
			case QUIVER_ID:
				return new ContainerQuiver(player);
			case CRAFTER_ID:
				te = world.getTileEntity(new BlockPos(x, y, z));
				if (te instanceof TileEntityFeyCrafter) {
					return new ContainerFeyCrafter(player, (TileEntityFeyCrafter) te);
				} else {
					return null;
				}
			case IMPOSER_ID:
				te = world.getTileEntity(new BlockPos(x, y, z));
				if (te instanceof TileEntityImposer) {
					((TileEntityImposer) te).updateInSlot(player);
					return new ContainerImposer(player, (TileEntityImposer) te);
				} else {
					return null;
				}
			case LIBRARY_ID:
				Supplier<ItemStack> staff = getStaff(player);
				if (staff != null) {
					SpellUtil.updateModifiers(staff.get(), player);
					PlayerSyncUtil.syncPlayer(player);
					return new ContainerLibrary(player, staff, SpellLibraryRegistry.getData(player));
				} else {
					player.sendStatusMessage(new TextComponentTranslation("roots.message.hold_staff").setStyle(new Style().setColor(TextFormatting.LIGHT_PURPLE).setBold(true)), true);
					return null;
				}
		}
		return null;
	}

@SubscribeEvent
	public static void onEntityItemPickup(EntityItemPickupEvent event) {
		if (GeneralConfig.AutoRefillPouches) {
			EntityPlayer player = event.getEntityPlayer();
			EntityItem entity = event.getItem();
			if (!entity.world.isRemote) {
				ItemStack stack = entity.getItem().copy();
				Item item = stack.getItem();
				int original = stack.getCount();
				if (HerbRegistry.isHerb(item)) {
					boolean modified = false;
					List<ItemStack> pouches = ServerHerbUtil.getPouches(player);
					for (ItemStack pouch : pouches) {
						PouchHandler handler = PouchHandler.getHandler(pouch);
						int refill = handler.refill(stack);
						if (refill < original) {
							modified = true;
							stack.setCount(refill);
							original = refill;
						}
					}
					if (modified) {
						event.setCanceled(true);
						entity.setDead();
						entity.world.playSound(null, player.getPosition(), SoundEvents.ENTITY_ITEM_PICKUP, SoundCategory.PLAYERS, 0.6f, 0.5f);
						if (!stack.isEmpty()) {
							EntityItem newEntity = new EntityItem(entity.world, entity.posX, entity.posY, entity.posZ, stack);
							newEntity.motionX = entity.motionX;
							newEntity.motionY = entity.motionY;
							newEntity.motionZ = entity.motionZ;
							newEntity.setPickupDelay(0);
							entity.world.spawnEntity(newEntity);
						}
					}
				}
			}
		}
	}

public boolean costsMet(EntityPlayer player, StaffModifierInstanceList modifiers) {
		boolean matches = true;
		for (Map.Entry<Herb, Double> entry : modifiers.apply(this.costs).entrySet()) {
			Herb herb = entry.getKey();
			double d = entry.getValue();
			if (matches) {
				double r;
				if (!player.world.isRemote) {
					r = ServerHerbUtil.getHerbAmount(player, herb);
				} else {
					r = ClientHerbUtil.getHerbAmount(herb);
				}
				matches = r >= d;
				if (!matches && !player.isCreative()) {
					if (r == -1.0) {
						if (!player.world.isRemote) {
							player.sendStatusMessage(new TextComponentTranslation("roots.info.pouch.no_pouch").setStyle(new Style().setColor(TextFormatting.RED)), true);
						}
					} else {
						if (!player.world.isRemote) {
							player.sendStatusMessage(new TextComponentTranslation("roots.info.pouch.no_herbs", new TextComponentTranslation(String.format("item.%s.name", herb.getName()))), true);
						}
					}
				}
			}
		}
		return matches && costs.size() > 0 || player.capabilities.isCreativeMode;
	}

public void enactCosts(EntityPlayer player, StaffModifierInstanceList modifiers) {
		for (Map.Entry<Herb, Double> entry : modifiers.apply(this.costs).entrySet()) {
			Herb herb = entry.getKey();
			double d = entry.getValue();
			ServerHerbUtil.removePowder(player, herb, d);
		}
	}

public void enactTickCosts(EntityPlayer player, StaffModifierInstanceList modifiers) {
		for (Map.Entry<Herb, Double> entry : modifiers.apply(this.costs).entrySet()) {
			Herb herb = entry.getKey();
			double d = entry.getValue();
			ServerHerbUtil.removePowder(player, herb, d / 20.0);
		}
	}

@Nonnull
	@Override
	public ActionResult<ItemStack> onItemRightClick(World world, EntityPlayer player, @Nonnull EnumHand hand) {
		ItemStack stack = player.getHeldItem(hand);
		StaffSpellStorage capability = StaffSpellStorage.fromStack(stack);
		if (player.isSneaking() && capability != null) {
			return new ActionResult<>(EnumActionResult.SUCCESS, nextSlot(world, player, stack, capability));
		} else {
			if (capability != null && !capability.onCooldown()) {
				StaffSpellInfo info = capability.getSelectedInfo();
				if (info != null) {
					SpellBase spell = info.getSpell();
					if (spell != null && spell.getCastType() != SpellBase.EnumCastType.CONTINUOUS) {
						if (spell.getCastType() == SpellBase.EnumCastType.INSTANTANEOUS) {
							if (spell.costsMet(player, info.getModifiers())) {
								SpellBase.CastResult result = spell.cast(player, info, 0);
								if (result.isSuccess()) {
									if (!player.capabilities.isCreativeMode && !world.isRemote) {
										spell.enactCosts(player, info.getModifiers());
										capability.setCooldown(result.modifyCooldown(info.cooldownTotal()) + player.world.getTotalWorldTime());
									}
								}
							}
							return new ActionResult<>(EnumActionResult.SUCCESS, stack);
						}
					} else if (spell != null && spell.getCastType() == SpellBase.EnumCastType.CONTINUOUS) {
						player.setActiveHand(hand);
						return new ActionResult<>(EnumActionResult.SUCCESS, stack);
					}
				}
			}
		}
		return new ActionResult<>(EnumActionResult.FAIL, player.getHeldItem(hand));
	}

@Override
	public void onUsingTick(ItemStack stack, EntityLivingBase player, int count) {
		StaffSpellStorage capability = StaffSpellStorage.fromStack(stack);
		if (player instanceof EntityPlayer && capability != null) {
			StaffSpellInfo info = capability.getSelectedInfo();
			SpellBase spell = info == null ? null : info.getSpell();
			if (spell != null) {
				if (spell.getCastType() == SpellBase.EnumCastType.CONTINUOUS) {
					if (spell.costsMet((EntityPlayer) player, info.getModifiers())) {
						SpellBase.CastResult result = spell.cast((EntityPlayer) player, info, count);
						if (result.isSuccess() && !player.world.isRemote) {
							spell.enactTickCosts((EntityPlayer) player, info.getModifiers());
						}
					}
				}
			}
		}
	}

