public boolean costsMet(EntityPlayer player, StaffModifierInstanceList modifiers) {
		boolean matches = true;
		for (Map.Entry<Herb, Double> entry : modifiers.apply(this.costs).entrySet()) {
			Herb herb = entry.getKey();
			double d = entry.getValue();
			if (matches) {
				double r;
				if (!player.world.isRemote) {
					r = ServerHerbUtil.getHerbAmount(player, herb);
				} else {
					r = ClientHerbUtil.getHerbAmount(herb);
				}
				matches = r >= d;
				if (!matches && !player.isCreative()) {
					if (r == -1.0) {
						if (!player.world.isRemote) {
							player.sendStatusMessage(new TextComponentTranslation("roots.info.pouch.no_pouch").setStyle(new Style().setColor(TextFormatting.RED)), true);
						}
					} else {
						if (!player.world.isRemote) {
							player.sendStatusMessage(new TextComponentTranslation("roots.info.pouch.no_herbs", new TextComponentTranslation(String.format("item.%s.name", herb.getName()))), true);
						}
					}
				}
			}
		}
		return matches && costs.size() > 0 || player.capabilities.isCreativeMode;
	}

public void enactCosts(EntityPlayer player, StaffModifierInstanceList modifiers) {
		for (Map.Entry<Herb, Double> entry : modifiers.apply(this.costs).entrySet()) {
			Herb herb = entry.getKey();
			double d = entry.getValue();
			ServerHerbUtil.removePowder(player, herb, d);
		}
	}

public void enactTickCosts(EntityPlayer player, StaffModifierInstanceList modifiers) {
		for (Map.Entry<Herb, Double> entry : modifiers.apply(this.costs).entrySet()) {
			Herb herb = entry.getKey();
			double d = entry.getValue();
			ServerHerbUtil.removePowder(player, herb, d / 20.0);
		}
	}

public CastResult cast(EntityPlayer caster, StaffSpellInfo info, int ticks) {
		StaffModifierInstanceList mods = info.getModifiers();

		CastResult result = CastResult.FAIL;

		if (cast(caster, info.getModifiers(), ticks)) {
			result = CastResult.SUCCESS;
		}

		if (result != CastResult.FAIL && !caster.world.isRemote && (ticks == 0 || ticks == 72000)) {
			SoundEvent event = this.getCastSound();
			if (event != null && shouldPlaySound()) {
				caster.world.playSound(null, caster.getPosition(), event, SoundCategory.PLAYERS, getSoundVolume(), 1);
			}
		}
		return result;
	}

private SpellAugment(ResourceLocation name) {
		super(name, TextFormatting.AQUA, 69 / 255.0f, 209 / 255.0f, 127 / 255.0f, 28 / 255.0f, 28 / 255.0f, 148 / 255.0f);
		properties.add(PROP_COOLDOWN, PROP_CAST_TYPE, PROP_COST_1, PROP_RADIUS_X, PROP_RADIUS_Y, PROP_RADIUS_Z, PROP_REACH, PROP_REACH_DURATION, PROP_SPEED_AMPLIFIER, PROP_SPEED_DURATION, PROP_SLOW_FALL_DURATION, PROP_DRIFTER_DURATION, PROP_LUCK_AMPLIFIER, PROP_LUCK_DURATION, PROP_AIR_AMOUNT, PROP_STRENGTH_AMPLIFIER, PROP_STRENGTH_DURATION, PROP_HASTE_AMPLIFIER, PROP_HASTE_DURATION, PROP_ABSORPTION_AMPLIFIER, PROP_ABSORPTION_DURATION);
		acceptModifiers(REACH, SPEED, SLOW_FALL, LIGHT_DRIFTER, MAGNETISM, LUCK, ABSORPTION, STRENGTH, HASTE, SECOND_WIND);
	}

@Override
	public boolean cast(EntityPlayer player, StaffModifierInstanceList info, int ticks) {
		// TODO: Particle
		boolean acted = false;
		if (info.has(REACH)) {
			acted = true;
			player.addPotionEffect(new PotionEffect(ModPotions.reach, reach_duration, 0, false, false));
		}
		if (info.has(SPEED)) {
			acted = true;
			player.addPotionEffect(new PotionEffect(MobEffects.SPEED, speed_duration, speed_amplifier, false, false));
		}
		if (info.has(SLOW_FALL)) {
			acted = true;
			player.addPotionEffect(new PotionEffect(ModPotions.slow_fall, slow_fall, 0, false, false));
		}
		if (info.has(LIGHT_DRIFTER)) {
			acted = true;
			if (!player.world.isRemote) {
				player.capabilities.disableDamage = true;
				player.capabilities.allowFlying = true;
				player.noClip = true;
				player.getEntityData().setInteger(LIGHT_DRIFTER_TAG, drifter_duration);
				player.getEntityData().setDouble(LIGHT_DRIFTER_X, player.posX);
				player.getEntityData().setDouble(LIGHT_DRIFTER_Y, player.posY + 0.5);
				player.getEntityData().setDouble(LIGHT_DRIFTER_Z, player.posZ);
				player.getEntityData().setInteger(LIGHT_DRIFTER_DIMENSION_ID, player.dimension);
				if (player.capabilities.isCreativeMode) {
					player.getEntityData().setInteger(LIGHT_DRIFTER_MODE, GameType.CREATIVE.getID());
				} else {
					player.getEntityData().setInteger(LIGHT_DRIFTER_MODE, GameType.SURVIVAL.getID());
				}
				player.setGameType(GameType.SPECTATOR);
				PacketHandler.sendToAllTracking(new MessageLightDrifterSync(player.getUniqueID(), player.posX, player.posY, player.posZ, true, GameType.SPECTATOR.getID(), player.dimension), player);
				PacketHandler.sendToAllTracking(new MessageLightDrifterFX(player.posX, player.posY, player.posZ), player);
			} else {
				SpectatorHandler.setFake();
			}
		}
		if (info.has(MAGNETISM)) {
			int count = 0;
			count += Magnetize.pull(EntityItem.class, player.world, player.getPosition(), radius_x, radius_y, radius_z);
			if (SpellConfig.spellFeaturesCategory.shouldMagnetismAttractXP) {
				count += Magnetize.pull(EntityXPOrb.class, player.world, player.getPosition(), radius_x, radius_y, radius_z);
			}

			if (!acted) {
				acted = count != 0;
			}
		}
		if (info.has(LUCK)) {
			acted = true;
			player.addPotionEffect(new PotionEffect(MobEffects.LUCK, luck_duration, luck_amplifier, false, false));
		}
		if (info.has(STRENGTH)) {
			acted = true;
			player.addPotionEffect(new PotionEffect(MobEffects.STRENGTH, strength_duration, strength_amplifier, false, false));
		}
		if (info.has(ABSORPTION)) {
			acted = true;
			player.addPotionEffect(new PotionEffect(MobEffects.ABSORPTION, absorption_duration, absorption_amplifier, false, false));
		}
		if (info.has(SECOND_WIND)) {
			int air = player.getAir();
			if (air < 300) {
				acted = true;
				player.setAir(Math.min(300, air + air_amount));
				if (player.world.isRemote) {
					player.playSound(SoundEvents.ENTITY_BOAT_PADDLE_WATER, 1, 1);
				}
			}
		}
		if (info.has(HASTE)) {
			acted = true;
			player.addPotionEffect(new PotionEffect(MobEffects.HASTE, haste_duration, haste_amplifier, false, false));
		}
		if (!acted) {
			player.sendMessage(new TextComponentTranslation("roots.message.augment.no_modifier").setStyle(new Style().setColor(TextFormatting.YELLOW)));
		}
		return acted;
	}

@SubscribeEvent
	public static void onEntityTick(LivingUpdateEvent event) {
		EntityLivingBase entity = event.getEntityLiving();
		if (entity.getActivePotionEffect(ModPotions.time_stop) != null) {
			entity.removePotionEffect(ModPotions.time_stop);
			event.setCanceled(true);
		}
		final NBTTagCompound entityData = event.getEntity().getEntityData();
		if (!event.getEntity().getEntityWorld().isRemote
		    && entity instanceof EntityPlayer
		    && entityData.hasKey(SpellAugment.LIGHT_DRIFTER_TAG))
		{
			entityData.setInteger(SpellAugment.LIGHT_DRIFTER_TAG, entityData.getInteger(SpellAugment.LIGHT_DRIFTER_TAG) - 1);

			// When spell ends:
			if (entityData.getInteger(SpellAugment.LIGHT_DRIFTER_TAG) <= 0) {
				onEndLightDrifter(event, entityData);
			}
		}
		if (entity.getActivePotionEffect(ModPotions.geas) != null) {
			PacketHandler.sendToAllTracking(new MessageGeasFX(entity.posX, entity.posY + entity.getEyeHeight() + 0.75f, entity.posZ), entity);
		}
	}

private static void onEndLightDrifter(LivingUpdateEvent event, NBTTagCompound entityData) {
		final EntityPlayer player = ((EntityPlayer) event.getEntity());
		player.addPotionEffect(new PotionEffect(MobEffects.RESISTANCE, 40, 10, false, false));

		//player.dimension = entityData.getInteger(Constants.LIGHT_DRIFTER_DIMENSION_ID);
		player.capabilities.allowFlying = false;
		player.capabilities.disableDamage = false;
		player.noClip = false;
		player.capabilities.isFlying = false;

		int startingDimension = entityData.getInteger(SpellAugment.LIGHT_DRIFTER_DIMENSION_ID);
		if (player.dimension != startingDimension) // Change dimension only if it's different than where we left
			player.changeDimension(startingDimension, (world, playerIn, yaw) -> playerIn.moveToBlockPosAndAngles(
					new BlockPos(entityData.getDouble(SpellAugment.LIGHT_DRIFTER_X), entityData.getDouble(SpellAugment.LIGHT_DRIFTER_Y), entityData.getDouble(
							SpellAugment.LIGHT_DRIFTER_Z)),
					yaw, playerIn.rotationPitch));
		else
			player.setPositionAndUpdate(player.posX, player.posY, player.posZ); // Otherwise handled by changeDimension

		player.setGameType(GameType.getByID(entityData.getInteger(SpellAugment.LIGHT_DRIFTER_MODE)));
		player.extinguish();
//				PacketHandler.sendToAllTracking(new MessageLightDrifterFX(event.getEntity().posX, event.getEntity().posY + 1.0f, event.getEntity().posZ), event.getEntity());

		//TODO Is this necessary to be able to sync, or do moveToBlockPosAndAngles and setPosition sync it to the client already?
		// I guess there's no harm in leaving it...
		PacketHandler.sendToAllTracking(new MessageLightDrifterSync(event.getEntity().getUniqueID(), player.posX, player.posY, player.posZ, false, entityData.getInteger(
				SpellAugment.LIGHT_DRIFTER_MODE), player.dimension), player);

		entityData.removeTag(SpellAugment.LIGHT_DRIFTER_TAG);
		entityData.removeTag(SpellAugment.LIGHT_DRIFTER_X);
		entityData.removeTag(SpellAugment.LIGHT_DRIFTER_Y);
		entityData.removeTag(SpellAugment.LIGHT_DRIFTER_Z);
		entityData.removeTag(SpellAugment.LIGHT_DRIFTER_MODE);
		entityData.removeTag(SpellAugment.LIGHT_DRIFTER_DIMENSION_ID);

		if (SpellAugment.instance.shouldPlaySound()) {
			player.world.playSound(null, player.getPosition(), ModSounds.Spells.LIGHT_DRIFTER_EFFECT_END, SoundCategory.PLAYERS, SpellAugment.instance.getSoundVolume(), 1);
		}
	}

@Override
    public void deserializeNBT(CompoundTag compound) {
        this.drainSpots.clear();
        var list = compound.getList("drain_spots", 10);
        for (var base : list)
            this.addDrainSpot(new DrainSpot((CompoundTag) base));
        this.addOrRemoveAsActive();
    }

public AuraChunk(LevelChunk chunk) {
        this.chunk = chunk;
        this.type = IAuraType.forLevel(chunk.getLevel());

        for (var supplier : NaturesAuraAPI.DRAIN_SPOT_EFFECTS.values()) {
            var effect = supplier.get();
            if (effect.appliesHere(this.chunk, this, this.type))
                this.effects.add(effect);
        }
    }

@Override
    public int drainAura(BlockPos pos, int amount, boolean aimForZero, boolean simulate) {
        if (amount <= 0)
            return 0;
        var spot = this.getActualDrainSpot(pos, !simulate);
        var curr = spot != null ? spot.intValue() : 0;
        if (curr < 0 && curr - amount > 0) // Underflow protection
            return this.drainAura(pos.above(), amount, aimForZero, simulate);
        if (aimForZero) {
            if (curr > 0 && curr - amount < 0)
                amount = curr;
        }
        if (!simulate) {
            spot.subtract(amount);
            if (spot.intValue() == 0)
                this.drainSpots.remove(pos);
            this.markDirty();
        }
        return amount;
    }

@Override
    public int drainAura(BlockPos pos, int amount) {
        return this.drainAura(pos, amount, false, false);
    }

@Override
    public int storeAura(BlockPos pos, int amount, boolean aimForZero, boolean simulate) {
        if (amount <= 0)
            return 0;
        var spot = this.getActualDrainSpot(pos, !simulate);
        var curr = spot != null ? spot.intValue() : 0;
        if (curr > 0 && curr + amount < 0) // Overflow protection
            return this.storeAura(pos.above(), amount, aimForZero, simulate);
        if (aimForZero) {
            if (curr < 0 && curr + amount > 0) {
                amount = -curr;
            }
        }
        if (!simulate) {
            spot.add(amount);
            if (spot.intValue() == 0)
                this.drainSpots.remove(pos);
            this.markDirty();
        }
        return amount;
    }

@Override
    public int storeAura(BlockPos pos, int amount) {
        return this.storeAura(pos, amount, true, false);
    }

@Override
    public DrainSpot getActualDrainSpot(BlockPos pos, boolean make) {
        var spot = this.drainSpots.get(pos);
        if (spot == null && make) {
            spot = new DrainSpot(pos, 0);
            this.addDrainSpot(spot);
        }
        return spot;
    }

@Override
    public int getDrainSpot(BlockPos pos) {
        var spot = this.getActualDrainSpot(pos, false);
        return spot == null ? 0 : spot.intValue();
    }

private void addDrainSpot(DrainSpot spot) {
        var expX = spot.pos.getX() >> 4;
        var expZ = spot.pos.getZ() >> 4;
        var myPos = this.chunk.getPos();
        if (expX != myPos.x || expZ != myPos.z)
            throw new IllegalArgumentException("Tried to add drain spot " + spot.pos + " to chunk at " + myPos.x + ", " + myPos.z + " when it should've been added to chunk at " + expX + ", " + expZ);

        this.drainSpots.put(spot.pos, spot);
    }

public void setSpots(Collection<DrainSpot> spots) {
        this.drainSpots.clear();
        for (var spot : spots)
            this.addDrainSpot(spot);
        this.addOrRemoveAsActive();
    }

@Override
    public IAuraType getType() {
        return this.type;
    }

@Override
    public void markDirty() {
        this.chunk.setUnsaved(true);
        this.needsSync = true;
        this.auraAndSpotAmountCache.clear();
        this.limitSpotCache.clear();
        this.addOrRemoveAsActive();
    }

public void update() {
        var level = this.chunk.getLevel();

        for (var spot : this.drainSpots.values()) {
            for (var effect : this.effects)
                effect.update(level, this.chunk, this, spot.pos, spot.intValue(), spot);

            // cause this spot to fizzle out if it's over the range limit
            if (spot.intValue() > 0 && spot.originalSpreadPos != null && !spot.originalSpreadPos.closerThan(spot.pos, ModConfig.instance.maxAuraSpreadRange.get()))
                this.drainAura(spot.pos, spot.intValue());
        }

        if (this.needsSync) {
            var pos = this.chunk.getPos();
            PacketHandler.sendToAllLoaded(level,
                    new BlockPos(pos.x * 16, 0, pos.z * 16),
                    this.makePacket());
            this.needsSync = false;
        }
    }

public PacketAuraChunk makePacket() {
        var pos = this.chunk.getPos();
        return new PacketAuraChunk(pos.x, pos.z, this.drainSpots.values());
    }

public void getSpots(BlockPos pos, int radius, BiConsumer<BlockPos, Integer> consumer) {
        for (var entry : this.drainSpots.entrySet()) {
            var drainPos = entry.getKey();
            if (drainPos.distSqr(pos) <= radius * radius) {
                consumer.accept(drainPos, entry.getValue().intValue());
            }
        }
    }

public Pair<Integer, Integer> getAuraAndSpotAmount(BlockPos pos, int radius) {
        var ret = this.auraAndSpotAmountCache.get(pos, radius);
        if (ret == null) {
            var aura = new MutableInt();
            var spots = new MutableInt();
            this.getSpots(pos, radius, (p, i) -> {
                aura.add(i);
                spots.increment();
            });
            ret = Pair.of(aura.intValue(), spots.intValue());
            this.auraAndSpotAmountCache.put(pos, radius, ret);
        }
        return ret;
    }

@SuppressWarnings("unchecked")
    public Pair<BlockPos, Integer>[] getLowestAndHighestSpots(BlockPos pos, int radius) {
        var ret = this.limitSpotCache.get(pos, radius);
        if (ret == null) {
            var lowestSpot = new MutableObject<BlockPos>();
            var highestSpot = new MutableObject<BlockPos>();
            var lowestAmount = new MutableInt(Integer.MAX_VALUE);
            var highestAmount = new MutableInt(Integer.MIN_VALUE);
            this.getSpots(pos, radius, (p, i) -> {
                if (i > highestAmount.intValue()) {
                    highestAmount.setValue(i);
                    highestSpot.setValue(p);
                }
                if (i < lowestAmount.intValue()) {
                    lowestAmount.setValue(i);
                    lowestSpot.setValue(p);
                }
            });
            ret = new Pair[]{
                    Pair.of(lowestSpot.getValue(), lowestAmount.intValue()),
                    Pair.of(highestSpot.getValue(), highestAmount.intValue())};
            this.limitSpotCache.put(pos, radius, ret);
        }
        return ret;
    }

public void getActiveEffectIcons(Player player, Map<ResourceLocation, Tuple<ItemStack, Boolean>> icons) {
        for (var effect : this.effects) {
            var alreadyThere = icons.get(effect.getName());
            if (alreadyThere != null && alreadyThere.getB())
                continue;
            for (var entry : this.drainSpots.entrySet()) {
                var pos = entry.getKey();
                var amount = entry.getValue();
                var state = effect.isActiveHere(player, this.chunk, this, pos, amount.intValue());
                if (state == ActiveType.INACTIVE)
                    continue;
                var stack = effect.getDisplayIcon();
                if (stack.isEmpty())
                    continue;
                icons.put(effect.getName(), new Tuple<>(stack, state == ActiveType.INHIBITED));
            }
        }
    }

@Override
    public CompoundTag serializeNBT() {
        var list = new ListTag();
        for (var spot : this.drainSpots.values())
            list.add(spot.serializeNBT());
        var compound = new CompoundTag();
        compound.put("drain_spots", list);
        return compound;
    }

private void addOrRemoveAsActive() {
        var chunkPos = this.chunk.getPos().toLong();
        var data = (LevelData) ILevelData.getLevelData(this.chunk.getLevel());
        if (!this.drainSpots.isEmpty()) {
            data.auraChunksWithSpots.put(chunkPos, this);
        } else {
            data.auraChunksWithSpots.remove(chunkPos);
        }
    }

public DrainSpot(BlockPos pos, int value) {
            super(value);
            this.pos = pos;
        }

public DrainSpot(CompoundTag tag) {
            this(BlockPos.of(tag.getLong("pos")), tag.getInt("amount"));
            if (tag.contains("original_spread_pos"))
                this.originalSpreadPos = BlockPos.of(tag.getLong("original_spread_pos"));
        }

public CompoundTag serializeNBT() {
            var ret = new CompoundTag();
            ret.putLong("pos", this.pos.asLong());
            ret.putInt("amount", this.intValue());
            if (this.originalSpreadPos != null)
                ret.putLong("original_spread_pos", this.originalSpreadPos.asLong());
            return ret;
        }

