@Override
    public Pair<Integer, Integer> getAuraAndSpotAmountInArea(Level level, BlockPos pos, int radius) {
        var spots = new MutableInt();
        var aura = new MutableInt(IAuraChunk.DEFAULT_AURA);
        Helper.getAuraChunksWithSpotsInArea(level, pos, radius, chunk -> {
            var auraAndSpots = chunk.getAuraAndSpotAmount(pos, radius);
            aura.add(auraAndSpots.getLeft());
            spots.add(auraAndSpots.getRight());
        });
        return Pair.of(aura.intValue(), spots.intValue());
    }

@Override
    public int triangulateAuraInArea(Level level, BlockPos pos, int radius) {
        var result = new MutableFloat(IAuraChunk.DEFAULT_AURA);
        IAuraChunk.getSpotsInArea(level, pos, radius, (blockPos, spot) -> {
            var percentage = 1F - (float) Math.sqrt(pos.distSqr(blockPos)) / radius;
            result.add(spot * percentage);
        });
        return result.intValue();
    }

@Override
    public BlockPos getLowestAuraDrainSpot(Level level, BlockPos pos, int radius, BlockPos defaultSpot) {
        var lowestAmount = new MutableInt(Integer.MAX_VALUE);
        var lowestSpot = new MutableObject<BlockPos>();
        Helper.getAuraChunksWithSpotsInArea(level, pos, radius, c -> {
            var spot = c.getLowestAndHighestSpots(pos, radius)[0];
            if (spot.getRight() < lowestAmount.intValue()) {
                lowestAmount.setValue(spot.getRight());
                lowestSpot.setValue(spot.getLeft());
            }
        });
        var lowest = lowestSpot.getValue();
        if (lowest == null || lowestAmount.intValue() >= 0)
            lowest = defaultSpot;
        return lowest;
    }

@Override
    public BlockPos getHighestAuraDrainSpot(Level level, BlockPos pos, int radius, BlockPos defaultSpot) {
        var highestAmount = new MutableInt(Integer.MIN_VALUE);
        var highestSpot = new MutableObject<BlockPos>();
        Helper.getAuraChunksWithSpotsInArea(level, pos, radius, c -> {
            var spot = c.getLowestAndHighestSpots(pos, radius)[1];
            if (spot.getRight() > highestAmount.intValue()) {
                highestAmount.setValue(spot.getRight());
                highestSpot.setValue(spot.getLeft());
            }
        });
        var highest = highestSpot.getValue();
        if (highest == null || highestAmount.intValue() <= 0)
            highest = defaultSpot;
        return highest;
    }

public static void getAuraChunksWithSpotsInArea(Level level, BlockPos pos, int radius, Consumer<AuraChunk> consumer) {
        var data = (LevelData) ILevelData.getLevelData(level);
        for (var x = pos.getX() - radius >> 4; x <= pos.getX() + radius >> 4; x++) {
            for (var z = pos.getZ() - radius >> 4; z <= pos.getZ() + radius >> 4; z++) {
                var chunk = data.auraChunksWithSpots.get(ChunkPos.asLong(x, z));
                if (chunk != null)
                    consumer.accept(chunk);
            }
        }
    }

public static ChunkAccess getLoadedChunk(LevelAccessor level, int x, int z) {
        // as always, this code is EXTREMELY FRAGILE and editing it before the next major version will probably break it
        if (level.getChunkSource() instanceof ServerChunkCache cache) {
            return cache.isPositionTicking(ChunkPos.asLong(x, z)) ? cache.getChunk(x, z, ChunkStatus.FULL, false) : null;
        } else {
            return level.getChunk(x, z, ChunkStatus.FULL, false);
        }
    }

static ILevelData getLevelData(Level level) {
        return NaturesAuraAPI.instance().getLevelData(level);
    }

static ILevelData getOverworldData(Level level) {
        if (!level.isClientSide)
            return ILevelData.getLevelData(level.getServer().getLevel(Level.OVERWORLD));
        return ILevelData.getLevelData(level);
    }

public LevelData(CompoundTag compound) {
        for (var base : compound.getList("storages", 10)) {
            var storageComp = (CompoundTag) base;
            var storage = this.getEnderStorage(storageComp.getString("name"));
            storage.deserializeNBT(storageComp);
        }
        for (var base : compound.getList("converted_moss", Tag.TAG_LONG))
            this.recentlyConvertedMossStones.add(BlockPos.of(((LongTag) base).getAsLong()));
    }

@Override
    public CompoundTag save(CompoundTag compound) {
        var storages = new ListTag();
        for (var entry : this.enderStorages.entrySet()) {
            var handler = entry.getValue();
            if (Helper.isEmpty(handler))
                continue;
            var storageComp = handler.serializeNBT();
            storageComp.putString("name", entry.getKey());
            storages.add(storageComp);
        }
        compound.put("storages", storages);

        var moss = new ListTag();
        for (var pos : this.recentlyConvertedMossStones)
            moss.add(LongTag.valueOf(pos.asLong()));
        compound.put("converted_moss", moss);

        return compound;
    }

@Override
    public boolean isDirty() {
        return true;
    }

@Override
    public ItemStackHandlerNA getEnderStorage(String name) {
        return this.enderStorages.computeIfAbsent(name, n -> new ItemStackHandlerNA(27));
    }

@Override
    public boolean isEnderStorageLocked(String name) {
        var handler = this.getEnderStorage(name);
        for (var i = 0; i < handler.getSlots(); i++) {
            var stack = handler.getStackInSlot(i);
            if (!stack.isEmpty() && stack.getItem() == ModItems.TOKEN_TERROR)
                return true;
        }
        return false;
    }

public void addMossStone(BlockPos pos) {
        this.recentlyConvertedMossStones.add(pos);
        if (this.recentlyConvertedMossStones.size() > 512)
            this.recentlyConvertedMossStones.remove(0);
    }

@SubscribeEvent
    public void onChunkUnload(ChunkEvent.Unload event) {
        var iChunk = event.getChunk();
        if (iChunk instanceof LevelChunk chunk) {
            var auraChunk = chunk.getData(NaturesAuraAPI.AURA_CHUNK_ATTACHMENT);
            if (auraChunk instanceof AuraChunk) {
                var data = (LevelData) ILevelData.getLevelData(chunk.getLevel());
                data.auraChunksWithSpots.remove(chunk.getPos().toLong());
            }
        }
    }

@SubscribeEvent
    public void onItemUse(PlayerInteractEvent.RightClickBlock event) {
        var player = event.getEntity();
        if (player.level().isClientSide)
            return;
        var held = event.getItemStack();
        if (!held.isEmpty() && BuiltInRegistries.ITEM.getKey(held.getItem()).getPath().contains("chisel")) {
            var state = player.level().getBlockState(event.getPos());
            if (NaturesAuraAPI.BOTANIST_PICKAXE_CONVERSIONS.containsKey(state)) {
                var data = (LevelData) ILevelData.getLevelData(player.level());
                data.addMossStone(event.getPos());
            }
        }
    }

@SubscribeEvent
    @SuppressWarnings("unchecked")
    public void onLevelTick(TickEvent.LevelTickEvent event) {
        if (!event.level.isClientSide && event.phase == TickEvent.Phase.END) {
            if (event.level.getGameTime() % 20 == 0) {
                event.level.getProfiler().push(NaturesAura.MOD_ID + ":onLevelTick");
                try {
                    var manager = ((ServerChunkCache) event.level.getChunkSource()).chunkMap;
                    var chunks = (Iterable<ChunkHolder>) CommonEvents.GET_LOADED_CHUNKS_METHOD.invoke(manager);
                    for (var holder : chunks) {
                        var chunk = holder.getTickingChunk();
                        if (chunk == null)
                            continue;
                        var auraChunk = (AuraChunk) chunk.getData(NaturesAuraAPI.AURA_CHUNK_ATTACHMENT);
                        if (auraChunk != null)
                            auraChunk.update();
                    }
                } catch (IllegalAccessException | InvocationTargetException e) {
                    NaturesAura.LOGGER.fatal(e);
                }
                event.level.getProfiler().pop();
            }
        }
    }

@SubscribeEvent
    public void onPlayerTick(TickEvent.PlayerTickEvent event) {
        if (!event.player.level().isClientSide && event.phase == TickEvent.Phase.END) {
            if (event.player.level().getGameTime() % 10 == 0) {
                var pending = CommonEvents.PENDING_AURA_CHUNKS.get(event.player.getUUID());
                pending.removeIf(p -> this.handleChunkWatchDeferred(event.player, p));
            }

            if (event.player.level().getGameTime() % 200 != 0)
                return;

            var aura = IAuraChunk.triangulateAuraInArea(event.player.level(), event.player.blockPosition(), 25);
            if (aura <= 0)
                Helper.addAdvancement(event.player, new ResourceLocation(NaturesAura.MOD_ID, "negative_imbalance"), "triggered_in_code");
            else if (aura >= 1500000)
                Helper.addAdvancement(event.player, new ResourceLocation(NaturesAura.MOD_ID, "positive_imbalance"), "triggered_in_code");
        }
    }

@SubscribeEvent
    public void onChunkWatch(ChunkWatchEvent.Watch event) {
        CommonEvents.PENDING_AURA_CHUNKS.put(event.getPlayer().getUUID(), event.getPos());
    }

private boolean handleChunkWatchDeferred(Player player, ChunkPos pos) {
        var chunk = Helper.getLoadedChunk(player.level(), pos.x, pos.z);
        if (!(chunk instanceof LevelChunk levelChunk))
            return false;
        var auraChunk = (AuraChunk) levelChunk.getData(NaturesAuraAPI.AURA_CHUNK_ATTACHMENT);
        if (auraChunk == null)
            return false;
        PacketHandler.sendTo(player, auraChunk.makePacket());
        return true;
    }

public NaturesAura(IEventBus eventBus) {
        NaturesAura.instance = this;
        NaturesAura.proxy = FMLEnvironment.dist.isClient() ? new ClientProxy() : new ServerProxy();

        eventBus.addListener(this::setup);

        var builder = new ModConfigSpec.Builder();
        ModConfig.instance = new ModConfig(builder);
        ModLoadingContext.get().registerConfig(net.neoforged.fml.config.ModConfig.Type.COMMON, builder.build());
    }

public void setup(FMLCommonSetupEvent event) {
        this.preInit(event);
        this.init(event);
        this.postInit(event);
    }

private void preInit(FMLCommonSetupEvent event) {
        Compat.setup(event);
        new Multiblocks();

        NeoForge.EVENT_BUS.register(new CommonEvents());

        NaturesAura.proxy.preInit(event);
    }

private void init(FMLCommonSetupEvent event) {
        event.enqueueWork(ModConfig.instance::apply);

        ModRecipes.init();
        DrainSpotEffects.init();

        NaturesAura.proxy.init(event);
    }

