public static ItemStack getEquippedItem(Predicate<ItemStack> predicate, Player player, boolean hotbarOnly) {
        if (Compat.hasCompat("curios")) {
            var inventory = CuriosApi.getCuriosInventory(player);
            if (inventory.isPresent()) {
                var stack = inventory.get().findFirstCurio(predicate).map(SlotResult::stack);
                if (stack.isPresent())
                    return stack.get();
            }
        }
        var invSize = hotbarOnly ? 9 : player.getInventory().getContainerSize();
        for (var i = 0; i < invSize; i++) {
            var slot = player.getInventory().getItem(i);
            if (!slot.isEmpty() && predicate.test(slot))
                return slot;
        }
        return ItemStack.EMPTY;
    }

public static boolean isEmpty(IItemHandler handler) {
        for (var i = 0; i < handler.getSlots(); i++)
            if (!handler.getStackInSlot(i).isEmpty())
                return false;
        return true;
    }

public ItemAuraContainer(ItemStack stack, IAuraType type, int maxAura) {
        this.stack = stack;
        this.type = type;
        this.maxAura = maxAura;
    }

@Override
    public int storeAura(int amountToStore, boolean simulate) {
        var aura = this.getStoredAura();
        var actual = Math.min(amountToStore, this.getMaxAura() - aura);
        if (!simulate) {
            this.setAura(aura + actual);
        }
        return actual;
    }

@Override
    public int drainAura(int amountToDrain, boolean simulate) {
        var aura = this.getStoredAura();
        var actual = Math.min(amountToDrain, aura);
        if (!simulate) {
            this.setAura(aura - actual);
        }
        return actual;
    }

private void setAura(int amount) {
        if (!this.stack.hasTag()) {
            this.stack.setTag(new CompoundTag());
        }
        this.stack.getTag().putInt("aura", amount);
    }

@Override
    public int getStoredAura() {
        if (this.stack.hasTag()) {
            return this.stack.getTag().getInt("aura");
        } else {
            return 0;
        }
    }

