@Override
    public Tag serializeNBT(@Nullable CoverBehavior value,
                            CoverBehaviorTransformer.TransformerContext<CoverBehavior> context) {
        if (value == null) {
            var nullTag = new CompoundTag();
            nullTag.putBoolean("null", true);
            return nullTag;
        }

        var compound = new CompoundTag();
        compound.putString("side", value.attachedSide.getSerializedName());
        compound.putString("coverType", value.coverDefinition.getId().toString());
        CompoundTag serializedCover = value.getSyncDataHolder().serializeNBT(context.lookup());
        compound.put("data", serializedCover);
        return compound;
    }

@Override
    public void writeToPacket(FriendlyByteBuf buf, @Nullable CoverBehavior value,
                              TransformerContext<CoverBehavior> context) {
        buf.writeBoolean(value != null);
        if (value == null) return;
        buf.writeEnum(value.attachedSide);
        buf.writeResourceLocation(value.coverDefinition.getId());
        if (context.isClientFullSyncUpdate()) value.getSyncDataHolder().resyncAllFields();
        value.getSyncDataHolder().writeClientPacket(context.lookup(), buf);
    }

@Override
    public @Nullable CoverBehavior readFromPacket(FriendlyByteBuf buf, TransformerContext<CoverBehavior> context) {
        if (!(context.holder() instanceof ICoverable holder)) {
            GTCEu.LOGGER.error("Sync: Object attempting to sync cover does not implement ICoverable {}", context);
            return null;
        }

        if (!buf.readBoolean()) {
            return null;
        }

        Direction side = buf.readEnum(Direction.class);
        ResourceLocation coverId = buf.readResourceLocation();
        CoverBehavior cover = context.currentValue();

        if (cover == null || !cover.coverDefinition.getId().equals(coverId)) {
            var coverReg = GTRegistries.COVERS.get(coverId);
            if (coverReg == null) {
                GTCEu.LOGGER.error("Error during packet read: unknown cover type {}", coverId);
                return null;
            }
            holder.setCoverAtSide(coverReg.createCoverBehavior(holder, side), side);
        }

        CoverBehavior newCover = holder.getCoverAtSide(side);
        if (newCover == null) return null;

        newCover.getSyncDataHolder().readClientPacket(context.lookup(), buf);

        return newCover;
    }

@Inject(method = "readCustomDataFromNbt", at = @At("RETURN"))
    private void readNbt(NbtCompound tag, CallbackInfo info) {
        unlocked.clear();

        // This tag might exist - it contains old save data for pre-variant Identities.
        // Each entry will be a string with an entity registry ID value.
        NbtList unlockedIdList = tag.getList("UnlockedMorphs", NbtElement.STRING_TYPE);
        unlockedIdList.forEach(entityRegistryID -> {
            Identifier id = new Identifier(entityRegistryID.asString());
            if(Registries.ENTITY_TYPE.containsId(id)) {
                EntityType<?> type = Registries.ENTITY_TYPE.get(id);

                // The variant added from the UnlockedMorphs list will default to the fallback value if needed (eg. Sheep => White)
                // This value will be re-serialize in UnlockedIdentities list, so this is 100% for old save conversions
                unlocked.add(new IdentityType(type));
            } else {
                // TODO: log reading error here
            }
        });

        // This is the new tag for saving Identity unlock information.
        // It includes metadata for variants.
        NbtList unlockedIdentityList = tag.getList("UnlockedIdentities", NbtElement.COMPOUND_TYPE);
        unlockedIdentityList.forEach(compound -> {
            IdentityType<?> type = IdentityType.from((NbtCompound) compound);
            if(type != null) {
                unlocked.add(type);
            } else {
                // TODO: log reading error here
            }
        });

        // Favorites - OLD TAG containing String IDs
        favorites.clear();
        NbtList favoriteIdList = tag.getList("FavoriteIdentities", NbtElement.STRING_TYPE);
        favoriteIdList.forEach(registryID -> {
            Identifier id = new Identifier(registryID.asString());
            if(Registries.ENTITY_TYPE.containsId(id)) {
                EntityType<?> type = Registries.ENTITY_TYPE.get(id);
                favorites.add(new IdentityType(type));
            }
        });

        // Favorites - NEW TAG for updated variant compound data
        NbtList favoriteTypeList = tag.getList("FavoriteIdentitiesV2", NbtElement.STRING_TYPE);
        favoriteTypeList.forEach(compound -> {
            IdentityType<?> type = IdentityType.from((NbtCompound) compound);
            if(type != null) {
                favorites.add(type);
            }
        });

        // Abilities
        abilityCooldown = tag.getInt(ABILITY_COOLDOWN_KEY);

        // Hostility
        remainingTime = tag.getInt("RemainingHostilityTime");

        // Current Identity
        readCurrentIdentity(tag.getCompound("CurrentIdentity"));
    }

