            false,
            RemnantStateChangeCallback.Cause.MERGE
        )) {
            // if we got a FakeServerPlayerEntity here, we must have a ServerPlayerEntity too
            PlayerSplitter.doMerge((PlayerShellEntity) shell, (ServerPlayerEntity) this.player);
            return true;
        }
        return false;
    }

