                            final Integer page = parseInteger(clickEvent, "value");
                            if (page == null) {
                                root.remove("click_event");
                                break;
                            }
                            clickEvent.remove("value");
                            clickEvent.setInt("page", Math.max(1, page.intValue()));
                        }

                        // default: do nothing
                    }
                }

                return null;
            }

