@Nullable
    public static Entity getEntityByUuid(@Nullable UUID uuid, @Nullable MinecraftServer server) {

        if (uuid == null || server == null) {
            return null;
        }

        Entity entity;
        for (ServerWorld serverWorld : server.getWorlds()) {

            if ((entity = serverWorld.getEntity(uuid)) != null) {
                return entity;
            }

        }

        return null;

    }

