@Override
    public void load(final CompoundTag compound)
    {
        super.load(compound);
        if (compound.contains(TAG_SIZE))
        {
            size = compound.getInt(TAG_SIZE);
            inventory = createInventory(DEFAULT_SIZE + size * SLOT_PER_LINE);
        }

        final ListTag inventoryTagList = compound.getList(TAG_INVENTORY, TAG_COMPOUND);
        for (int i = 0; i < inventoryTagList.size(); i++)
        {
            final CompoundTag inventoryCompound = inventoryTagList.getCompound(i);
            if (!inventoryCompound.contains(TAG_EMPTY))
            {
                final ItemStack stack = ItemStack.of(inventoryCompound);
                inventory.setStackInSlot(i, stack);
            }
        }

        updateContent();

        this.inWarehouse = compound.getBoolean(TAG_IN_WAREHOUSE);
        if (compound.contains(TAG_POS))
        {
            this.buildingPos = BlockPosUtil.read(compound, TAG_POS);
        }
        version = compound.getByte(TAG_VERSION);

        invalidateCap();

        if (level != null && level.isClientSide)
        {
            refreshTextureCache();
        }
    }

@Override
    public void saveAdditional(final CompoundTag compound)
    {
        super.saveAdditional(compound);
        compound.putInt(TAG_SIZE, size);
        @NotNull final ListTag inventoryTagList = new ListTag();
        for (int slot = 0; slot < inventory.getSlots(); slot++)
        {
            @NotNull final CompoundTag inventoryCompound = new CompoundTag();
            final ItemStack stack = inventory.getStackInSlot(slot);
            if (stack.isEmpty())
            {
                inventoryCompound.putBoolean(TAG_EMPTY, true);
            }
            else
            {
                stack.save(inventoryCompound);
            }
            inventoryTagList.add(inventoryCompound);
        }
        compound.put(TAG_INVENTORY, inventoryTagList);
        compound.putBoolean(TAG_IN_WAREHOUSE, inWarehouse);
        BlockPosUtil.write(compound, TAG_POS, buildingPos);
        compound.putByte(TAG_VERSION, version);
    }

private IAIState tryResurrect()
    {
        @Nullable final BuildingGraveyard buildingGraveyard = building;

        if (checkForToolOrWeapon(ModEquipmentTypes.shovel.get())
              || buildingGraveyard.getGraveToWorkOn() == null)
        {
            return IDLE;
        }

        unequip();

        @Nullable final BlockPos gravePos = buildingGraveyard.getGraveToWorkOn();

        if (gravePos == null)
        {
            return IDLE;
        }

        // Still moving to the block
        if (walkWithProxy(gravePos, 3))
        {
            return getState();
        }

        final BlockEntity entity = world.getBlockEntity(gravePos);
        if (entity instanceof TileEntityGrave)
        {
            if (effortCounter < EFFORT_RESURRECT)
            {
                worker.getLookControl().setLookAt(gravePos.getX(), gravePos.getY(), gravePos.getZ(), FACING_DELTA_YAW, worker.getMaxHeadXRot());
                worker.swing(InteractionHand.MAIN_HAND);
                Network.getNetwork()
                  .sendToTrackingEntity(new VanillaParticleMessage(gravePos.getX() + 0.5f, gravePos.getY() + 0.05f, gravePos.getZ() + 0.5f, ParticleTypes.ENCHANT), worker);
                effortCounter += getSecondarySkillLevel();
                return getState();
            }
            effortCounter = 0;

            shouldDumpInventory = true;
            final double chance = getResurrectChance(buildingGraveyard);

            if (getTotemResurrectChance() > 0 && random.nextDouble() <= TOTEM_BREAK_CHANCE)
            {
                worker.getInventoryCitizen().extractItem(InventoryUtils.findFirstSlotInItemHandlerWith(worker.getInventoryCitizen(), Items.TOTEM_OF_UNDYING), 1, false);
                worker.playSound(SoundEvents.TOTEM_USE, 1.0f, 1.0f);
            }

            if (chance >= random.nextDouble())
            {
                Network.getNetwork()
                  .sendToTrackingEntity(new VanillaParticleMessage(gravePos.getX() + 0.5f, gravePos.getY() + 0.05f, gravePos.getZ() + 0.5f, ParticleTypes.HEART), worker);

                final GraveData graveData = (GraveData) ((TileEntityGrave) entity).getGraveData();
                final ICitizenData citizenData = buildingGraveyard.getColony()
                                                   .getCitizenManager()
                                                   .resurrectCivilianData(graveData.getCitizenDataNBT(), true, world, gravePos);
                MessageUtils.format(MESSAGE_INFO_CITIZEN_UNDERTAKER_RESURRECTED_SUCCESS, citizenData.getName()).sendTo(buildingGraveyard.getColony()).forManagers();
                StatsUtil.trackStat(building, CITIZENS_RESURRECTED, 1);
                building.getColony().getStatisticsManager().increment(CITIZENS_RESURRECTED, worker.getCitizenColonyHandler().getColonyOrRegister().getDay());
                worker.getCitizenColonyHandler().getColonyOrRegister().getCitizenManager().updateCitizenMourn(citizenData, false);
                AdvancementUtils.TriggerAdvancementPlayersForColony(worker.getCitizenColonyHandler().getColonyOrRegister(),
                  playerMP -> AdvancementTriggers.CITIZEN_RESURRECT.trigger(playerMP));
                buildingGraveyard.getFirstModuleOccurance(GraveyardManagementModule.class).setLastGraveData(null);
                world.setBlockAndUpdate(gravePos, Blocks.AIR.defaultBlockState());
                return INVENTORY_FULL;
            }
        }

        return DIG_GRAVE;
    }

@Override
    public void readFromNBT(@NotNull final CompoundTag compound)
    {
        stats.clear();
        if (compound.contains(TAG_STAT_MANAGER))
        {
            final ListTag statsNbts = compound.getList(TAG_STAT_MANAGER, Tag.TAG_COMPOUND);
            for (int i = 0; i < statsNbts.size(); i++)
            {
                final CompoundTag statCompound = statsNbts.getCompound(i);
                final String id = statCompound.getString(TAG_ID);
                final ListTag timeStampNbts = statCompound.getList(TAG_STAT, Tag.TAG_COMPOUND);
                final Int2IntLinkedOpenHashMap timeStamps = new Int2IntLinkedOpenHashMap();
                for (int j = 0; j < timeStampNbts.size(); j++)
                {
                    final CompoundTag compoundTag = timeStampNbts.getCompound(j);
                    final int day = compoundTag.getInt(TAG_TIME);
                    final int qty = compoundTag.getInt(TAG_QUANTITY);

                    timeStamps.put(day, qty);
                }

                stats.put(id, timeStamps);
            }
        }
    }

@Override
    public void increment(final @NotNull String id, final int day)
    {
        incrementBy(id, 1, day);
    }

@Override
    public void incrementBy(final @NotNull String id, int qty, final int day)
    {
        final Int2IntLinkedOpenHashMap innerMap = stats.computeIfAbsent(id, k -> new Int2IntLinkedOpenHashMap());
        innerMap.addTo(day, qty);
        dirtyStats.add(id);
    }

@Override
    public int getStatTotal(final @NotNull String id)
    {
        final Int2IntLinkedOpenHashMap stats = this.stats.getOrDefault(id, new Int2IntLinkedOpenHashMap());
        int totalCount = 0;
        for (final int count : stats.values())
        {
            totalCount += count;
        }
        return totalCount;
    }

@Override
    public int getStatsInPeriod(final @NotNull String id, final int startDay, final int endDay)
    {
        final Int2IntLinkedOpenHashMap stats = this.stats.getOrDefault(id, new Int2IntLinkedOpenHashMap());
        int count = 0;
        for (int day = startDay; day <= endDay; day++)
        {
            count += stats.get(day);
        }
        return count;
    }

@Override
    public @NotNull Set<String> getStatTypes()
    {
        return stats.keySet();
    }

@Override
    public @NotNull Set<Map.Entry<String, Int2IntLinkedOpenHashMap>>  getStatEntries()
    {
        return stats.entrySet();
    }

@Override
    public void clear()
    {
        dirtyStats.addAll(stats.keySet());
        stats.clear();
    }

@Override
    public void serialize(@NotNull final FriendlyByteBuf buf, final boolean fullSync)
    {
        buf.writeBoolean(fullSync);
        buf.writeVarInt(fullSync ? stats.size() : dirtyStats.size());

        if (fullSync)
        {
            for (final Map.Entry<String, Int2IntLinkedOpenHashMap> dataEntry : stats.entrySet())
            {
                buf.writeUtf(dataEntry.getKey());
                buf.writeVarInt(dataEntry.getValue().size());

                for (final Int2IntMap.Entry valueEntry : dataEntry.getValue().int2IntEntrySet())
                {
                    buf.writeVarInt(valueEntry.getIntKey());
                    buf.writeVarInt(valueEntry.getIntValue());
                }
            }
        }
        else
        {
            for (final String id : dirtyStats)
            {
                final Int2IntLinkedOpenHashMap dataEntry = stats.get(id);

                buf.writeUtf(id);
                if (dataEntry == null)
                {
                    buf.writeVarInt(0);
                    continue;
                }

                buf.writeVarInt(1);
                buf.writeVarInt(dataEntry.lastIntKey());
                buf.writeVarInt(dataEntry.get(dataEntry.lastIntKey()));
            }
        }

        if (!dirtyStats.isEmpty())
        {
            dirtyStats = new HashSet<>();
        }
    }

@Override
    public void deserialize(@NotNull final FriendlyByteBuf buf)
    {
        final boolean fullSync = buf.readBoolean();
        if (fullSync)
        {
            stats.clear();
        }

        final int statSize = buf.readVarInt();
        for (int i = 0; i < statSize; i++)
        {
            final String id = buf.readUtf();
            final int statEntrySize = buf.readVarInt();

            if (!fullSync && statEntrySize == 0)
            {
                stats.remove(id);
                continue;
            }

            final Int2IntLinkedOpenHashMap statValues = (fullSync || !stats.containsKey(id)) ? new Int2IntLinkedOpenHashMap(statEntrySize) : stats.get(id);
            for (int j = 0; j < statEntrySize; j++)
            {
                statValues.put(buf.readVarInt(), buf.readVarInt());
            }

            stats.put(id, statValues);
        }
    }

@Override
    public void writeToNBT(@NotNull final CompoundTag compound)
    {
        final ListTag statManagerNBT = new ListTag();
        for (final Map.Entry<String, Int2IntLinkedOpenHashMap> stat : stats.entrySet())
        {
            final CompoundTag statCompound = new CompoundTag();
            statCompound.putString(TAG_ID, stat.getKey());

            final ListTag statNBT = new ListTag();
            for (final Map.Entry<Integer, Integer> dailyStats : stat.getValue().entrySet())
            {
                final CompoundTag timeStampTag = new CompoundTag();

                timeStampTag.putInt(TAG_TIME, dailyStats.getKey());
                timeStampTag.putInt(TAG_QUANTITY, dailyStats.getValue());

                statNBT.add(timeStampTag);
            }

            statCompound.put(TAG_STAT, statNBT);
            statManagerNBT.add(statCompound);
        }

        compound.put(TAG_STAT_MANAGER, statManagerNBT);
    }

