@Override
	public boolean removeGem(CircleGem gem) {
		Iterator<CircleGem> gemIT = this.gems.iterator();
		while(gemIT.hasNext()) {
			CircleGem currentGem = gemIT.next();
			if(currentGem.getGemType() == gem.getGemType() && currentGem.getCombatType() == gem.getCombatType()) {
				gemIT.remove();
				this.markDirty();
				return true;
			}
		}
		return false;
	}

