	}

public CombatType getCombatType() {
		return this.combatType;
	}

public boolean matchCombatType(CombatType type) {
		return this.combatType == CombatType.BOTH || type == this.combatType;
	}

public NBTTagCompound writeToNBT(NBTTagCompound nbt) {
		nbt.setString("gem", this.gemType.name);
		nbt.setInteger("type", this.combatType.ordinal());
		return nbt;
	}

public static CircleGem readFromNBT(NBTTagCompound nbt) {
		CircleGemType gem = CircleGemType.fromName(nbt.getString("gem"));
		int typeOrdinal = nbt.getInteger("type");
		if(CombatType.values().length > typeOrdinal) {
			return new CircleGem(gem, CombatType.values()[typeOrdinal]);
		}
		return null;
	}

public static CircleGemType fromName(String name) {
		for(CircleGemType gem : TYPES) {
			if(gem.name.equals(name)) {
				return gem;
			}
		}
		return NONE;
	}

public static CircleGemType fromID(int id) {
		for(CircleGemType gem : TYPES) {
			if(gem.id == id) {
				return gem;
			}
		}
		return NONE;
	}

public int getRelation(CircleGemType gem) {
		switch(this) {
		case CRIMSON:
			switch(gem){
			case GREEN:
				return 1;
			case AQUA:
				return -1;
			default:
				return 0;
			}
		case GREEN:
			switch(gem){
			case AQUA:
				return 1;
			case CRIMSON:
				return -1;
			default:
				return 0;
			}
		case AQUA:
			switch(gem){
			case CRIMSON:
				return 1;
			case GREEN:
				return -1;
			default:
				return 0;
			}
		default:
			return 0;
		}
	}

