@Override
	public ActionResult<ItemStack> onItemRightClick(World world, EntityPlayer player, EnumHand hand) {
		ItemStack stack = player.getHeldItem(hand);
		if(!world.isRemote) {
			if(player.isSneaking() && player.capabilities.isCreativeMode) {
				removeAmuletSlot(player);
			} else {
				addAmuletSlot(player, stack, player);
			}
		}
		return new ActionResult<>(EnumActionResult.SUCCESS, stack);
	}

@Override
	public boolean itemInteractionForEntity(ItemStack stack, EntityPlayer player, EntityLivingBase target, EnumHand hand) {
		if(!player.world.isRemote) {
			if(ItemAmulet.canPlayerAddAmulet(player, target) || player.capabilities.isCreativeMode) {
				if(player.isSneaking() && player.capabilities.isCreativeMode) {
					removeAmuletSlot(target);
				} else {
					if(addAmuletSlot(player, stack, target)) {
						player.swingArm(hand);
					}
				}
			}
		}
		return true;
	}

public static boolean addAmuletSlot(EntityPlayer player, ItemStack stack, EntityLivingBase entity) {
		IEquipmentCapability cap = entity.getCapability(CapabilityRegistry.CAPABILITY_EQUIPMENT, null);
		if(cap != null) {

			if(cap.getAmuletSlots() < 3 || player.capabilities.isCreativeMode) {
				cap.setAmuletSlots(cap.getAmuletSlots() + 1);

				if(!player.capabilities.isCreativeMode) {
					if(entity instanceof EntityPlayer) {
						stack.damageItem(5, player);
					} else {
						stack.damageItem(2, player);
					}
				}

				player.sendStatusMessage(new TextComponentTranslation("chat.amulet.slot.added"), true);

				return true;
			} else {
				player.sendStatusMessage(new TextComponentTranslation("chat.amulet.slot.full"), true);
			}
		}
		return false;
	}

public static void removeAmuletSlot(EntityLivingBase entity) {
		IEquipmentCapability cap = entity.getCapability(CapabilityRegistry.CAPABILITY_EQUIPMENT, null);
		if(cap != null) {
			if(cap.getAmuletSlots() > 1) {
				cap.setAmuletSlots(cap.getAmuletSlots() - 1);
			}
		}
	}

@SubscribeEvent
	public static void onEntityAttacked(LivingHurtEvent event) {
		EntityLivingBase attackedEntity = event.getEntityLiving();
		DamageSource source = event.getSource();
		float damage = event.getAmount();

		Entity entity = source.getTrueSource();
		if(attackedEntity instanceof IEntityBL && entity instanceof EntityLivingBase && ((EntityLivingBase) entity).getActiveHand() != null) {
			//BL mobs overworld item resistance
			EntityLivingBase attacker = (EntityLivingBase) entity;
			ItemStack heldItem = attacker.getHeldItem(attacker.getActiveHand());

			if (heldItem.isEmpty() || OverworldItemHandler.isToolWeakened(heldItem)) {
				//Cap damage of overly OP weapons
				damage = Math.min(damage, 40.0F);
			}

			if (!heldItem.isEmpty()) {
				if (OverworldItemHandler.isToolWeakened(heldItem)) {
					damage = damage * DAMAGE_REDUCTION;

					if(!attackedEntity.world.isRemote) {
						Vec3d center = attackedEntity.getPositionVector().add(0, attackedEntity.height / 2.0F, 0);

						Vec3d hitOffset = null;

						Entity immediateAttacker = source.getImmediateSource();

						if(immediateAttacker == null || attacker == immediateAttacker) {
							RayTraceResult result = attackedEntity.getEntityBoundingBox().calculateIntercept(attacker.getPositionEyes(1), attacker.getPositionEyes(1).add(attacker.getLookVec().scale(10)));
							if(result != null) {
								hitOffset = result.hitVec.subtract(center);
							}
						}
						if(immediateAttacker != null && hitOffset == null) {
							hitOffset = immediateAttacker.getPositionVector().add(0, immediateAttacker.height / 2.0F, 0).subtract(center);
						}
						if(hitOffset != null) {
							Vec3d offsetDirXZ = new Vec3d(hitOffset.x, 0, hitOffset.z).normalize();
							Vec3d offset = offsetDirXZ.scale(attackedEntity.width).add(0, hitOffset.y + attackedEntity.height / 2.0F, 0);

							attackedEntity.world.playSound(null, attackedEntity.posX, attackedEntity.posY + 0.5D, attackedEntity.posZ, SoundRegistry.DAMAGE_REDUCTION, SoundCategory.PLAYERS, 0.7F, 0.75F + attackedEntity.world.rand.nextFloat() * 0.3F);

							TheBetweenlands.networkWrapper.sendToAllAround(new MessageDamageReductionParticle(attackedEntity, offset, offsetDirXZ.scale(attackedEntity.width + 0.2F).normalize()), new TargetPoint(attackedEntity.dimension, attackedEntity.posX, attackedEntity.posY, attackedEntity.posZ, 32.0D));
						}
					}
				}
			}
		}

		damage = CircleGemHelper.handleAttack(source, attackedEntity, damage);

		if(entity instanceof EntityLivingBase) {
			IEquipmentCapability cap = entity.getCapability(CapabilityRegistry.CAPABILITY_EQUIPMENT, null);
			if(cap != null) {
				IInventory inv = cap.getInventory(EnumEquipmentInventory.RING);
				int rings = 0;

				for(int i = 0; i < inv.getSizeInventory(); i++) {
					ItemStack stack = inv.getStackInSlot(i);
					if(!stack.isEmpty() && stack.getItem() == ItemRegistry.RING_OF_POWER && stack.getItemDamage() < stack.getMaxDamage()) {
						rings++;
					}
				}

				if(rings > 0) {
					TheBetweenlands.networkWrapper.sendToAllAround(new MessagePowerRingParticles(attackedEntity), new TargetPoint(attackedEntity.dimension, attackedEntity.posX, attackedEntity.posY, attackedEntity.posZ, 32.0D));
				}

				damage *= 1.0F + 0.5F * rings;
			}
		}

		int thornsCount = 0;

		for (ItemStack armor : attackedEntity.getArmorInventoryList()) {
			if (armor.getItem() instanceof ItemAmphibiousArmor) {
				if (((ItemAmphibiousArmor) armor.getItem()).getUpgradeCount(armor, AmphibiousArmorUpgrades.THORNS) >= 1) {
					thornsCount++;
				}
			}
		}

		if(entity != null && thornsCount > 0 && EnchantmentThorns.shouldHit(thornsCount, entity.world.rand)) {
			// Perhaps also damage armor like normal thorns would do? though thats usually really annoying
			entity.attackEntityFrom(DamageSource.causeThornsDamage(attackedEntity), thornsCount + entity.world.rand.nextInt(4));
		}

		event.setAmount(damage);
	}

public static <T, F extends EntityCapability<F, T, E>, E extends Entity> void registerEntityCapability(EntityCapability<F, T, E> entityCapability) {
		//Make sure the entity capability is the implementation of the capability
		Preconditions.checkState(entityCapability.getCapabilityClass().isAssignableFrom(entityCapability.getClass()), "Entity capability %s must implement %s", entityCapability.getClass().getName(), entityCapability.getCapabilityClass().getName());
		REGISTERED_CAPABILITIES.add(entityCapability);
	}

public static void registerCapabilities() {
		Preconditions.checkState(Loader.instance().isInState(LoaderState.PREINITIALIZATION));
		for(EntityCapability<?, ?, ?> capability : REGISTERED_CAPABILITIES) {
			registerCapability(capability);
		}
	}

private static <T, E extends Entity> void registerCapability(EntityCapability<?, T, E> capability) {
		CapabilityManager.INSTANCE.register(capability.getCapabilityClass(), new IStorage<T>() {
			@Override
			public final NBTBase writeNBT(Capability<T> capability, T instance, EnumFacing side) {
				if(instance instanceof ISerializableCapability) {
					NBTTagCompound nbt = new NBTTagCompound();
					((ISerializableCapability)instance).writeToNBT(nbt);
					return nbt;
				}
				return new NBTTagCompound(); //This is broken, the doc says returning null if not required, but causes a NPE
			}

			@Override
			public final void readNBT(Capability<T> capability, T instance, EnumFacing side, NBTBase nbt) {
				if(instance instanceof ISerializableCapability && nbt instanceof NBTTagCompound) {
					((ISerializableCapability)instance).readFromNBT((NBTTagCompound)nbt);
				}
			}
		}, new Callable<T>() {
			@SuppressWarnings("unchecked")
			@Override
			public final T call() throws Exception {
				return (T) capability.getDefaultCapabilityImplementation();
			}
		});
		ID_CAPABILITY_MAP.put(capability.getID(), capability);
	}

@SubscribeEvent
	public static void onAttachCapabilities(AttachCapabilitiesEvent<Entity> event) {
		Entity entity = event.getObject();
		for(EntityCapability<?, ?, ?> entityCapability : REGISTERED_CAPABILITIES) {
			if(entityCapability.isApplicable(entity)) {
				final Capability<?> capabilityInstance = entityCapability.getCapability();

				event.addCapability(entityCapability.getID(), new ICapabilitySerializable<NBTTagCompound>() {
					private Object entityCapability = this.getNewInstance();

					private EntityCapability<?, ?, ?> getNewInstance() {
						EntityCapability<?, ?, ?> entityCapability = (EntityCapability<?, ?, ?>)capabilityInstance.getDefaultInstance();
						entityCapability.setEntity(entity);
						entityCapability.init();
						return entityCapability;
					}

					@Override
					public boolean hasCapability(Capability<?> capability, EnumFacing facing) {
						return capability == capabilityInstance;
					}

					@SuppressWarnings("unchecked")
					@Override
					public <T> T getCapability(Capability<T> capability, EnumFacing facing) {
						return capability == capabilityInstance ? (T)this.entityCapability : null;
					}

					@Override
					public NBTTagCompound serializeNBT() {
						return this.serialize(capabilityInstance, this.entityCapability);
					}

					@SuppressWarnings("unchecked")
					private <T> NBTTagCompound serialize(Capability<T> capability, Object instance) {
						return (NBTTagCompound) capability.getStorage().writeNBT(capability, (T)instance, null);
					}

					@Override
					public void deserializeNBT(NBTTagCompound nbt) {
						this.deserialize(capabilityInstance, this.entityCapability, nbt);
					}

					@SuppressWarnings("unchecked")
					private <T> void deserialize(Capability<T> capability, Object instance, NBTTagCompound nbt) {
						capability.getStorage().readNBT(capability, (T)instance, null, nbt);
					}
				});
			}
		}
	}

@SubscribeEvent
	public static void onPlayerClone(PlayerEvent.Clone event) {
		//Clone persistent capability properties
		EntityPlayer oldPlayer = event.getOriginal();
		EntityPlayer newPlayer = event.getEntityPlayer();
		List<EntityCapability<?, ?, EntityPlayer>> capabilities = getEntityCapabilities(oldPlayer);

		for(EntityCapability<?, ?, EntityPlayer> capability : capabilities) {
			if(capability.isPersistent(oldPlayer, newPlayer, event.isWasDeath()) && capability instanceof ISerializableCapability) {
				EntityCapability<?, ?, EntityPlayer> newCapability = capability.getEntityCapability(newPlayer);

				if(newCapability != null && newCapability instanceof ISerializableCapability) {
					capability.clonePersistentData(oldPlayer, newPlayer, event.isWasDeath(), (ISerializableCapability) newCapability);
				}
			}
		}
	}

@SuppressWarnings("unchecked")
	private static <E extends Entity> List<EntityCapability<?, ?, E>> getEntityCapabilities(E entity) {
		List<EntityCapability<?, ?, E>> capabilities = new ArrayList<EntityCapability<?, ?, E>>();

		for(EntityCapability<?, ?, ?> capability : REGISTERED_CAPABILITIES) {
			if(entity.hasCapability(capability.getCapability(), null)) {
				capabilities.add((EntityCapability<?, ?, E>) entity.getCapability(capability.getCapability(), null));
			}
		}

		return capabilities;
	}

@SuppressWarnings("unchecked")
	void setEntity(Entity entity) {
		this.entity = (E) entity;
	}

@SuppressWarnings("unchecked")
	public final EntityCapability<?, ?, E> getEntityCapability(E entity) {
		if(entity.hasCapability(this.getCapability(), null))
			return (EntityCapability<?, ?, E>) entity.getCapability(this.getCapability(), null);
		return null;
	}

public boolean isPersistent(EntityPlayer oldPlayer, EntityPlayer newPlayer, boolean wasDead) {
		return !wasDead;
	}

public void clonePersistentData(EntityPlayer oldPlayer, EntityPlayer newPlayer, boolean wasDead, ISerializableCapability newCapability) {
		if(this instanceof ISerializableCapability) {
			NBTTagCompound nbt = new NBTTagCompound();
			((ISerializableCapability) this).writeToNBT(nbt);
			newCapability.readFromNBT(nbt);
		}
	}

