public final void setMaximumEMC(@Range(from = 1, to = Long.MAX_VALUE) long max) {
		maximumEMC = max;
		if (getStoredEmc() > getMaximumEmc()) {
			currentEMC = getMaximumEmc();
			storedEmcChanged();
		}
	}

@Override
	@Range(from = 0, to = Long.MAX_VALUE)
	public long getStoredEmc() {
		return currentEMC;
	}

@Override
	@Range(from = 1, to = Long.MAX_VALUE)
	public long getMaximumEmc() {
		return maximumEMC;
	}

@Range(from = 0, to = Long.MAX_VALUE)
	protected long getEmcInsertLimit() {
		return getNeededEmc();
	}

@Range(from = 0, to = Long.MAX_VALUE)
	protected long getEmcExtractLimit() {
		return getStoredEmc();
	}

protected boolean canAcceptEmc() {
		return true;
	}

protected boolean canProvideEmc() {
		return true;
	}

@Override
	public long extractEmc(long toExtract, EmcAction action) {
		if (toExtract < 0) {
			return insertEmc(-toExtract, action);
		}
		if (canProvideEmc()) {
			return forceExtractEmc(Math.min(getEmcExtractLimit(), toExtract), action);
		}
		return 0;
	}

@Override
	public long insertEmc(long toAccept, EmcAction action) {
		if (toAccept < 0) {
			return extractEmc(-toAccept, action);
		}
		if (canAcceptEmc()) {
			return forceInsertEmc(Math.min(getEmcInsertLimit(), toAccept), action);
		}
		return 0;
	}

protected long forceExtractEmc(long toExtract, EmcAction action) {
		if (toExtract < 0) {
			return forceInsertEmc(-toExtract, action);
		}
		long toRemove = Math.min(getStoredEmc(), toExtract);
		if (action.execute()) {
			currentEMC -= toRemove;
			storedEmcChanged();
		}
		return toRemove;
	}

protected long forceInsertEmc(long toAccept, EmcAction action) {
		if (toAccept < 0) {
			return forceExtractEmc(-toAccept, action);
		}
		long toAdd = Math.min(getNeededEmc(), toAccept);
		if (action.execute()) {
			currentEMC += toAdd;
			storedEmcChanged();
		}
		return toAdd;
	}

protected void storedEmcChanged() {
		setChanged();
	}

@Override
	protected void saveAdditional(@NotNull CompoundTag tag, @NotNull HolderLookup.Provider registries) {
		super.saveAdditional(tag, registries);
		if (getStoredEmc() > getMaximumEmc()) {
			currentEMC = getMaximumEmc();
		}
		tag.putLong("emc", getStoredEmc());
	}

@Override
	public void loadAdditional(@NotNull CompoundTag tag, @NotNull HolderLookup.Provider registries) {
		super.loadAdditional(tag, registries);
		currentEMC = Math.min(tag.getLong("emc"), getMaximumEmc());
	}

private boolean doBlockPlace(Player player, Level level, BlockState oldState, BlockPos placePos, BlockState newState, ItemStack eye, long oldEMC, long newEMC,
			NonNullList<ItemStack> drops, BlockPlaceContext context) {
		if (oldState.hasBlockEntity()) {
			return false;
		} else if (!newState.getValues().isEmpty()) {
			//If the block has multiple states, make sure we update the state based on where we are placing it
			BlockPlaceContext adjustedContext = BlockPlaceContext.at(context, placePos, context.getClickedFace());
			//Ensure that the context returns the actual spot and knows we are replacing the existing state
			adjustedContext.replaceClicked = true;
			newState = newState.getBlock().getStateForPlacement(adjustedContext);
			if (newState == null) {
				return false;
			}
		}
		return doBlockPlace(player, level, oldState, placePos, newState, eye, oldEMC, newEMC, drops);
	}

