		if(nbt != null && nbt.hasKey(NBT_SYNC_COUNT_KEY, Constants.NBT.TAG_BYTE)) {
			return 1 - nbt.getByte(NBT_SYNC_COUNT_KEY) / (float)this.getCapacity();
		}
		return 1;
