		catchTimerMax = nbt.getInteger("catchTimerMax");

		if(nbt.hasKey("tokenBucket", Constants.NBT.TAG_COMPOUND)) {
			tokenBucket = new TokenBucket(nbt.getCompoundTag("tokenBucket"));
		}
	}

