public ReproductionManager(final Colony colony)
    {
        this.colony = colony;
        childCreationTimer = random.nextInt(CHILD_SPAWN_INTERVAL) + MIN_TIME_BEFORE_SPAWNTRY;
    }

@Override
    public void onColonyTick(@NotNull final IColony colony)
    {
        if ( (childCreationTimer -= MAX_TICKRATE) <= 0)
        {
            childCreationTimer = (MIN_TIME_BEFORE_SPAWNTRY + random.nextInt(CHILD_SPAWN_INTERVAL)) * (colony.getCitizenManager().getCurrentCitizenCount() / Math.max(4, colony.getCitizenManager().getMaxCitizens()));
            trySpawnChild();
        }
    }

public void trySpawnChild()
    {
        // Spawn a child when adults are present
        if (colony.getSettings().getSetting(BuildingTownHall.MOVE_IN).getValue() && colony.getCitizenManager().getCurrentCitizenCount() < colony.getCitizenManager().getMaxCitizens() && colony.getCitizenManager().getCurrentCitizenCount() >= Math.min(MIN_SIZE_FOR_REPRO, MinecoloniesAPIProxy.getInstance().getConfig().getServer().initialCitizenAmount.get()))
        {
            if (!checkForBioParents())
            {
                return;
            }

            final IBuilding newHome = colony.getServerBuildingManager().getHouseWithSpareBed();
            if (newHome == null)
            {
                return;
            }

            final LivingBuildingModule module = newHome.getFirstModuleOccurance(LivingBuildingModule.class);
            final List<ICitizenData> assignedCitizens = module.getAssignedCitizen();
            assignedCitizens.removeIf(ICitizen::isChild);

            boolean isOnlyChildInColony = true;
            for (final ICitizenData data : colony.getCitizenManager().getCitizens())
            {
                if (data.isChild())
                {
                    isOnlyChildInColony = false;
                    break;
                }
            }

            final ICitizenData newCitizen = colony.getCitizenManager().createAndRegisterCivilianData();
            ICitizenData firstParent;
            ICitizenData secondParent;
            if (!assignedCitizens.isEmpty())
            {
                firstParent = assignedCitizens.get(random.nextInt(assignedCitizens.size()));
                secondParent = firstParent.getPartner();
                if (secondParent == null)
                {
                    assignedCitizens.removeIf(cit -> cit.getPartner() != null || cit.getName().equals(firstParent.getName()) || cit.isRelatedTo(firstParent) || cit.isChild());
                    if (assignedCitizens.size() > 0 && random.nextBoolean())
                    {
                        secondParent = assignedCitizens.get(random.nextInt(assignedCitizens.size()));
                    }
                    else
                    {
                        final BlockPos altPos = colony.getServerBuildingManager().getRandomBuilding(b -> b.hasModule(LivingBuildingModule.class) && !b.getPosition().equals(newHome.getPosition()) && BlockPosUtil.getDistance2D(b.getPosition(), newHome.getPosition()) < 50);
                        if (altPos != null)
                        {
                            final IBuilding building = colony.getServerBuildingManager().getBuilding(altPos);
                            final LivingBuildingModule altModule = building.getFirstModuleOccurance(LivingBuildingModule.class);

                            final List<ICitizenData> newAssignedCitizens = altModule.getAssignedCitizen();
                            newAssignedCitizens.removeIf(cit -> cit.isChild() || cit.getPartner() != null || cit.isRelatedTo(firstParent));
                            if (newAssignedCitizens.size() > 0)
                            {
                                secondParent = newAssignedCitizens.get(random.nextInt(newAssignedCitizens.size()));
                            }
                        }
                    }
                }
            }
            else
            {
                firstParent = null;
                secondParent = null;
            }

            if (secondParent != null)
            {
                firstParent.setPartner(secondParent.getId());
                secondParent.setPartner(firstParent.getId());
            }

            newCitizen.getCitizenSkillHandler().init(colony, firstParent, secondParent, random);
            newCitizen.setIsChild(true);

            final List<String> possibleSuffixes = new ArrayList<>();
            if (firstParent != null)
            {
                newCitizen.addSiblings(firstParent.getChildren().toArray(new Integer[0]));
                firstParent.addChildren(newCitizen.getId());
                possibleSuffixes.add(firstParent.getTextureSuffix());
            }

            if (secondParent != null)
            {
                newCitizen.addSiblings(secondParent.getChildren().toArray(new Integer[0]));
                secondParent.addChildren(newCitizen.getId());
                possibleSuffixes.add(secondParent.getTextureSuffix());
            }

            newCitizen.setParents(firstParent == null ? "" : firstParent.getName(), secondParent == null ? "" : secondParent.getName());
            newCitizen.generateName(random, firstParent == null ? "" : firstParent.getName(), secondParent == null ? "" : secondParent.getName(), colony.getCitizenNameFile());

            module.assignCitizen(newCitizen);

            for (final int sibling : newCitizen.getSiblings())
            {
                final ICitizenData siblingData = colony.getCitizenManager().getCivilian(sibling);
                if (siblingData != null)
                {
                    siblingData.addSiblings(newCitizen.getId());
                }
            }

            if (possibleSuffixes.contains("_w") && possibleSuffixes.contains("_d"))
            {
                possibleSuffixes.add("_b");
            }

            if (possibleSuffixes.isEmpty())
            {
                possibleSuffixes.addAll(SUFFIXES);
            }

            newCitizen.setSuffix(possibleSuffixes.get(random.nextInt(possibleSuffixes.size())));

            final int populationCount = colony.getCitizenManager().getCurrentCitizenCount();
            AdvancementUtils.TriggerAdvancementPlayersForColony(colony, playerMP -> AdvancementTriggers.COLONY_POPULATION.trigger(playerMP, populationCount));

            colony.getCitizenManager().spawnOrCreateCitizen(newCitizen, colony.getWorld(), newHome.getPosition());
            if (isOnlyChildInColony)
            {
                MessageUtils.format(MESSAGE_NEW_CHILD_BORN, newCitizen.getName(), colony.getName()).sendTo(colony).forManagers();
            }

            colony.getEventDescriptionManager().addEventDescription(new CitizenBornEvent(newHome.getPosition(), newCitizen.getName()));
            colony.getStatisticsManager().increment(BIRTH, colony.getDay());
        }
    }

private boolean checkForBioParents()
    {
        boolean hasMale = false;
        boolean hasFemale = false;

        for (final ICitizenData data : colony.getCitizenManager().getCitizens())
        {
            if (data.isFemale())
            {
                hasFemale = true;
            }
            else
            {
                hasMale = true;
            }

            if (hasFemale && hasMale)
            {
                return true;
            }
        }

        for (final ICivilianData data : colony.getVisitorManager().getCivilianDataMap().values())
        {
            if (data.isFemale())
            {
                hasFemale = true;
            }
            else
            {
                hasMale = true;
            }

            if (hasFemale && hasMale)
            {
                return true;
            }
        }
        return false;
    }

public void read(@NotNull final CompoundTag compound)
    {
        dimensionId = ResourceKey.create(Registries.DIMENSION, new ResourceLocation(compound.getString(TAG_DIMENSION)));

        mercenaryLastUse = compound.getLong(TAG_MERCENARY_TIME);
        additionalChildTime = compound.getInt(TAG_CHILD_TIME);

        // Permissions
        permissions.loadPermissions(compound);

        citizenManager.read(compound.getCompound(TAG_CITIZEN_MANAGER));
        visitorManager.read(compound);
        animalManager.read(compound.getCompound(TAG_ANIMAL_MANAGER));
        buildingManager.read(compound.getCompound(TAG_BUILDING_MANAGER));

        // Recalculate max after citizens and buildings are loaded.
        citizenManager.afterBuildingLoad();

        graveManager.read(compound.getCompound(TAG_GRAVE_MANAGER));

        eventManager.readFromNBT(compound);
        statisticManager.readFromNBT(compound);

        questManager.deserializeNBT(compound.getCompound(TAG_QUEST_MANAGER));
        eventDescManager.deserializeNBT(compound.getCompound(NbtTagConstants.TAG_EVENT_DESC_MANAGER));

        if (compound.contains(TAG_RESEARCH))
        {
            researchManager.readFromNBT(compound.getCompound(TAG_RESEARCH));
            // now that buildings, colonists, and research are loaded, check for new autoStartResearch.
            // this is mostly for backwards compatibility with older saves, so players do not have to manually start newly added autostart researches that they've unlocked before the update.
            researchManager.checkAutoStartResearch();
        }

        //  Workload
        workManager.read(compound.getCompound(TAG_WORK));

        wayPoints.clear();
        // Waypoints
        final ListTag wayPointTagList = compound.getList(TAG_WAYPOINT, Tag.TAG_COMPOUND);
        for (int i = 0; i < wayPointTagList.size(); ++i)
        {
            final CompoundTag blockAtPos = wayPointTagList.getCompound(i);
            final BlockPos pos = BlockPosUtil.read(blockAtPos, TAG_WAYPOINT);
            final BlockState state = NbtUtils.readBlockState(BuiltInRegistries.BLOCK.asLookup(), blockAtPos);
            wayPoints.put(pos, state);
        }

        // Free blocks
        final Set<Block> tempFreeBlocks = new HashSet<>();
        final ListTag freeBlockTagList = compound.getList(TAG_FREE_BLOCKS, Tag.TAG_STRING);
        for (int i = 0; i < freeBlockTagList.size(); ++i)
        {
            tempFreeBlocks.add(ForgeRegistries.BLOCKS.getValue(new ResourceLocation(freeBlockTagList.getString(i))));
        }
        freeBlocks = ImmutableSet.copyOf(tempFreeBlocks);

        final Set<BlockPos> tempFreePositions = new HashSet<>();
        // Free positions
        final ListTag freePositionTagList = compound.getList(TAG_FREE_POSITIONS, Tag.TAG_COMPOUND);
        for (int i = 0; i < freePositionTagList.size(); ++i)
        {
            final CompoundTag blockTag = freePositionTagList.getCompound(i);
            final BlockPos block = BlockPosUtil.read(blockTag, TAG_FREE_POSITIONS);
            tempFreePositions.add(block);
        }
        freePositions = ImmutableSet.copyOf(tempFreePositions);

        packageManager.setLastContactInHours(compound.getInt(TAG_ABANDONED));

        if (compound.contains(TAG_STYLE))
        {
            this.pack = BlueprintMapping.getStyleMapping(compound.getString(TAG_STYLE));
        }
        else
        {
            this.pack = compound.getString(TAG_PACK);
        }

        raidManager.read(compound);

        if (compound.contains(TAG_AUTO_DELETE))
        {
            this.canColonyBeAutoDeleted = compound.getBoolean(TAG_AUTO_DELETE);
        }
        else
        {
            this.canColonyBeAutoDeleted = true;
        }

        if (compound.contains(TAG_TEAM_COLOR))
        {
            // This read can occur before the world is non-null, due to Minecraft's order of operations for capabilities.
            // As a result, setColonyColor proper must wait until onWorldLoad fires.
            this.colonyTeamColor = ChatFormatting.values()[compound.getInt(TAG_TEAM_COLOR)];
        }

        if (compound.contains(TAG_FLAG_PATTERNS))
        {
            this.setColonyFlag(compound.getList(TAG_FLAG_PATTERNS, Constants.TAG_COMPOUND));
        }

        this.requestManager.reset();
        if (compound.contains(TAG_REQUESTMANAGER))
        {
            this.requestManager.deserializeNBT(compound.getCompound(TAG_REQUESTMANAGER));
        }
        this.lastOnlineTime = compound.getLong(TAG_LAST_ONLINE);
        if (compound.contains(TAG_COL_TEXT))
        {
            this.textureStyle = compound.getString(TAG_COL_TEXT);
        }
        if (compound.contains(TAG_COL_NAME_STYLE))
        {
            this.nameStyle = compound.getString(TAG_COL_NAME_STYLE);
        }

        if (compound.contains(BuildingModules.TOWNHALL_SETTINGS.key) && settingsModule != null)
        {
            settingsModule.deserializeNBT(compound.getCompound(BuildingModules.TOWNHALL_SETTINGS.key));
        }

        this.day = compound.getInt(COLONY_DAY);
        this.colonyTag = compound;

        if (compound.contains(NbtTagConstants.TAG_TRAVELLING_DATA))
        {
            this.travellingManager.deserializeNBT(compound.getCompound(NbtTagConstants.TAG_TRAVELLING_DATA));
        }

        if (compound.contains(NbtTagConstants.TAG_CONNECTION_MANAGER))
        {
            this.connectionManager.deserializeNBT(compound.getCompound(NbtTagConstants.TAG_CONNECTION_MANAGER));
        }
    }

public CompoundTag write(@NotNull final CompoundTag compound)
    {
        compound.putInt(DATA_VERSION_TAG, DATA_VERSION);

        //  Core attributes
        compound.putInt(TAG_ID, id);
        compound.putString(TAG_DIMENSION, dimensionId.location().toString());

        //  Basic data
        compound.putString(TAG_NAME, name);
        BlockPosUtil.write(compound, TAG_CENTER, center);

        compound.putLong(TAG_MERCENARY_TIME, mercenaryLastUse);

        compound.putInt(TAG_CHILD_TIME, additionalChildTime);

        // Permissions
        permissions.savePermissions(compound);

        final CompoundTag buildingCompound = new CompoundTag();
        buildingManager.write(buildingCompound);
        compound.put(TAG_BUILDING_MANAGER, buildingCompound);

        final CompoundTag citizenCompound = new CompoundTag();
        citizenManager.write(citizenCompound);
        compound.put(TAG_CITIZEN_MANAGER, citizenCompound);

        visitorManager.write(compound);

        final CompoundTag animalCompound = new CompoundTag();
        animalManager.write(animalCompound);
        compound.put(TAG_ANIMAL_MANAGER, animalCompound);

        final CompoundTag graveCompound = new CompoundTag();
        graveManager.write(graveCompound);
        compound.put(TAG_GRAVE_MANAGER, graveCompound);

        //  Workload
        @NotNull final CompoundTag workManagerCompound = new CompoundTag();
        workManager.write(workManagerCompound);
        compound.put(TAG_WORK, workManagerCompound);

        eventManager.writeToNBT(compound);
        statisticManager.writeToNBT(compound);

        compound.put(TAG_QUEST_MANAGER, questManager.serializeNBT());
        compound.put(NbtTagConstants.TAG_EVENT_DESC_MANAGER, eventDescManager.serializeNBT());
        raidManager.write(compound);

        @NotNull final CompoundTag researchManagerCompound = new CompoundTag();
        researchManager.writeToNBT(researchManagerCompound);
        compound.put(TAG_RESEARCH, researchManagerCompound);

        // Waypoints
        @NotNull final ListTag wayPointTagList = new ListTag();
        for (@NotNull final Map.Entry<BlockPos, BlockState> entry : wayPoints.entrySet())
        {
            @NotNull final CompoundTag wayPointCompound = new CompoundTag();
            BlockPosUtil.write(wayPointCompound, TAG_WAYPOINT, entry.getKey());
            wayPointCompound.put(TAG_BLOCK, NbtUtils.writeBlockState(entry.getValue()));
            wayPointTagList.add(wayPointCompound);
        }
        compound.put(TAG_WAYPOINT, wayPointTagList);

        // Free blocks
        @NotNull final ListTag freeBlocksTagList = new ListTag();
        for (@NotNull final Block block : freeBlocks)
        {
            freeBlocksTagList.add(StringTag.valueOf(ForgeRegistries.BLOCKS.getKey(block).toString()));
        }
        compound.put(TAG_FREE_BLOCKS, freeBlocksTagList);

        // Free positions
        @NotNull final ListTag freePositionsTagList = new ListTag();
        for (@NotNull final BlockPos pos : freePositions)
        {
            @NotNull final CompoundTag wayPointCompound = new CompoundTag();
            BlockPosUtil.write(wayPointCompound, TAG_FREE_POSITIONS, pos);
            freePositionsTagList.add(wayPointCompound);
        }
        compound.put(TAG_FREE_POSITIONS, freePositionsTagList);

        compound.putInt(TAG_ABANDONED, packageManager.getLastContactInHours());
        compound.put(TAG_REQUESTMANAGER, getRequestManager().serializeNBT());
        compound.putString(TAG_PACK, pack);
        compound.putBoolean(TAG_AUTO_DELETE, canColonyBeAutoDeleted);
        compound.putInt(TAG_TEAM_COLOR, colonyTeamColor.ordinal());
        compound.put(TAG_FLAG_PATTERNS, colonyFlag);
        compound.putLong(TAG_LAST_ONLINE, lastOnlineTime);
        compound.putString(TAG_COL_TEXT, textureStyle);
        compound.putString(TAG_COL_NAME_STYLE, nameStyle);
        compound.putInt(COLONY_DAY, day);

        final CompoundTag settings = new CompoundTag();
        settingsModule.serializeNBT(settings);
        compound.put(BuildingModules.TOWNHALL_SETTINGS.key, settings);

        compound.put(TAG_TRAVELLING_DATA, travellingManager.serializeNBT());
        compound.put(TAG_CONNECTION_MANAGER, connectionManager.serializeNBT());

        this.colonyTag = compound;

        isDirty = false;
        return compound;
    }

private boolean tickTravellers()
    {
        if (getTravellingManager() != null)
        {
            return !getTravellingManager().onTick();
        }
        return false;
    }

@Override
    public CompoundTag serializeNBT()
    {
        final CompoundTag nbtTagCompound = new CompoundTag();

        nbtTagCompound.putInt(TAG_ID, id);
        nbtTagCompound.putString(TAG_NAME, name);
        nbtTagCompound.putString(TAG_SUFFIX, textureSuffix);
        nbtTagCompound.putInt(TAG_SOUND_PROFILE, voiceProfile);

        nbtTagCompound.putBoolean(TAG_FEMALE, female);
        nbtTagCompound.putBoolean(TAG_PAUSED, paused);
        nbtTagCompound.putBoolean(TAG_CHILD, isChild);
        nbtTagCompound.putInt(TAG_TEXTURE, textureId);

        nbtTagCompound.put(TAG_NEW_SKILLS, citizenSkillHandler.write());

        BlockPosUtil.write(nbtTagCompound, TAG_POS, getEntity().isPresent() ? getEntity().get().blockPosition() : lastPosition);
        if (nextRespawnPos != null)
        {
            BlockPosUtil.write(nbtTagCompound, TAG_RESPAWN_POS, nextRespawnPos);
        }
        nbtTagCompound.putDouble(TAG_SATURATION, saturation);

        if (job != null)
        {
            @NotNull final Tag jobCompound = job.serializeNBT();
            nbtTagCompound.put("job", jobCompound);
        }

        citizenHappinessHandler.write(nbtTagCompound, true);
        citizenMournHandler.write(nbtTagCompound);
        citizenFoodHandler.write(nbtTagCompound);
        citizenDiseaseHandler.write(nbtTagCompound);

        inventory.write(nbtTagCompound);
        nbtTagCompound.putInt(TAG_HELD_ITEM_SLOT, inventory.getHeldItemSlot(InteractionHand.MAIN_HAND));
        nbtTagCompound.putInt(TAG_OFFHAND_HELD_ITEM_SLOT, inventory.getHeldItemSlot(InteractionHand.OFF_HAND));

        BlockPosUtil.write(nbtTagCompound, TAG_BEDS, bedPos);
        nbtTagCompound.putBoolean(TAG_ASLEEP, isAsleep);
        nbtTagCompound.putBoolean(TAG_JUST_ATE, justAte);

        @NotNull final ListTag chatTagList = new ListTag();
        for (@NotNull final IInteractionResponseHandler entry : citizenChatOptions.values())
        {
            @NotNull final CompoundTag chatOptionCompound = new CompoundTag();
            chatOptionCompound.put(TAG_CHAT_OPTION, entry.serializeNBT());
            chatTagList.add(chatOptionCompound);
        }

        nbtTagCompound.put(TAG_CHAT_OPTIONS, chatTagList);
        nbtTagCompound.putInt(TAG_JOB_STATUS, jobStatus.ordinal());

        nbtTagCompound.putString(TAG_PARENT_A, parents.getA());
        nbtTagCompound.putString(TAG_PARENT_B, parents.getB());

        @NotNull final ListTag siblingsNBT = new ListTag();
        for (final int sibling : siblings)
        {
            siblingsNBT.add(IntTag.valueOf(sibling));
        }
        nbtTagCompound.put(TAG_SIBLINGS, siblingsNBT);

        @NotNull final ListTag childrenNBT = new ListTag();
        for (final int child : children)
        {
            childrenNBT.add(IntTag.valueOf(child));
        }
        nbtTagCompound.put(TAG_CHILDREN, childrenNBT);
        nbtTagCompound.putInt(TAG_PARTNER, partner);
        nbtTagCompound.putBoolean(TAG_ACTIVE, this.isWorking);
        nbtTagCompound.putInt(TAG_LEISURE, this.leisureTime);

        @NotNull final ListTag avQuestNBT = new ListTag();
        for (final ResourceLocation quest : availableQuests)
        {
            avQuestNBT.add(StringTag.valueOf(quest.toString()));
        }
        nbtTagCompound.put(TAG_AV_QUESTS, avQuestNBT);

        @NotNull final ListTag partQuestNBT = new ListTag();
        for (final ResourceLocation quest : participatingQuests)
        {
            partQuestNBT.add(StringTag.valueOf(quest.toString()));
        }
        nbtTagCompound.put(TAG_PART_QUESTS, partQuestNBT);

        @NotNull final ListTag finishedQuestNBT = new ListTag();
        for (final ResourceLocation quest : finishedQuests)
        {
            finishedQuestNBT.add(StringTag.valueOf(quest.toString()));
        }
        nbtTagCompound.put(TAG_FINISHED_AV_QUESTS, finishedQuestNBT);

        @NotNull final ListTag finishedPartQuestNBT = new ListTag();
        for (final ResourceLocation quest : finishedQuestParticipation)
        {
            finishedPartQuestNBT.add(StringTag.valueOf(quest.toString()));
        }
        nbtTagCompound.put(TAG_FINISHED_PART_QUESTS, finishedPartQuestNBT);

        if (textureUUID != null)
        {
            nbtTagCompound.putUUID(TAG_TEXTURE_UUID, textureUUID);
        }
        return nbtTagCompound;
    }

@Override
    public void deserializeNBT(final CompoundTag nbtTagCompound)
    {
        name = nbtTagCompound.getString(TAG_NAME);
        female = nbtTagCompound.getBoolean(TAG_FEMALE);
        paused = nbtTagCompound.getBoolean(TAG_PAUSED);
        isChild = nbtTagCompound.getBoolean(TAG_CHILD);
        textureId = nbtTagCompound.getInt(TAG_TEXTURE);

        if (nbtTagCompound.contains(TAG_SUFFIX))
        {
            textureSuffix = nbtTagCompound.getString(TAG_SUFFIX);
        }
        else
        {
            textureSuffix = SUFFIXES.get(random.nextInt(SUFFIXES.size()));
        }

        if (nbtTagCompound.contains(TAG_SOUND_PROFILE))
        {
            voiceProfile = nbtTagCompound.getInt(TAG_SOUND_PROFILE);
        }
        else
        {
            voiceProfile = random.nextInt(NUM_SOUND_PROFILES);
        }

        lastPosition = BlockPosUtil.read(nbtTagCompound, TAG_POS);

        if (nbtTagCompound.contains(TAG_RESPAWN_POS))
        {
            nextRespawnPos = BlockPosUtil.read(nbtTagCompound, TAG_RESPAWN_POS);
        }

        citizenSkillHandler.read(nbtTagCompound.getCompound(TAG_NEW_SKILLS));

        saturation = nbtTagCompound.getDouble(TAG_SATURATION);

        if (nbtTagCompound.contains("job"))
        {
            setJob(IJobDataManager.getInstance().createFrom(this, nbtTagCompound.getCompound("job")), true);
        }

        if (nbtTagCompound.contains(TAG_INVENTORY))
        {
            this.inventory.read(nbtTagCompound);
            this.inventory.setHeldItem(InteractionHand.MAIN_HAND, nbtTagCompound.getInt(TAG_HELD_ITEM_SLOT));
            this.inventory.setHeldItem(InteractionHand.OFF_HAND, nbtTagCompound.getInt(TAG_OFFHAND_HELD_ITEM_SLOT));
        }

        if (name.isEmpty())
        {
            name = generateName(random, isFemale(), getColony(), getColony().getCitizenNameFile());
        }

        if (nbtTagCompound.contains(TAG_ASLEEP))
        {
            bedPos = BlockPosUtil.read(nbtTagCompound, TAG_BEDS);
            isAsleep = nbtTagCompound.getBoolean(TAG_ASLEEP);
        }

        if (nbtTagCompound.contains(TAG_JUST_ATE))
        {
            justAte = nbtTagCompound.getBoolean(TAG_JUST_ATE);
        }

        //  Citizen chat options.
        if (nbtTagCompound.contains(TAG_CHAT_OPTIONS))
        {
            final ListTag handlerTagList = nbtTagCompound.getList(TAG_CHAT_OPTIONS, Tag.TAG_COMPOUND);
            for (int i = 0; i < handlerTagList.size(); ++i)
            {
                try
                {
                    final ServerCitizenInteraction handler =
                        (ServerCitizenInteraction) MinecoloniesAPIProxy.getInstance()
                            .getInteractionResponseHandlerDataManager()
                            .createFrom(this, handlerTagList.getCompound(i).getCompound(TAG_CHAT_OPTION));
                    citizenChatOptions.put(handler.getId(), handler);
                }
                catch (final Exception ex)
                {
                    Log.getLogger().warn("Failed to load Interaction for a quest. Did the quest vanish?", ex);
                }
            }
        }

        this.citizenHappinessHandler.read(nbtTagCompound, true);
        this.citizenMournHandler.read(nbtTagCompound);
        this.citizenFoodHandler.read(nbtTagCompound);
        citizenDiseaseHandler.read(nbtTagCompound);

        if (nbtTagCompound.contains(TAG_LEVEL_MAP) && !nbtTagCompound.contains(TAG_NEW_SKILLS))
        {
            citizenSkillHandler.init((int) citizenHappinessHandler.getHappiness(getColony(), this));
            final Map<String, Integer> levels = new HashMap<>();
            final ListTag levelTagList = nbtTagCompound.getList(TAG_LEVEL_MAP, Tag.TAG_COMPOUND);
            for (int i = 0; i < levelTagList.size(); ++i)
            {
                final CompoundTag levelExperienceAtJob = levelTagList.getCompound(i);
                final String jobName = levelExperienceAtJob.getString(TAG_NAME);
                final int level = Math.min(levelExperienceAtJob.getInt(TAG_LEVEL), MAX_CITIZEN_LEVEL);
                levels.put(jobName, level);
            }

            for (final Map.Entry<String, Integer> entry : levels.entrySet())
            {
                final Skill primary = Skill.values()[random.nextInt(Skill.values().length)];
                final Skill secondary = Skill.values()[random.nextInt(Skill.values().length)];

                citizenSkillHandler.incrementLevel(primary, entry.getValue() / 2);
                citizenSkillHandler.incrementLevel(secondary, entry.getValue() / 4);
            }
        }

        if (nbtTagCompound.contains(TAG_JOB_STATUS))
        {
            this.jobStatus = JobStatus.values()[nbtTagCompound.getInt(TAG_JOB_STATUS)];
        }
        else if (nbtTagCompound.getBoolean(TAG_IDLE))
        {
            this.jobStatus = JobStatus.STUCK;
        }

        final String parentA = nbtTagCompound.getString(TAG_PARENT_A);
        final String parentB = nbtTagCompound.getString(TAG_PARENT_B);

        this.parents = new Tuple<>(parentA, parentB);
        @NotNull final ListTag siblingsNBT = nbtTagCompound.getList(TAG_SIBLINGS, Tag.TAG_INT);
        for (int i = 0; i < siblingsNBT.size(); i++)
        {
            siblings.add(siblingsNBT.getInt(i));
        }

        @NotNull final ListTag childrenNBT = nbtTagCompound.getList(TAG_CHILDREN, Tag.TAG_INT);
        for (int i = 0; i < childrenNBT.size(); i++)
        {
            children.add(childrenNBT.getInt(i));
        }

        partner = nbtTagCompound.getInt(TAG_PARTNER);
        this.isWorking = nbtTagCompound.getBoolean(TAG_ACTIVE);
        this.leisureTime = nbtTagCompound.getInt(TAG_LEISURE);

        @NotNull final ListTag availQuestNbt = nbtTagCompound.getList(TAG_AV_QUESTS, TAG_STRING);
        for (int i = 0; i < availQuestNbt.size(); i++)
        {
            availableQuests.add(new ResourceLocation(availQuestNbt.getString(i)));
        }

        @NotNull final ListTag partQuestsNbt = nbtTagCompound.getList(TAG_PART_QUESTS, TAG_STRING);
        for (int i = 0; i < partQuestsNbt.size(); i++)
        {
            participatingQuests.add(new ResourceLocation(partQuestsNbt.getString(i)));
        }

        @NotNull final ListTag finQuestNbt = nbtTagCompound.getList(TAG_FINISHED_AV_QUESTS, TAG_STRING);
        for (int i = 0; i < finQuestNbt.size(); i++)
        {
            finishedQuests.add(new ResourceLocation(finQuestNbt.getString(i)));
        }

        @NotNull final ListTag finPartQuestsNbt = nbtTagCompound.getList(TAG_FINISHED_PART_QUESTS, TAG_STRING);
        for (int i = 0; i < finPartQuestsNbt.size(); i++)
        {
            finishedQuestParticipation.add(new ResourceLocation(finPartQuestsNbt.getString(i)));
        }

        if (nbtTagCompound.contains(TAG_TEXTURE_UUID))
        {
            this.textureUUID = nbtTagCompound.getUUID(TAG_TEXTURE_UUID);
        }
    }

@Override
    public void updateEntityIfNecessary()
    {
        if (getEntity().isPresent())
        {
            final Entity entity = getEntity().get();
            if (entity.isAlive() && WorldUtil.isEntityBlockLoaded(entity.level, entity.blockPosition()))
            {
                return;
            }

            setEntity(null);
        }

        //Check if we are traveling, we don't spawn an entity if we are traveling.
        if (getColony().getTravellingManager().isTravelling(this))
        {
            return;
        }

        boolean spawnVisible;
        //Okey we are either just done traveling or the entity disappeared, lets check if we just finished traveling.
        final Optional<BlockPos> travelingTargetCandidate = getColony().getTravellingManager().getTravellingTargetFor(this);
        if (travelingTargetCandidate.isPresent())
        {
            //We just finished traveling, lets spawn the entity by setting the nextRespawnPosition.
            getColony().getTravellingManager().finishTravellingFor(this);
            nextRespawnPos = travelingTargetCandidate.get();
            spawnVisible = false;
            lastPosition = nextRespawnPos;
        }
        else
        {
            spawnVisible = true;
        }

        List<BlockPos> spawnPositions = new ArrayList<>();
        if (nextRespawnPos != null)
        {
            spawnPositions.add(nextRespawnPos);
        }
        spawnPositions.add(lastPosition);
        if (getWorkBuilding() != null)
        {
            spawnPositions.add(getWorkBuilding().getPosition());
        }
        if (getHomeBuilding() != null)
        {
            spawnPositions.add(getHomeBuilding().getPosition());
        }

        colony.getCitizenManager().spawnOrCreateCivilian(this, colony.getWorld(), spawnPositions, true);

        if (nextRespawnPos != null)
        {
            getEntity().ifPresent(entity -> {
                entity.getCitizenJobHandler().setModelDependingOnJob(getJob());
                if (!spawnVisible)
                {
                    entity.setInvisible(true);
                    entity.setPos(nextRespawnPos.getX(), nextRespawnPos.getY(), nextRespawnPos.getZ());
                }
                nextRespawnPos = null;
            });
        }
    }

