			entity = world.getEntityByID(x);
			if (entity instanceof EntityDraeton)
				return new ContainerDraetonUpgrades(player.inventory, (EntityDraeton)entity);
			break;

		case GUI_FISHING_TACKLE_BOX:
			if (tile instanceof TileEntityFishingTackleBox)
				return new ContainerFishingTackleBox(player, (TileEntityFishingTackleBox) tile);
			break;

		case GUI_SMOKING_RACK:
			if (tile instanceof TileEntitySmokingRack)
				return new ContainerSmokingRack(player, (TileEntitySmokingRack) tile);
			break;

		case GUI_FISH_TRIMMING_TABLE:
			if (tile instanceof TileEntityFishTrimmingTable)
				return new ContainerFishTrimmingTable(player, (TileEntityFishTrimmingTable) tile);
			break;

		case GUI_CRAB_POT_FILTER:
			if (tile instanceof TileEntityCrabPotFilter)
				return new ContainerCrabPotFilter(player, (TileEntityCrabPotFilter) tile);
			break;

		case GUI_AMPHIBIOUS_ARMOR: {
			ItemStack item = player.getHeldItemMainhand();
			String name = item.hasDisplayName() ? item.getDisplayName() : "container.bl.amphibious_armour";
			if (!item.isEmpty() && item.getItem() instanceof ItemAmphibiousArmor)
				return new ContainerAmphibiousArmor(player, new InventoryAmphibiousArmor(item, name));
			break;
		}

		case GUI_SILK_BUNDLE: {
			ItemStack item = player.getHeldItemMainhand();
			if(item.isEmpty() || !(item.getItem() instanceof ItemSilkBundle)) {
				item = player.getHeldItemOffhand();
			}
			if(!item.isEmpty() && item.getItem() instanceof ItemSilkBundle) {
				String name = item.hasDisplayName() ? item.getDisplayName() : "container.bl.silk_bundle";
				return new ContainerSilkBundle(player, player.inventory, new InventorySilkBundle(item, 4, name));
			}
			break;
		}
		}
		return null;
	}

@Override
	public void readEntityFromNBT(NBTTagCompound nbt) {
		super.readEntityFromNBT(nbt);
		String s;
		if (nbt.hasKey("OwnerUUID", 8))
			s = nbt.getString("OwnerUUID");
		else {
			String s1 = nbt.getString("Owner");
			s = PreYggdrasilConverter.convertMobOwnerIfNeeded(getServer(), s1);
		}
		if (!s.isEmpty()) {
			try {
				setOwnerId(UUID.fromString(s));
			} catch (Throwable e) {}
		}

		setHasHatched(nbt.getBoolean("Hatched"));
		setHatchTick(nbt.getInteger("HatchTick"));
		setRising(nbt.getBoolean("Rising"));
		setRiseCount(nbt.getInteger("RisingCount"));
		setIsHungry(nbt.getBoolean("Hungry"));
		setAmountEaten(nbt.getInteger("FoodEaten"));
		setEatingCooldown(nbt.getInteger("EatingCooldown"));
		setIsTransforming(nbt.getBoolean("Transforming"));
		setTransformCount(nbt.getInteger("TransformCount"));
		this.facing = EnumFacing.VALUES[nbt.getInteger("Facing")];
		setElectricBoogaloo(nbt.getBoolean("Electric"));
		setIsWild(nbt.getBoolean("Wild"));

		NBTTagCompound nbtFood = (NBTTagCompound) nbt.getTag("Items");
		ItemStack stack = new ItemStack(ItemRegistry.SNAIL_FLESH_RAW);
		if(nbtFood != null)
			stack = new ItemStack(nbtFood);
		setFoodCraved(stack);
	}

